'Custom_SMS_Payload' => 'የጥያቄ ይዘት (Payload)',
'Custom_SMS_Add_Header' => 'ራስጌ ጨምር',
'Custom_SMS_Add_Field' => 'መስክ ጨምር',
'Custom_SMS_Placeholders' => 'የሚገኙ ቦታ ያዦች',
'Custom_SMS_Payload_Hint' => 'የጥያቄውን አካል መስኮች ይግለጹ። {phone}፣ {message} እና {sender}ን እንደ ቦታ ያዦች ይጠቀሙ፤ በሚላክበት ጊዜ በትክክለኛ እሴቶች ይተካሉ።',
'Custom_SMS_Guide_Title' => 'እንዴት ማዋቀር እንደሚቻል',
'Custom_SMS_Guide_Intro' => 'HTTP API ያለው ማንኛውም የSMS አቅራቢ ሊገናኝ ይችላል። የአቅራቢዎን የAPI ሰነድ ይክፈቱ፣ የመድረሻውን (endpoint)፣ የዘዴውን እና የመስኮቹን ስሞች ይቅዱ፣ ከዚያ ቦታ ያዦቹን በመጠቀም ከታች ያዛምዷቸው።',
'Custom_SMS_Guide_Placeholder_Phone' => 'የተቀባዩ ስልክ ቁጥር',
'Custom_SMS_Guide_Placeholder_Message' => 'የSMS ጽሑፉ',
'Custom_SMS_Guide_Placeholder_Sender' => 'ከላይ የገባው የላኪ መለያ (Sender ID)',
'Custom_SMS_Guide_Api_Url' => 'ከአቅራቢዎ ሰነድ የተገኘው ሙሉ የመድረሻ URL፣ ለምሳሌ https://api.provider.com/sms/send። ቦታ ያዦች በቀጥታ በURL ውስጥም ይፈቀዳሉ፣ ለምሳሌ ...?to={phone}&text={message}።',
'Custom_SMS_Guide_Method' => 'POST በጣም የተለመደው ነው። GETን ይምረጡ አቅራቢዎ ሁሉንም ነገር በURL ውስጥ የሚጠብቅ ከሆነ ብቻ — የይዘት (payload) መስኮቹ ያኔ እንደ የመጠይቅ ግቤቶች (query parameters) ይላካሉ።',
'Custom_SMS_Guide_Content_Type' => '"json" ይዘቱን እንደ JSON አካል (application/json) ይልካል። "form" እንደ ተለመደው የHTML ቅጽ (application/x-www-form-urlencoded) ይልካል። አቅራቢዎ የትኛውን እንደሚጠብቅ ያረጋግጡ፤ ለGET ግምት ውስጥ አይገባም።',
'Custom_SMS_Guide_Sender' => 'የጸደቀው የላኪ መለያዎ (Sender ID) ወይም የመላኪያ ስልክ ቁጥርዎ። የሚሞላው የ{sender} ቦታ ያዥን ብቻ ነው — እንዲላክ በይዘቱ (payload)፣ በራስጌዎቹ ወይም በURL ውስጥ ጥቅም ላይ መዋል አለበት።',
'Custom_SMS_Guide_Success_Keyword' => 'አማራጭ ቢሆንም ይመከራል። አንዳንድ አቅራቢዎች መላክ ሳይሳካ እንኳ "200 OK" ብለው ይመልሳሉ። በተሳካ ምላሽ ውስጥ ብቻ የሚታይ ቃል ወይም ቁራጭ ያስገቡ (ለምሳሌ success)። ምላሹ ካልያዘው SMSው እንዳልተሳካ ይቆጠራል።',
'Custom_SMS_Guide_Headers' => 'አቅራቢዎ የሚጠይቃቸው የማረጋገጫ ራስጌዎች፣ ለምሳሌ Authorization = Bearer YOUR_API_KEY ወይም Api-Key = YOUR_API_KEY። Content-Type አይጨምሩ — በራስ-ሰር ይዘጋጃል።',
'Custom_SMS_Guide_Payload' => 'የጥያቄው አካል መስኮች፣ ስማቸው በአቅራቢዎ ሰነድ ውስጥ እንዳለው በትክክል። ቦታ ያዦቹን እንደ እሴቶች ይጠቀሙ፣ ለምሳሌ to = {phone}, message = {message}, from = {sender}።',
'Custom_SMS_Guide_Example' => 'ሙሉ ምሳሌ',
'Custom_SMS_Guide_Default_Note' => 'ካስቀመጡ በኋላ በዚህ ገጽ አናት ላይ "custom"ን እንደ ነባሪ የSMS መግቢያ ይምረጡ እና ያስገቡ — አለበለዚያ SMS ቀደም ሲል የተመረጠውን መግቢያ መጠቀሙን ይቀጥላል።',
