'Ord_Guide_Payment_Intro' => 'ይህ አምድ ደንበኛው በክፍያ ወቅት እንዴት ለመክፈል እንደመረጠ ይመዘግባል። በሱቅ ገጹ የሚወሰን ሲሆን ከዚህ ገጽ ሊስተካከል አይችልም — ገንዘቡ ራሱ የሚከታተለው ትዕዛዙን ማረጋገጥ በሚፈጥረው ሽያጭ ላይ ነው።',
