'Ord_Guide_Lifecycle_Cancelled' => 'ትዕዛዙ ከመረጋገጡ በፊት ተሰርዟል፤ ስለዚህ ምንም ሽያጭ አልተፈጠረም፣ ክምችትም አልተቀነሰም።',
'Ord_Guide_Lifecycle_Confirmed' => 'ትዕዛዙን ተቀብለዋል። Stocky በመረጡት መጋዘን ውስጥ ሽያጭ ይፈጥራል እና ክምችቱን ይቀንሳል — የክምችት፣ የክፍያ እና የትርፍ ሪፖርቶችዎ መረጃቸውን የሚያነቡት ከዚህ ሽያጭ ነው።',
'Ord_Guide_Lifecycle_Delivered' => 'ደንበኛው ትዕዛዙን ተቀብሏል። የመመለሻ ጊዜው የሚጀምረው ከዚህ ነው።',
'Ord_Guide_Lifecycle_Pending' => 'ግምገማዎን የሚጠብቅ አዲስ ትዕዛዝ። ሊረጋገጥ ወይም ሊሰረዝ የሚችለው በመጠባበቅ ላይ ያለ ትዕዛዝ ብቻ ነው።',
'Ord_Guide_Lifecycle_Shipped' => 'ትዕዛዙን ልከዋል። ይህ የማድረስ ሂደት ብቻ ነው፤ ክምችቱ ትዕዛዙን ሲያረጋግጡ ቀድሞ ተቀንሷል።',
'Ord_Guide_MarkPaid_Step1' => 'መጀመሪያ ትዕዛዙን እዚህ ያረጋግጡ — ሽያጩን የሚፈጥረው ማረጋገጡ ነው።',
'Ord_Guide_MarkPaid_Step2' => 'ሽያጮች > ሁሉም ሽያጮች የሚለውን ይክፈቱ እና ያንን ሽያጭ ያግኙ (ተመሳሳይ ደንበኛ ነው፤ የዝርዝሮች ገጹም የመጣበትን የኦንላይን ትዕዛዝ ያሳያል)።',
'Ord_Guide_MarkPaid_Step3' => 'የረድፍ ተግባራት ምናሌን ይክፈቱ እና "ክፍያ ፍጠር" የሚለውን ይምረጡ።',
'Ord_Guide_MarkPaid_Step4' => 'መጠኑን፣ የክፍያ ዘዴውን እና ቀኑን ያስገቡ፣ ከዚያ ያስቀምጡ። እንደ መጠኑ ሽያጩ በራሱ ወደ "ከፊል" ወይም "ተከፍሏል" ይቀየራል።',
'Ord_Guide_Note_Cancel' => 'መሰረዝ የሚቻለው ትዕዛዙ ገና በመጠባበቅ ላይ እያለ ብቻ ነው። ከተረጋገጠ በኋላ በሽያጩ ወይም በደንበኛ መመለሻ በኩል ይቀልብሱት።',
'Ord_Guide_Note_Flagged' => '"ተጠቁሟል" የሚል መለያ ትዕዛዙ በክፍያ ወቅት የማጭበርበር ፍተሻን እንዳስነሳ ያሳያል። ምክንያቱን ለማየት ጠቋሚውን በመለያው ላይ ያድርጉ፤ ከማረጋገጥዎ በፊትም ትዕዛዙን ይገምግሙ።',
