'Cr_Guide_Step_Account_Help' => 'ኩሪየርዎን ይምረጡ እና የAPI ቁልፎቹን ከዳሽቦርዱ ይለጥፉ። ብዙ መለያዎች መኖራቸው ችግር የለውም፣ ለምሳሌ ለእያንዳንዱ መጋዘን አንድ።',
'Cr_Guide_Step_Test' => 'ግንኙነቱን ይፈትሹ',
