'Cr_Guide_Step_Webhook' => 'የwebhook URL ያስመዝግቡ',
'Cr_Guide_Step_Webhook_Help' => 'ዝማኔዎችን የሚልኩ ኩሪየሮች ሁኔታዎች ወዲያውኑ እንዲቀየሩ የመለያውን webhook URL (ከታች የተዘረዘረውን) ይፈልጋሉ። ሌሎቹ በተወሰነ የጊዜ ሰሌዳ ይፈተሻሉ።',
'Cr_Guide_Step_Cod' => 'የCOD ክፍያዎች የሚገቡበትን ይምረጡ',
