'Cr_Guide_Step_Book_Help' => 'በሽያጮች ዝርዝር ውስጥ የአንድን ሽያጭ ምናሌ ከፍተው «ወደ ኩሪየር ላክ»ን ይምረጡ፣ ወይም በርካታ ሽያጮችን ምልክት አድርገው በአንድ ጊዜ ይላኩ።',
'Cr_Guide_Step_Errors' => 'ስህተቶችን ይከታተሉ',
