'Cr_Guide_How' => 'እንዴት እንደሚመዘገብ',
'Cr_Guide_How_It_Works' => 'እንዴት እንደሚሠራ',
'Cr_Guide_Meaning' => 'ትርጉም',
'Cr_Guide_T_Statuses' => 'ሁኔታዎች',
'Cr_Guide_Statuses_Note' => 'ሁኔታዎች ወደፊት ብቻ ይሄዳሉ፤ ስለዚህ ዘግይቶ የሚመጣ ዝማኔ እሽግን ወደኋላ አይመልስም። የደረሰ እሽግ ግን አሁንም በመመለስ ላይ ወይም ተመልሷል ተብሎ ሊገለጽ ይችላል።',
'Cr_Guide_S_booked' => 'ኩሪየሩ ትዕዛዙን ተቀብሏል፤ እስካሁን ማንም አልወሰደውም። ማስያዣ መሰረዝ የሚቻለው አሁን ብቻ ነው።',
'Cr_Guide_S_picked_up' => 'ኩሪየሩ እሽጉን ወስዷል።',
'Cr_Guide_S_in_transit' => 'በማዕከላት መካከል በመጓዝ ላይ፣ በጉምሩክ ውስጥ ወይም ተይዟል።',
'Cr_Guide_S_out_for_delivery' => 'ዛሬ ከአድራሹ ጋር ነው።',
'Cr_Guide_S_failed_attempt' => 'ቤት አልተገኘም፣ እምቢ ተብሏል ወይም አድራሻው ተሳስቷል። ኩሪየሩ እንደገና ይሞክራል ወይም ይመልሰዋል።',
'Cr_Guide_S_delivered' => 'ለደንበኛው ተሰጥቷል። የCOD መጠን በኩሪየሩ እንደተሰበሰበ ይቆጠራል።',
'Cr_Guide_S_returning' => 'ወደ እርስዎ በመመለስ ላይ ነው።',
'Cr_Guide_S_returned' => 'ወደ እርስዎ ተመልሷል፤ በ«ለመገምገም የተመለሱ» ውስጥ ይጠብቃል፣ ወይም በራስ-ሰር ወደ ክምችት ይመለሳል።',
'Cr_Guide_S_cancelled' => 'ማስያዣው ተሰርዟል።',
'Cr_Guide_T_Booking' => 'ትዕዛዞችን ማስያዝ',
'Cr_Guide_B_Booking' => '«ወደ ኩሪየር ላክ» ቅጹን ከሽያጩ ይሞላል፦ ተቀባይ፣ አድራሻ፣ አሁንም ያልተከፈለውን መጠን እንደ COD፣ እና የምርቶቹን ክብደት። የራሳቸው የከተሞች ዝርዝር ያላቸው ኩሪየሮች መምረጫ ያሳያሉ፣ ምርጫዎም ለዚያ ከተማ ይታወሳል። አሰባሳቢዎች፣ DHL፣ FedEx፣ UPS እና Lalamove «ዋጋዎችን አወዳድር» ያቀርባሉ፦ ዋጋ ይምረጡ እና «አስይዝ» ይገዛዋል። በርካታ ሽያጮች ከሽያጮች ዝርዝር በአንድ ጊዜ ሊያዙ ይችላሉ።',
'Cr_Guide_T_Cod' => 'በማድረስ ጊዜ ክፍያ (COD)',
'Cr_Guide_B_Cod' => 'የCOD እሽግ ከ«አልተሰበሰበም» ወደ «በኩሪየር ተሰብስቧል» (ሲደርስ) ከዚያም ወደ «ለእርስዎ ተከፍሏል» ይሸጋገራል። ክፍያዎችን የሚያሳውቁ ኩሪየሮች የመጨረሻውን እርምጃ ራሳቸው ይቀይራሉ፤ ለሌሎቹ «COD አዘምን»ን ይጠቀሙ። በኩሪየር ቅንብሮች ውስጥ ሂሳብ ከተመረጠ፣ ክፍያው በሽያጩ ላይ እንደ ክፍያ ይመዘገባል። እሽግ ከተጠናቀቀ በኋላ የኩሪየር ክፍያዎች እንደ ወጪ ሊቀመጡ ይችላሉ።',
'Cr_Guide_T_Returns' => 'የተመለሱ እሽጎች',
'Cr_Guide_B_Returns' => 'በነባሪ የተመለሰ እሽግ በኩሪየር መላኪያዎች ውስጥ በ«ለመገምገም የተመለሱ» ስር ይጠብቃል። «ወደ ክምችት መልስ» ለሙሉ ትዕዛዙ የሽያጭ መመለሻ ይፈጥራል እና እቃዎቹን ወደ ክምችት ይመልሳል፤ «አሰናብት» ምንም አይመልስም፣ ለተበላሹ ወይም ለጠፉ እሽጎች። በምትኩ የኩሪየር ቅንብሮች በራስ-ሰር ወደ ክምችት እንዲመልሱ ማድረግ ይቻላል።',
'Cr_Guide_T_Customers' => 'የደንበኛ መልዕክቶች እና የመከታተያ ገጽ',
'Cr_Guide_B_Customers' => 'በኩሪየር ቅንብሮች ውስጥ ያሉ የደንበኛ ማሳወቂያዎች ምልክት ባደረጓቸው ሁኔታዎች ላይ SMS፣ ኢሜይል ወይም WhatsApp በራስዎ ጽሑፍ ለእያንዳንዱ እሽግ አንድ ጊዜ ይልካሉ። በመስመር ላይ ሱቅዎ ውስጥ ያለው የመከታተያ ገጽ ደንበኞች እሽግን በመከታተያ ቁጥር፣ ወይም በትዕዛዝ ቁጥር እና ስልክ እንዲከታተሉ ያስችላል። ብዙ ጊዜ እሽግ የሚመልሱ ደንበኞች ሲያስይዙ የመመለስ ስጋት ምልክት ያገኛሉ።',
'Cr_Guide_T_Labels' => 'ሌብሎች',
'Cr_Guide_B_Labels' => '«ሌብል አትም» ኩሪየሩ የራሱን ሌብል ሲያወጣ (PDF፣ አገናኝ ወይም ምስል) ያንኑ ይሰጣል፤ አለበለዚያ የመከታተያ ባርኮድ እና የሚሰበሰበውን መጠን የያዘ የStocky ሌብል ይሰጣል። ለማተም ለዚህ ጣቢያ ብቅ-ባዮችን (pop-ups) ይፍቀዱ። DHL፣ FedEx እና UPS ሌብላቸውን በማስያዝ ጊዜ አንድ ጊዜ ብቻ ይሰጣሉ፣ Stocky ደግሞ እንደገና ለማተም ያስቀምጠዋል።',
'Cr_Guide_T_Faq' => 'ችግር መፍቻ',
'Cr_Guide_Q_Test' => 'የግንኙነት ሙከራ አልተሳካም',
'Cr_Guide_A_Test' => 'የሙከራ ቁልፎች ከሙከራ ሁነታ ጋር፣ ቀጥታ ቁልፎች ደግሞ ከቀጥታ ጋር ይሄዳሉ፤ የተለያዩ ናቸው። ትክክለኛውን ምክንያት ለማወቅ የኩሪየር መዝገቦችን ከፍተው የኩሪየሩን ምላሽ ያንብቡ።',
'Cr_Guide_Q_City' => 'ኩሪየሩ ከተማውን ወይም አድራሻውን አይቀበልም',
'Cr_Guide_A_City' => 'በማስያዣ ቅጹ ውስጥ ከተማውን ከኩሪየሩ የከተሞች ዝርዝር ይምረጡ፤ ኩሪየሮች የሚቀበሉት የራሳቸውን ስሞች ብቻ ነው። በፖስታ አድራሻዎች የሚሠሩ ኩሪየሮች ክልል፣ የፖስታ ኮድ እና ባለሁለት ፊደል የአገር ኮድም ይፈልጋሉ።',
'Cr_Guide_Q_Webhook' => 'ሁኔታዎች በራሳቸው አይቀየሩም',
'Cr_Guide_A_Webhook' => 'ዝማኔ ለሚልኩ ኩሪየሮች፣ webhook URL በኩሪየሩ ዘንድ መመዝገቡን ያረጋግጡ፤ የኩሪየር መዝገቦች የተቀበሉትን እያንዳንዱን ዝማኔ ወይም ለምን ውድቅ እንደተደረገ (ለምሳሌ የተሳሳተ ሚስጥር) ያሳያሉ። ሌሎች ኩሪየሮች በኩሪየር ቅንብሮች ውስጥ ባለው የጊዜ ሰሌዳ ይፈተሻሉ፤ «ሁኔታን አሁን ፈትሽ» ደግሞ ወዲያውኑ ይጠይቃል።',
'Cr_Guide_Q_Stuck' => 'መላኪያው የሁኔታ ፍተሻ ስህተት ያሳያል',
'Cr_Guide_A_Stuck' => 'ኩሪየሩ የመጨረሻዎቹን ፍተሻዎች አልተቀበለም፤ ምክንያቱ በመላኪያው ላይ እና በኩሪየር መዝገቦች ውስጥ አለ። ከተደጋጋሚ ውድቀቶች በኋላ መላኪያው በራስ-ሰር መፈተሹ ይቆማል፦ ምክንያቱን ያስተካክሉ፣ ከዚያም «ሁኔታን አሁን ፈትሽ»ን ይጠቀሙ።',
'Cr_Guide_Q_Label' => 'ሌብል ሲታተም ምንም አይከፈትም',
'Cr_Guide_A_Label' => 'አሳሽዎ ብቅ-ባዩን አግዶታል። ለዚህ ጣቢያ ብቅ-ባዮችን ይፍቀዱ እና እንደገና ይሞክሩ።',
'Cr_Guide_Q_Cod' => 'የCOD ክፍያ በሽያጩ ላይ አልተመዘገበም',
'Cr_Guide_A_Cod' => 'በኩሪየር ቅንብሮች ውስጥ በማድረስ ጊዜ ክፍያ መቀየሪያው እንዲበራ እና ሂሳብ እንዲመረጥ ይፈልጋል። ሂሳብ ካልተመረጠ ክፍያዎች እንደተከፈሉ ብቻ ምልክት ይደረግባቸዋል።',
