'Restrict_Master_Data_By_Warehouse_Help' => 'ሲበራ፣ ለተወሰኑ መጋዘኖች የተመደበ ተጠቃሚ ከእነዚያ መጋዘኖች ጋር የተያያዙ ምርቶችን፣ ደንበኞችን፣ አቅራቢዎችን፣ ብራንዶችን እና ምድቦችን ብቻ ያያል። እስካሁን የትም ጥቅም ላይ ያልዋሉ መዝገቦች ይታያሉ፤ ስለዚህ አዲስ የተፈጠሩት ፈጽሞ አይደበቁም። ሽያጮች፣ ግዢዎች እና መመለሻዎች ሁልጊዜ የተገደቡ ናቸው፤ በዚህ መቀየሪያ አይነኩም።',
'Restrict_Products_By_Warehouse' => 'ምርቶችን በመጋዘን ገድብ',
'Restrict_Products_By_Warehouse_Help' => 'እያንዳንዱ ምርት መነሻ መጋዘን ያገኛል — የተፈጠረለትን ቅርንጫፍ። ሲበራ፣ ለተወሰኑ መጋዘኖች የተመደበ ተጠቃሚ የሚያየው፣ የሚሸጠው እና የሚያስተካክለው መነሻ መጋዘናቸው የእሱ የሆኑ ምርቶችን፣ እንዲሁም በአንዱ መጋዘኑ ውስጥ እውነተኛ ክምችት ያላቸውን ምርቶች (የተላለፉ ወይም የተገዙ) ብቻ ነው። ሁሉንም መጋዘኖች ማግኘት የሚችሉ ተጠቃሚዎች ሁልጊዜ ሁሉንም ያያሉ። የመስመር ላይ ሱቁም ተመሳሳይ ደንብ ይከተላል፦ በሱቅ ቅንብሮች ውስጥ የተመረጡትን መጋዘኖች ምርቶች ብቻ ይዘረዝራል።',
'Virtual_Combo_Stock' => 'ምናባዊ የኮምቦ ክምችት',
'Virtual_Combo_Stock_Help' => 'ሲበራ፣ የኮምቦ ምርት የራሱ ክምችት የለውም፦ ያለው መጠን የአካል ምርቶቹ አሁንም ሊሞሉት የሚችሉት የኮምቦ ብዛት ነው፣ ኮምቦ መሸጥም ከአካል ምርቶቹ ክምችት ይወስዳል። ሲጠፋ፣ ኮምቦዎች መጀመሪያ በማስተካከያ ተገጣጥመው ወደ ክምችት ይገባሉ።',
'Virtual_Combo_Stock_Warning' => 'ኮምቦዎችን ከመሸጥዎ በፊት ቢመረጥ ይሻላል። ኮምቦዎች ከተሸጡ ወይም ከተመለሱ በኋላ መቀየር፣ የእነዚያን ሰነዶች ቀጣይ ማስተካከያዎች፣ ስረዛዎች እና መመለሻዎች ክምችታቸውን በተሳሳተ መንገድ እንዲመልሱ ያደርጋል።',
'Virtual_Combo_Stock_Confirm_On_Title' => 'ምናባዊ የኮምቦ ክምችት ይብራ?',
'Virtual_Combo_Stock_Confirm_On_Body' => 'ኮምቦዎች በቀጥታ ከአካል ምርቶቻቸው ይሸጣሉ፣ የራሳቸው ክምችትም ከእንግዲህ ጥቅም ላይ አይውልም።',
'Virtual_Combo_Stock_Confirm_Off_Title' => 'ምናባዊ የኮምቦ ክምችት ይጥፋ?',
'Virtual_Combo_Stock_Confirm_Off_Body' => 'ኮምቦዎች ወደ ራሳቸው ክምችት ይመለሳሉ፤ ይህም ከመሸጣቸው በፊት ከአካል ምርቶቹ በማስተካከያ መገጣጠም አለበት።',
