'Tg_Guide_A_Title' => 'ወዲያውኑ — የሚጫን ምንም ነገር የለም',
'Tg_Guide_A_Body' => 'በStocky ውስጥ — በPOS ወይም በአስተዳደር ገጹ — የተቀመጠ ሽያጭ፣ ግዢ፣ ክፍያ ወይም ወጪ {rightAfter} በዚያው ጥያቄ ውስጥ ወደ Telegram ይላካል። cron ግቤት፣ queue worker አያስፈልግም፣ ካሽየሩም Telegramን ፈጽሞ አይጠብቅም፦ መልዕክቱ ሲላክ ሽያጩ አስቀድሞ ምላሽ አግኝቷል።',
'Tg_Guide_Right_After' => 'ልክ እንደተቀመጠ',
'Tg_Guide_B_Title' => 'የcron ግቤቱ — ለድጋሚ ሙከራዎች እና ለጀርባ ክስተቶች',
'Tg_Guide_B_Body' => 'ሁለት ዓይነት መልዕክቶች በምትኩ በTelegram የራሱ ወረፋ ላይ ይጠብቃሉ፦ ያልተሳካ መላክ (Telegram ለአፍታ የማይደረስ ሲሆን)፣ ይህም በሚቀጥሉት ጥቂት ደቂቃዎች እስከ ሦስት ተጨማሪ ጊዜ እንደገና ይሞከራል፤ እና ከአስተዳደር ገጹ ውጭ የተከሰቱ ክስተቶች — ከWooCommerce ወይም Shopify የገቡ ትዕዛዞች፣ artisan ትዕዛዞች። ይህ የcron ግቤት እነሱን ይልካል፣ ሌላ ምንም አያደርግም፦',
'Tg_Guide_B_Note' => 'በየደቂቃው ትክክል ነው፦ የሚጠብቅ ነገር የሌለበት ሩጫ ወዲያውኑ ይወጣል። በcPanel ላይ ይህ በ{cronJobs} ውስጥ ይገባል — {php} የቆየ ከሆነ ወደ PHP 8.2+ ሙሉውን መንገድ ይጠቀሙ። በWindows ላይ Task Schedulerን ይጠቀሙ፦ ፕሮግራም {php2}፣ አርጉመንቶች {args}፣ የመነሻ ፎልደር {path}።',
