'Tg_Guide_Without_Cron' => 'የcron ግቤት ባይኖርም በStocky ውስጥ የተቀመጠው ሁሉ አሁንም ወዲያውኑ ይደርሳል፤ የሚያጡት ድጋሚ ሙከራዎችን እና የገቡትን ትዕዛዞች ብቻ ነው።',
