'Tg_Guide_Err_400' => '{code} — የተሳሳተ የቻት መለያ፣ ወይም ቦቱ በቡድኑ ውስጥ የለም። ለግል ቻት መጀመሪያ ለቦቱ መልዕክት ይላኩ።',
'Tg_Guide_Err_403' => '{code} — ቦቱን ወደ ቡድኑ መልሰው ያክሉ፣ ወይም የቻናሉ አስተዳዳሪ አድርገው ያክሉ።',
'Tg_Guide_Test_Works' => 'ሙከራው ይሠራል ግን ሽያጮች አይደርሱም',
'Tg_Guide_Test_Works_Item' => '{label} — ክስተቱ ምልክት መደረጉን (ወይም {allEvents} መመረጡን) እና መቀየሪያው መብራቱን ያረጋግጡ።',
'Tg_Guide_Imported_Never' => 'የገቡ ትዕዛዞች ፈጽሞ አይደርሱም',
'Tg_Guide_Imported_Never_Item' => '{label} — ከላይ ያለው የcron ግቤት እየሠራ አይደለም።',
'Jumia_Hero_Title' => 'የJumia ገበያ ማመሳሰል',
'Jumia_Hero_Desc' => 'ዋጋዎችን እና ክምችትን ወደ Jumia Seller Center ዝርዝሮችዎ ይላኩ እና የገበያ ትዕዛዞችን እንደ ሽያጮች ያስመጡ።',
'Jumia_Api_Url_Label' => 'API URL (የአገርዎ Seller Center endpoint)',
'Jumia_Account_Email' => 'የመለያ ኢሜይል (User ID)',
'Jumia_Prices_Stock' => 'ዋጋዎች እና ክምችት',
'Jumia_Push_Card_Title' => 'ዋጋዎችን እና ክምችትን ወደ Jumia ላክ',
'Jumia_Push_Desc' => 'ከJumia ዝርዝሩ {sellerSku} ጋር የሚዛመድ SKU ላለው እያንዳንዱ ምርት (እና ቫሪያንት) የአሁኑን ዋጋ እና ብዛት ይልካል። ዝማኔዎች እንደ Seller Center feeds ይቀርባሉ እና ባልተመሳሰለ ሁኔታ (asynchronously) ይተገበራሉ — የfeed IDው በመዝገቦች ትር ውስጥ ይመዘገባል፣ በእያንዳንዱ እቃ ላይ ያሉ ውድቅቶች ደግሞ በSeller Center የfeed ሁኔታ ማያ ገጽ ላይ ይታያሉ።',
'Jumia_Push_Prices_Stock' => 'ዋጋዎችን እና ክምችትን ላክ',
'Jumia_Orders_Desc' => 'የገበያ ትዕዛዞችን እንደ ሽያጮች (እንደ {ref} ያሉ ማጣቀሻዎች) ያስመጣል፣ በSeller SKU ከምርቶችዎ ጋር ይዛመዳሉ። አስቀድመው የገቡ እና የተሰረዙ ትዕዛዞች ይዘለላሉ፤ ስለዚህ በየጊዜው ማምጣት ደህንነቱ የተጠበቀ ነው። ክፍያዎች እንደተከፈሉ ምልክት የሚደረግባቸው ለደረሱ ትዕዛዞች ብቻ ነው (Jumia በብዛት COD ይጠቀማል)።',
'Jumia_Guide_1' => 'በJumia {sellerCenter} ውስጥ Settings → {integrationMgmt}ን ከፍተው የAPI ቁልፍ ይፍጠሩ።',
'Jumia_Guide_2' => 'የአገርዎን API URL (ለምሳሌ ለናይጄሪያ {ng}፣ ለኬንያ {ke}፣ ለግብፅ {eg})፣ የSeller Center መለያ ኢሜይልዎን እና ቁልፉን ያስገቡ — ከዚያም {test}ን ያሂዱ።',
'Jumia_Guide_3' => 'የእያንዳንዱ Jumia ዝርዝር {sellerSku} ከStocky የምርት ኮድ ጋር እኩል መሆኑን ያረጋግጡ — ለክምችት መላክም ሆነ ለትዕዛዝ ማዛመድ የሚውለው መለያ ይህ ነው።',
'Jumia_Guide_4' => 'ከክምችት ለውጦች በኋላ ዋጋዎችን እና ክምችትን ይላኩ፤ ትዕዛዞችን በየጊዜው ያምጡ (በዚህ API ውስጥ Jumia webhooks የለውም)።',
'Jumia_Guide_5' => 'አዳዲስ ዝርዝሮችን መፍጠር በSeller Center ውስጥ ይቀራል — Jumia ለየምድቡ የተለዩ ባህሪያትን እና የምስል ግምገማን ይፈልጋል፤ እነዚህን በሚገባ የሚያስተናግደው የራሳቸው ፖርታል ብቻ ነው።',
'Mc_Hero_Title' => 'የMailchimp ኦዲየንስ ማመሳሰል',
'Mc_Hero_Desc' => 'በእውነተኛ ደንበኞችዎ ላይ የኢሜይል ዘመቻዎችን ማካሄድ እንዲችሉ የMailchimp ኦዲየንስን በደንበኞችዎ የተሞላ ያቆዩ።',
'Mc_Account_Audience' => 'መለያ እና ኦዲየንስ',
'Mc_Api_Key_Placeholder' => 'ለምሳሌ a1b2c3…-us14 (Account → Extras → API keys)',
'Mc_Audience' => 'ኦዲየንስ (Audience)',
'Mc_N_Members' => '({n} አባላት)',
'Mc_Load_Audiences_To_Pick' => 'አንዱን ለመምረጥ ኦዲየንሶችን ይጫኑ',
'Mc_Load_Audiences' => 'ኦዲየንሶችን ጫን',
'Mc_Double_Opt_In_Label' => 'ድርብ ፈቃድ (double opt-in) — አዳዲስ አባላት ከመቀላቀላቸው በፊት የማረጋገጫ ኢሜይል ያገኛሉ',
'Mc_Recommended_GDPR' => '(ለGDPR የሚመከር)',
'Mc_Auto_Sync_New' => 'አዳዲስ ደንበኞች ሲፈጠሩ በራስ-ሰር አመሳስል',
'Mc_With_Email' => 'ኢሜይል ያላቸው',
'Mc_Push_Desc' => 'የኢሜይል አድራሻ ያለውን እያንዳንዱን ደንበኛ (ስም እና ስልክን ጨምሮ) ወደ ተመረጠው ኦዲየንስ ያክላል ወይም ያዘምናል። ነባር አባላት የምዝገባ ሁኔታቸውን ይይዛሉ — ምዝገባውን የሰረዘ ማንም እንደገና አይመዘገብም። ኢሜይል የሌላቸው ደንበኞች አይካተቱም።',
'Mc_Double_Opt_In_Off' => 'ድርብ ፈቃድ ጠፍቷል',
'Mc_Double_Opt_In_Off_Desc' => 'አዳዲስ አባላት ያለ ማረጋገጫ ኢሜይል እንደተመዘገቡ ይታከላሉ። ይህን የሚያደርጉት የግብይት መልዕክቶችን ለመቀበል አስቀድመው ለተስማሙ ደንበኞች ብቻ ነው።',
'Mc_Guide_1' => 'በMailchimp ውስጥ {path}ን ከፍተው ቁልፍ ይፍጠሩ (በ{suffix} ያበቃል — ያ ቅጥያ የእርስዎ datacenter ነው)።',
'Mc_Guide_2' => 'ቁልፉን እዚህ ይለጥፉ፣ ያስቀምጡ፣ ከዚያም {load}ን ጠቅ ያድርጉ እና የሚሞላውን ኦዲየንስ ይምረጡ።',
'Mc_Guide_3' => 'ደንበኞችዎ ለግብይት ኢሜይሎች አስቀድመው ፈቃድ ካልሰጡ በስተቀር {doi}ን እንደበራ ይተዉት።',
'Mc_Double_Opt_In_Lower' => 'ድርብ ፈቃድ (double opt-in)',
'Mc_Guide_4' => 'ለመጀመሪያው ሙሌት {push}ን ያሂዱ፤ አዳዲስ ደንበኞች በራስ-ሰር እንዲቀላቀሉ {autoSync}ን ያብሩ።',
'Mc_Auto_Sync_Lower' => 'ራስ-ሰር ማመሳሰል',
'Mc_Consent_Matters' => 'ፈቃድ አስፈላጊ ነው',
'Mc_Consent_Desc' => 'ለግብይት ፈጽሞ ላልተስማሙ ሰዎች ኢሜይል መላክ GDPR/CAN-SPAMን ሊጥስ እና የMailchimp መለያዎ እንዲታገድ ሊያደርግ ይችላል። ድርብ ፈቃድ ማረጋገጫውን ወደ Mailchimp ያዛውራል — ደህንነቱ የተጠበቀው ነባሪ ነው።',
'Mc_No_Audiences' => 'በዚህ መለያ ላይ ምንም ኦዲየንስ አልተገኘም።',
'Presta_Hero_Desc' => 'ምርቶችን፣ ክምችትን እና ትዕዛዞችን ከPrestaShop ሱቅዎ ጋር በwebservice APIው በኩል ያመሳስሉ።',
'Presta_Webservice_Key' => 'የWebservice ቁልፍ',
'Presta_Key_Placeholder' => 'ከAdvanced Parameters → Webservice',
'Presta_Key_Help' => 'በPrestaShop ውስጥ webserviceን ያንቁ (Advanced Parameters → Webservice)፣ በproducts፣ stock_availables፣ orders እና customers ላይ ፈቃድ ያለው ቁልፍ ይፍጠሩ፣ እና እዚህ ይለጥፉት። የሚቀመጠው ለመጻፍ ብቻ ነው።',
'Presta_Shop_Language_ID' => 'የሱቅ ቋንቋ ID',
'Presta_Language_Help' => 'ምርቶች ሲላኩ ለምርት ስሞች የሚውለው የቋንቋ id (1 = የሱቁ የመጀመሪያ ቋንቋ)።',
'Presta_Push_Desc' => 'በPrestaShop ላይ የሌሉ ቀላል ምርቶችን (ከአሁኑ ክምችታቸው ጋር) ይፈጥራል። አስቀድመው የተገናኙ ምርቶች እና የቫሪያንት ምርቶች ይዘለላሉ — የምርት ዝርዝሮችን በPrestaShop ውስጥ ማስተካከልዎን ይቀጥሉ፣ ወይም የአካባቢውን ቅጂ ለማደስ ያምጡ።',
'Presta_Pull_Desc' => 'የPrestaShop ምርቶችን ያስመጣል፣ ነባሮቹን በreference (SKU) በማዛመድ የቀሩትን ይፈጥራል። Combinations እንደ ወላጅ ምርታቸው ይመጣሉ።',
'Presta_Reset_Confirm' => 'የምርት ግንኙነቶች ዳግም ይጀመሩ? የትዕዛዝ ታሪክ ግንኙነቶቹን ይይዛል።',
'Presta_Stock_Desc' => 'ለእያንዳንዱ የተገናኘ ምርት የሱቁን ክምችት (stock_availables) ያዘምናል።',
'Presta_Orders_Desc' => 'የሱቅ ትዕዛዞችን እንደ ሽያጮች (እንደ {ref} ያሉ ማጣቀሻዎች)፣ አዳዲሶቹን መጀመሪያ ያስመጣል። አስቀድመው የገቡ እና የተሰረዙ ትዕዛዞች ይዘለላሉ፤ ስለዚህ በየጊዜው ማምጣት ደህንነቱ የተጠበቀ ነው። PrestaShop webhooks የለውም — ከስራ ከበዛባቸው ጊዜያት በኋላ ይህን ያሂዱ።',
