'Presta_Guide_2' => 'አዲስ ቁልፍ ያክሉ፣ በ{products} እና {stock} ላይ {vae}፣ በ{orders} እና {customers} ላይ ደግሞ {view} ፈቃድ ይስጡ።',
'Presta_Guide_3' => 'የሱቁን URL እና ቁልፉን በግንኙነት ትር ላይ ይለጥፉ፣ ያስቀምጡ፣ እና {test}ን ያሂዱ።',
'Presta_Guide_4' => 'ሱቁ አስቀድሞ ካታሎግ ካለው መጀመሪያ ምርቶችን ያምጡ (በreference/SKU ይዛመዳሉ)፤ የሌሉ ቀላል ምርቶችን ለመፍጠር ይላኩ።',
