'Xero_Guide_5' => 'የመለያ ኮዶቹን ያረጋግጡ፦ የሽያጭ መለያው የደረሰኝ መስመሮችን ይቀበላል፤ የተከፈሉ ሽያጮች ክፍያዎችንም እንዲመዘግቡ ከፈለጉ የባንክ መለያ ኮድ ያስገቡ።',
'Xero_Guide_6' => 'መጀመሪያ ደንበኞችን፣ ከዚያም ደረሰኞችን ይላኩ። የደረሰኝ ቁጥሮች የሽያጭ ማጣቀሻዎች ስለሆኑ ትስስሮች ዳግም ቢጀመሩም Xero ተደጋጋሚዎችን አይቀበልም።',
'Xero_Tax_Inclusive_Title' => 'መጠኖች ታክስን ጨምረው እንዳሉ ይላካሉ',
