'Salla_Urls_Help' => 'ሁለቱንም በ{link} ላይ ባለው መተግበሪያዎ ውስጥ ያስገቡ፣ የ{signature} webhook የደህንነት ስልትን ይምረጡ፣ እና ለትዕዛዝ፣ ለምርት እና ለመተግበሪያ ክስተቶች ይመዝገቡ።',
'Salla_Variants_Linked' => 'የተያያዙ ተለዋዋጮች',
'Salla_Push_Desc' => 'ቀላል ምርቶችን በSKU መሠረት በSalla ላይ ይፈጥራል ወይም ያዘምናል። ተለዋዋጭ ያላቸው ምርቶች በዚህ ስሪት ይዘለላሉ — በምትኩ ከSalla ያምጧቸው ወይም በSKU ያዛምዷቸው።',
'Salla_Only_Unlinked' => 'እስካሁን ያልተያያዙ ምርቶች ብቻ',
