'Salla_Reset_Confirm' => 'የምርት እና የተለዋዋጭ ትስስሮች ዳግም ይጀመሩ? የትዕዛዝ ታሪክ ትስስሮቹን እንደያዘ ይቆያል።',
'Salla_Stock_Desc' => 'ለእያንዳንዱ የተያያዘ ምርት (በSKU) እና ለተያያዘ ተለዋዋጭ የአሁኑን ብዛት ይልካል።',
'Salla_Orders_Desc' => 'አዳዲስ የSalla ትዕዛዞች በመደበኛነት በwebhooks አማካኝነት በራሳቸው ይደርሳሉ እና ሽያጮች ይሆናሉ። webhook ከመዋቀሩ በፊት የተሰጡ ትዕዛዞችን ለማሟላት ይህን ማምጫ ይጠቀሙ — አስቀድመው የገቡ ትዕዛዞች ይዘለላሉ።',
'Salla_Guide_1' => 'በ{link} ላይ (የግል) መተግበሪያ ይፍጠሩና የ{mode} የፈቃድ አሰጣጥ ሂደትን ይምረጡ።',
'Salla_Guide_2' => 'የመተግበሪያውን {clientId} እና {clientSecret} ወደ ግንኙነት ትር ይቅዱና ያስቀምጡ።',
'Salla_Guide_3' => 'በመተግበሪያው ቅንብሮች ውስጥ በግንኙነት ትር ላይ የሚታየውን OAuth callback URL ያስገቡ።',
'Salla_Guide_4' => 'በመተግበሪያው Webhooks ገጽ ላይ፦ የ{signature} የደህንነት ስልትን ይምረጡ፣ ሚስጥሩን እዚህ ወዳለው የWebhook ሚስጥር መስክ ይቅዱ፣ በግንኙነት ትር ላይ የሚታየውን Webhook URL ያስገቡ፣ እና ቢያንስ ለ{e1}፣ {e2}፣ {e3}፣ {e4}፣ {e5} እና {e6} ይመዝገቡ።',
'Salla_Guide_5' => '{connect} ን ይጫኑና መተግበሪያውን በሱቅዎ ላይ ያጽድቁ። (በEasy Mode ያሉ መተግበሪያዎች በምትኩ በ{webhook} webhook አማካኝነት በራስ-ሰር ይገናኛሉ።)',
'Salla_Guide_6' => 'ምርቶችን ያምጡ ወይም ይላኩ፣ ከዚያም ክምችትን ይላኩ። አዳዲስ ትዕዛዞች በራስ-ሰር ይደርሳሉ እና በሽያጮች ስር እንደ {ref} ባሉ ማጣቀሻዎች ይታያሉ።',
'Salla_Identity_Title' => 'የምርት መለያው SKU ነው',
'Salla_Identity_Desc' => 'የStocky የምርት ኮድ ከSalla SKU ጋር ይዛመዳል። በሁለቱም በኩል SKUዎችን ወጥ ያድርጉ፤ ተለዋዋጭ ያላቸው ምርቶች ሲመጡ እና በትዕዛዞች ውስጥ ይዛመዳሉ፣ ነገር ግን በዚህ ስሪት አይላኩም።',
