'Fbr_Token_Saved' => 'ቶክን ተቀምጧል (••••{last4})። እንዳለ ለማቆየት ባዶ ይተዉት።',
'Fbr_Token_Obtain' => 'ቶክኑን ከPRAL / IRIS የኤሌክትሮኒክ ደረሰኝ ፖርታል ያግኙ።',
'Fbr_Token_Placeholder' => 'ከPRAL / IRIS የኤሌክትሮኒክ ደረሰኝ ፖርታል የተገኘውን ቶክን ይለጥፉ',
'Fbr_Guide_What_Title' => 'የFBR ዲጂታል ደረሰኝ ምንድን ነው?',
'Fbr_Guide_What_Body' => 'በSRO 69(I)/2025 መሠረት፣ የፓኪስታን የፌዴራል ገቢዎች ቦርድ (FBR) የተቀናጁ ንግዶች የሽያጭ ደረሰኞችን በPRAL Digital Invoicing (DI) API አማካኝነት በእውነተኛ ጊዜ በኤሌክትሮኒክ መንገድ እንዲያሳውቁ ይጠይቃል። ተቀባይነት ያገኘ እያንዳንዱ ሽያጭ ይፋዊ የFBR ደረሰኝ ቁጥር ይቀበላል፣ እና ደረሰኞች ያንን ቁጥር ከማረጋገጫ QR ኮድ ጋር ማሳየት አለባቸው።',
'Fbr_Guide_Steps_Title' => 'ወደ ሥራ ለመግባት ደረጃዎች',
'Fbr_Guide_Step_1' => 'በFBR IRIS የኤሌክትሮኒክ ደረሰኝ ፖርታል ላይ ይመዝገቡ እና የ{sandbox} የደህንነት ቶክን ያግኙ።',
'Fbr_Guide_Step_2' => 'በውቅር ትር ላይ የሻጭ መገለጫዎን ያዋቅሩ (NTN/CNIC፣ የንግድ ስም፣ ክፍለ ሀገር፣ አድራሻ)፣ ቶክኑን ይለጥፉ፣ እና አካባቢውን ወደ {sandbox} በማድረግ ውህደቱን ያንቁ።',
'Fbr_Guide_Step_3' => 'FBR የመደበልዎትን የሙከራ ሁኔታ(ዎች) የሚሸፍኑ የሙከራ ሽያጮችን ያድርጉ (ሁኔታውን በSandbox ሙከራ ሁኔታ መስክ ውስጥ ይምረጡ)። {valid} ሆነው መመለሳቸውን ለማረጋገጥ የሰነዶች ትርን ይመልከቱ።',
'Fbr_Guide_Step_4' => 'FBR የsandbox ሙከራዎን ካጸደቀ በኋላ የ{production} ቶክኑን ከፖርታሉ ያግኙ፣ እዚህ ይለጥፉት፣ እና አካባቢውን ወደ {production} ይቀይሩ።',
'Fbr_Guide_Step_5' => 'አንድ ሽያጭ ተቀባይነት ካገኘ በኋላ ደረሰኞች የFBR ደረሰኝ ቁጥሩን እና QR ኮዱን በራስ-ሰር ያሳያሉ — በሽያጭ ቦታው ላይ ተጨማሪ እርምጃ አያስፈልግም።',
'Fbr_Sandbox_Lower' => 'sandbox (ሙከራ)',
'Fbr_Production_Lower' => 'production (ቀጥታ)',
'Fbr_Guide_Note_1' => 'ለእያንዳንዱ ምርት HS ኮድ በምርት ቅጹ ላይ ያስገቡ (መስክ "HS ኮድ")። እዚህ የተዋቀረው ነባሪ HS ኮድ የራሳቸው ኮድ ለሌላቸው ምርቶች ብቻ ጥቅም ላይ ይውላል።',
'Fbr_Guide_Note_2' => 'ያልተመዘገቡ ተራ ደንበኞች ለFBR "Unregistered" ተብለው ይላካሉ።',
'Fbr_Guide_Note_3' => 'የተመዘገቡ ገዢዎች እንደ ተመዘገቡ እንዲላኩ NTN ቁጥራቸው በደንበኛው የታክስ ቁጥር መስክ ውስጥ መግባት አለበት።',
'Fbr_Guide_Note_4' => 'ያልተሳኩ ወይም ልክ ያልሆኑ ማስገቢያዎች ምክንያቱ ከተስተካከለ በኋላ ከሰነዶች ትር እንደገና ሊሞከሩ ይችላሉ፤ የምዝግብ ማስታወሻዎች ትር ለችግር መፍቻ ጥሬ የAPI ልውውጦችን ያሳያል።',
'Fbr_Invoice_No' => 'የFBR ደረሰኝ ቁጥር',
'Fbr_Load_Failed' => 'የFBR ቅንብሮችን መጫን አልተቻለም',
'Fbr_Save_Failed' => 'ማስቀመጥ አልተሳካም',
