'Woo_Automatic_Sync' => 'ራስ-ሰር ማመሳሰል',
'Woo_Auto_Sync_Intro' => 'በ Stocky ውስጥ የሚደረጉ ለውጦችን ይህን ገጽ ሳይከፍቱ በተደረጉበት ቅጽበት ወደ WooCommerce ይልካል። እያንዳንዱ መላክ ድርጊቱ ከተቀመጠ በኋላ ወዲያውኑ ስለሚካሄድ ካሽየሩ WooCommerceን አይጠብቅም። ውጤቶቹ በመዝገቦች ትር ውስጥ ይታያሉ።',
'Woo_Auto_Sync_Products_Help' => 'በ Stocky ውስጥ የተፈጠረ፣ የተስተካከለ ወይም የተባዛ ምርት ወደ WooCommerce ይላካል (ዝርዝሮች፣ ዋጋ፣ ዓይነቶች፣ ምስሎች፣ ክምችት)። በጅምላ የሚመጡ ምርቶች አይላኩም፤ ካስመጡ በኋላ በምርቶች ትር ውስጥ አመሳስል — POS → WooCommerce ይጠቀሙ።',
'Woo_Auto_Sync_Stock_Help' => 'ማንኛውም የክምችት እንቅስቃሴ (የ POS ሽያጭ፣ ሽያጭ፣ መመለሻ፣ ግዢ፣ ማስተካከያ፣ ማስተላለፊያ) በ WooCommerce ላይ የሚመለከታቸውን ምርቶች ብዛት ያዘምናል። የሚዘመኑት አስቀድመው ከ WooCommerce ጋር የተያያዙ ምርቶች ብቻ ናቸው።',
'Woo_Sync_Tuning' => 'የማመሳሰል ማስተካከያ',
'Woo_Sync_Tuning_Intro' => 'ነባሪ እሴቶቹ ለአብዛኞቹ ሱቆች ተስማሚ ናቸው። እነዚህን የሚቀይሩት ማመሳሰል በሆስቲንግዎ ላይ ቀርፋፋ ከሆነ ወይም የጊዜ ገደቡ ካለፈ ብቻ ነው። እያንዳንዱ እሴት በአስተማማኝ ክልል ውስጥ የተገደበ ሲሆን መስኩን ባዶ ማድረግ ነባሪውን ይመልሰዋል።',
'Woo_Sync_Guide' => 'የ WooCommerce ማመሳሰል መመሪያ',
'Woo_Guide_Getting_Keys' => 'የ API ቁልፎችን ማግኘት',
'Woo_Guide_Keys_1' => 'በ WooCommerce ውስጥ፦ WooCommerce → Settings → Advanced → REST API።',
'Woo_Guide_Keys_2' => 'Add key ይጫኑ፣ Read/Write ይምረጡ፣ ከዚያም Consumer key እና Consumer secret ይቅዱ።',
'Woo_Guide_Keys_3' => 'የሱቅ URL፦ የድረ-ገጽዎ URL መጨረሻ ላይ ያለ ስላሽ (/) (ለምሳሌ {example})።',
'Woo_Guide_WP_Title' => 'የ WP የተጠቃሚ ስም እና Application Password (አማራጭ)',
'Woo_Guide_WP_Intro' => 'እነዚህ መስኮች ለምርት ምስሎች ብቻ ያገለግላሉ። የ WooCommerce API (የሱቅ URL + Consumer key/secret) የምርቶች፣ የክምችት፣ የምድቦች፣ የብራንዶች፣ የደንበኞች እና የትዕዛዞች ማመሳሰልን ያከናውናል፤ የ WordPress REST API ደግሞ የሚዲያ ቤተ-መጽሐፍቱን (Media Library) ያስተዳድራል (ምስሎችን መፈለግ እና መስቀል)።',
'Woo_Guide_WP_1' => 'ምርቶችን ወይም ክምችትን ሲያመሳስል Stocky የምርት ምስሎችን ማያያዝ ይችላል፦ በመጀመሪያ በ WordPress Media Library ውስጥ ያለ ምስልን በፋይል ስም ይፈልጋል፤ ካልተገኘ ምስሉን በ WordPress API በኩል ይሰቅለዋል።',
'Woo_Guide_WP_2' => 'ሚዲያን ማስተዳደር የሚችል የ WordPress ተጠቃሚ ይጠቀሙ (ለምሳሌ Administrator)። በ WordPress ውስጥ Application Password ይፍጠሩ፦ Users → Profile (ወይም የእርስዎ ተጠቃሚ) → Application Passwords — አዲስ ያክሉ እና እዚህ ይለጥፉት።',
'Woo_Guide_WP_3' => 'እነዚህን ባዶ ከተዉ ማመሳሰል ለሁሉም ውሂብ (ምርቶች፣ ክምችት፣ ምድቦች፣ ብራንዶች፣ ደንበኞች፣ ትዕዛዞች) ይሰራል፤ የሚታለፈው የምርት ምስል ማያያዝ (መፈለግ/መስቀል) ብቻ ነው።',
'Woo_Guide_How_To_Enable' => 'እንዴት ማንቃት እንደሚቻል',
'Woo_Guide_Enable_1' => 'ከላይ የሱቅ URL፣ Consumer key እና Consumer secret ያስገቡ፣ ከዚያም አስቀምጥ የሚለውን ይጫኑ።',
'Woo_Guide_Enable_2' => 'ምስክርነቶቹን ለማረጋገጥ ግንኙነትን ይፈትሹ የሚለውን ይጠቀሙ።',
'Woo_Guide_Enable_3' => 'ማመሳሰል ሲያስፈልግዎ ከማንኛውም ትር በእጅ ማመሳሰልን ይጠቀሙ።',
'Woo_Guide_Enable_4' => 'አዲስ እና የተስተካከሉ ምርቶችን እንዲሁም እያንዳንዱን የክምችት ለውጥ በተከሰተበት ቅጽበት ወደ WooCommerce ለመላክ ከላይ ራስ-ሰር ማመሳሰልን ያብሩ።',
'Woo_Guide_Manual_Sync' => 'በእጅ ማመሳሰል (በፍላጎት)',
'Woo_Guide_Manual_1' => 'ማመሳሰል በሁለቱም አቅጣጫዎች ይሰራል፦ Stocky → WooCommerce እና WooCommerce → Stocky።',
'Woo_Guide_Manual_2' => 'በእጅ ማመሳሰል በሁሉም የ WooCommerce ትሮች (ምርቶች፣ ክምችት፣ ወዘተ.) ውስጥ ይገኛል፤ በፈለጉት ጊዜ ለማመሳሰል በእያንዳንዱ ትር ያሉትን የማመሳሰል ድርጊቶች ይጠቀሙ።',
'Woo_Guide_Auto_1' => 'ምርቶች፦ ሲበራ በ Stocky ውስጥ የሚፈጥሩት፣ የሚያስተካክሉት ወይም የሚያባዙት ምርት ካስቀመጡት በኋላ ወዲያውኑ ወደ WooCommerce ይላካል፣ ቀጥሎም ክምችቱ ይላካል።',
'Woo_Guide_Auto_2' => 'ክምችት፦ ሲበራ እያንዳንዱ የክምችት ለውጥ (የ POS ሽያጭ፣ ሽያጭ፣ መመለሻ፣ ግዢ፣ ማስተካከያ፣ ማስተላለፊያ) በ WooCommerce ላይ ያለውን ብዛት ያዘምናል። የሚዘመኑት አስቀድመው ከ WooCommerce ጋር የተያያዙ ምርቶች ብቻ ናቸው።',
'Woo_Guide_Auto_3' => 'ራስ-ሰር ማመሳሰል ለውጦችን የሚልከው ከ Stocky ወደ WooCommerce ብቻ ነው። ከ WooCommerce ወደ Stocky ውሂብ ማምጣት (ትዕዛዞች፣ ደንበኞች፣ ምርቶች) ሁልጊዜ በትዕዛዞች፣ በደንበኞች እና በምርቶች ትሮች ውስጥ ባሉ አዝራሮች ይከናወናል።',
'Woo_Guide_Auto_4' => 'በጅምላ የሚመጡ ምርቶች በራስ-ሰር አይላኩም። ካስመጡ በኋላ በምርቶች ትር ውስጥ አመሳስል — POS → WooCommerce ይጠቀሙ።',
'Woo_Guide_Auto_5' => 'እያንዳንዱ ራስ-ሰር መላክ በመዝገቦች ትር ውስጥ ይመዘገባል፣ ስለዚህ ምን እንደተላከ ማረጋገጥ እና ስህተቶችን መለየት ይችላሉ።',
'Woo_Guide_First_Setup' => 'የመጀመሪያ ዝግጅት',
'Woo_Guide_First_1' => 'ያለው ካታሎግዎ እንዲያያዝ እነዚህን አንድ ጊዜ፣ በዚህ ቅደም ተከተል ያሂዱ፦ በምድቦች ትር ውስጥ አመሳስል — POS → WooCommerce፣ ከዚያም በብራንድ ትር፣ ከዚያም በምርቶች ትር፣ በመጨረሻም በክምችት ትር ውስጥ ክምችትን አመሳስል። ከዚያ በኋላ WooCommerceን ወቅታዊ ለማድረግ ከላይ ራስ-ሰር ማመሳሰልን ያብሩ።',
'Woo_Guide_First_2' => 'ትላልቅ የምርት እና የክምችት ማመሳሰሎች በትንንሽ ስብስቦች ይካሄዳሉ፣ እድገታቸውንም በትሩ ውስጥ ያሳያሉ። ማመሳሰሉ እስኪጠናቀቅ ድረስ ገጹን ክፍት ያድርጉት፤ በማንኛውም ጊዜ ማቆም ይችላሉ።',
'Woo_Guide_First_3' => 'ማመሳሰል ለብዙ ደቂቃዎች ካልተንቀሳቀሰ የመዝገቦች ትርን ይመልከቱ፣ ከዚያም ድጋፍን ያግኙ።',
'Woo_Guide_Notes_1' => 'የሱቅ URL ወይም የ API ቁልፎችን መቀየር ትስስሮችን (ምርቶች፣ ምድቦች፣ ብራንዶች፣ ደንበኞች) ዳግም ያስጀምራል፤ እቃዎቹ ወደ (አዲሱ) ሱቅ እንደገና ይመሳሰላሉ።',
'Woo_Guide_Notes_2' => 'የተባዙ ምርቶችን ለማስቀረት እና በደህና እንደገና ለማያያዝ SKUዎችን በ Stocky እና በ WooCommerce መካከል ወጥ ያድርጉ።',
'Store_Banner_Pos_Top_Left' => 'ላይ — ግራ',
'Store_Banner_Pos_Top_Right' => 'ላይ — ቀኝ',
'Store_Banner_Pos_Center_Left' => 'መሃል — ግራ',
'Store_Banner_Pos_Center_Right' => 'መሃል — ቀኝ',
'Store_Banner_Pos_Footer_Left' => 'ግርጌ — ግራ',
'Store_Banner_Pos_Footer_Right' => 'ግርጌ — ቀኝ',
'Store_Banner_Recommended' => 'የሚመከር፦ {w} × {h} ({ratio})',
'Store_Banner_Uploaded' => 'የተሰቀለ፦ {w} × {h} ({ratio})',
'Store_Banner_Aspect_Differs' => 'የምጥጥን መጠኑ ከሚመከረው ይለያል',
'Store_Banner_Looks_Good' => 'ጥሩ ይመስላል ✅',
'Store_Banner_Guide_Top' => 'ላይ (ግራ/ቀኝ)፦ 1200×600 (2:1)',
'Store_Banner_Guide_Center' => 'መሃል (ግራ/ቀኝ)፦ 1200×600 (2:1)',
'Store_Banner_Guide_Footer' => 'ግርጌ (ግራ/ቀኝ)፦ 1200×600 (2:1)',
'Store_Banner_Retina_Tip' => 'ጠቃሚ ምክር፦ ለሬቲና ማሳያዎች 2x ይጠቀሙ (ለምሳሌ 2400×1200)።',
'Store_Item_Required_Available' => '{name}፦ የሚያስፈልግ {need} — ያለ {have}',
'Store_Currency_Change_Warning' => 'ምንዛሪን መቀየር ሲስተሙንም የመስመር ላይ ሱቁንም ይነካል',
'Store_Color_Lavender' => 'ላቬንደር',
'Store_Color_Pink' => 'ሮዝ',
'Store_Color_Mint' => 'ሚንት',
'Store_Color_Yellow' => 'ቢጫ',
'Store_Color_Peach' => 'ኮክ',
'Store_Color_Sky' => 'የሰማይ ሰማያዊ',
'Store_Color_Lilac' => 'ሊላክ',
