'Pg_Store_Feature_Not_In_Plan' => 'የመስመር ላይ ሱቅ የክፍያ መግቢያዎች እና ከመስመር ውጭ የክፍያ ዘዴዎች የመስመር ላይ ትዕዛዞች ባህሪ አካል ናቸው፤ ይህ ባህሪ አሁን ባለዎት እቅድ ውስጥ አልተካተተም።',
'Pg_Intro_Title' => 'እዚህ ያለ እያንዳንዱ የክፍያ መግቢያ ምስክርነቶቹ ከተቀመጡ እና ማብሪያው ከበራ በኋላ በመስመር ላይ ሱቅ የክፍያ ማጠናቀቂያ ላይ ይቀርባል።',
'Pg_Intro_Desc' => 'እያንዳንዱ ትር የራሱ የማብሪያ/ማጥፊያ አለው፣ ልክ እንደቀየሩት ይቀመጣል፦ የክፍያ መግቢያን ማጥፋት ምስክርነቶቹን ባሉበት ይተዋቸዋል፣ የክፍያ ማጠናቀቂያው ማቅረቡን ብቻ ያቆማል። የ Stripe ቁልፎች በአጠቃላይ የጋራ ናቸው (አስተዳዳሪውም የመስመር ላይ ሱቁም አንድ አይነት የ Stripe ውህደት ይጠቀማሉ)። ከመስመር ውጭ ክፍያዎች በሲስተሙ ውጭ የሚከፈሉትን በማድረስ ጊዜ ጥሬ ገንዘብ ክፍያ እና የሞባይል ገንዘብን ይይዛል።',
