'Pg_Xpay_Help' => 'ካርዶች በክፍያ ማጠናቀቂያ ገጹ ውስጥ በተካተተ የ XPay ኤለመንት ይገባሉ (ወደ ሌላ ገጽ አይዘዋወርም)። ትዕዛዙ ከመፈጠሩ በፊት እያንዳንዱ ክፍያ በአገልጋዩ በኩል እንደገና ይረጋገጣል። ማሳሰቢያ፦ ልክ እንደ XPay ይፋዊ ፕለጊኖች ሁሉ የ XPay SDK የ API HMAC ሚስጥሩን በአሳሹ ውስጥ ይፈልጋል።',
