'Pg_Payfast_Help' => 'የተስተናገደ የክፍያ ገጽ (ZAR)። የክፍያ ማረጋገጫው ከታች ባለው ITN URL ላይ ይደርሳል — ከእያንዳንዱ ክፍያ ጋር በራስ-ሰር ይላካል፣ በዳሽቦርዱ ላይ ማዋቀር አያስፈልግም፦',
