'Pg_Paypal_Webhook_Url_Help' => 'ይህን በ PayPal ዳሽቦርድዎ ውስጥ ያክሉት። የገዢው አሳሽ ጨርሶ ሳይመለስ ሲቀር ትዕዛዙን የሚያጠናቅቀው ከአገልጋይ ወደ አገልጋይ የሚደረግ መጠባበቂያ ይህ ነው።',
'Pg_Paypal_Help' => 'የተስተናገደ የ PayPal ክፍያ ገጽ (Orders API v2)። ገዢው በ PayPal ላይ ያጸድቃል፣ ሲመለስም ክፍያው በአገልጋዩ በኩል ይወሰዳል — የተተወ ማጽደቅ ትዕዛዙን በፍጹም እንደተከፈለ ምልክት አያደርግም።',
