'Pg_Paystack_Help' => 'በመላው አፍሪካ ለካርዶች፣ ለባንክ ዝውውር እና ለሞባይል ገንዘብ የተስተናገደ የ Paystack ክፍያ ገጽ። ሙከራ ወይም ቀጥታ መሆኑ የሚወሰነው በቁልፍ ጥንዱ ስለሆነ የሳንድቦክስ ማብሪያ የለም።',
