'Pg_Flutterwave_Help' => 'የተስተናገደ የ Flutterwave v3 Standard ክፍያ ገጽ። ሙከራ ወይም ቀጥታ መሆኑ የሚወሰነው በቁልፍ ጥንዱ ነው (FLWSECK_TEST- ወይም FLWSECK-)፣ ስለዚህ የሳንድቦክስ ማብሪያ የለም።',
