'Shp_Stock_Lag_Desc' => 'በመሸጫ ቦታ የተደረገ ሽያጭ እስከዚያ ድረስ ለሱቁ አይታይም — እስከ {n} ደቂቃ ድረስ፣ ስለዚህ የመጨረሻው እቃ በመስመር ላይ ሁለት ጊዜ ሊሸጥ ይችላል። {setting}ን ያብሩ፣ እያንዳንዱ ሽያጭ፣ መመለሻ እና ማስተካከያ በምትኩ በሰከንዶች ውስጥ ይላካል።',
