'Shp_Hook_Register_Token' => 'ከታች “በ Shopify ውስጥ መዝግብ” የሚለውን ጠቅ ያድርጉ፣ የመተግበሪያውን API secret key በሱቅ ቅንብሮች ውስጥ እንደ የፊርማ ሚስጥር ይለጥፉ።',
'Shp_Hook_Note_Register' => 'መመዝገብ በ Shopify ውስጥ ምዝገባዎቹን ይፈጥራል እና ወደዚህ አድራሻ በራስ-ሰር ይጠቁማቸዋል። በ Shopify → Settings → Notifications → Webhooks ስር በእጅ አያክሉት፦ እነዚያ በተለየ ሚስጥር ስለሚፈረሙ እያንዳንዱ መላኪያ ውድቅ ይደረጋል።',
'Shp_Hook_Verified_Cc' => 'መላኪያዎች ቀድሞውኑ በተቀመጠው የመተግበሪያው client secret ይረጋገጣሉ።',
