'Shp_Hook_Retries' => 'Shopify 2xx እስኪያገኝ ድረስ እንደገና ይሞክራል፣ እያንዳንዱ መላኪያም አንድ ጊዜ ብቻ ይመዘገባል — የተደገመ ክስተት ምንም ውጤት የለውም፣ የተባዛ ትዕዛዝ አይፈጥርም።',
