'Shp_Instant_Push_Hint' => 'ሽያጭ፣ መመለሻ ወይም ማስተካከያ እንደተቀመጠ ለእነዚያ ምርቶች ብቻ የክምችት መላኪያ ይልካል፣ ስለዚህ ሱቁ በሚቀጥለው መርሐግብር ዙር ሳይሆን በሰከንዶች ውስጥ ትክክል ይሆናል። ሌላ የሚጫን ነገር የለም — መላኩ የሚካሄደው ለሽያጩ ምላሽ ከተሰጠ በኋላ ስለሆነ የሽያጭ መሳቢያው Shopifyን በፍጹም አይጠብቅም።',
'Shp_Switch_Inventory_First' => 'መጀመሪያ በ {tab} ስር ክምችትን ያብሩ።',
