'Shp_G_Lead_Store' => 'ይህ ሱቅ ራሱን ወቅታዊ ለማድረግ የሚያስፈልገው። እዚህ ያለው ሁሉ ለዚህ ሱቅ የተለየ ነው — የዌብሁክ URL እና idዎቹ እውነተኛ ናቸው።',
'Shp_G_Lead_Store_Cmd' => 'ይህ ሱቅ ራሱን ወቅታዊ ለማድረግ የሚያስፈልገው። እዚህ ያለው ሁሉ ለዚህ ሱቅ የተለየ ነው — የዌብሁክ URL እና idዎቹ እውነተኛ ናቸው፣ ስለዚህ ትዕዛዞቹን በቀጥታ ወደ አገልጋዩ መቅዳት ይቻላል።',
'Shp_G_Lead_Generic' => 'የ Shopify ሱቅ ራሱን ከ ERP ጋር እንዴት ወቅታዊ እንደሚያደርግ። የራሱን ሁኔታ ለማየት ከላይ ሱቅ ይምረጡ፣ ወይም እንዳለ ያንብቡት — የትኛውንም ሱቅ ቢያገናኙ የዌብሁክ URL አንድ ነው።',
'Shp_G_Lead_Generic_Cron' => 'የ Shopify ሱቅ ራሱን ከ ERP ጋር እንዴት ወቅታዊ እንደሚያደርግ። የራሱን ሁኔታ ለማየት ከላይ ሱቅ ይምረጡ፣ ወይም እንዳለ ያንብቡት — የትኛውንም ሱቅ ቢያገናኙ የዌብሁክ URL እና የክሮን መስመሩ አንድ ናቸው።',
'Shp_G_Ways_Note' => 'አብዛኞቹ ሱቆች ሁለቱንም ይጠቀማሉ፦ የመጀመሪያው ሱቁን በየደቂቃው ወቅታዊ ያደርጋል፣ ሁለተኛው የመጀመሪያው ያመለጠውን ይይዛል — ያልደረሰ ዌብሁክ፣ በቀጥታ በ Shopify አስተዳዳሪ የተደረገ ማስተካከያ፣ ድረ-ገጹ የተቋረጠበት ሌሊት።',
'Shp_G_Both_Need' => 'ሁለቱም መንገዶች መጀመሪያ ይህን ይፈልጋሉ',
'Shp_G_Credentials' => 'የ Shopify ምስክርነቶች',
'Shp_G_Cred_Intro' => 'ከጃንዋሪ 2026 ጀምሮ Shopify በአስተዳዳሪው ውስጥ ብጁ መተግበሪያዎችን ስለማይፈጥር ሁለት ዓይነት ግንኙነቶች አሉ፦',
'Shp_G_Cred_Dev' => '{app} (አሁን የሚገናኝ ማንኛውም ሱቅ) — {path}። ይህ ሱቅ ለሚያመሳስለው የ Admin API ፈቃዶችን (scopes) ይስጡ፣ መተግበሪያውን በሱቁ ላይ ይጫኑ፣ ከዚያም {clientId} እና {clientSecret} ከመተግበሪያው Settings ገጽ ወደ {edit} ይቅዱ። ERP በራሱ በመዳረሻ ቶከን ይለውጣቸዋል፣ በየ 24 ሰዓቱ ጊዜው ከማለፉ በፊትም ያድሰዋል። client secret ዌብሁኮችንም ይፈርማል፣ ስለዚህ ሌላ ምንም አያስፈልግም። መተግበሪያው እና ሱቁ በአንድ የ Shopify ድርጅት ውስጥ መሆን አለባቸው።',
'Shp_G_Dev_App' => 'የ Dev Dashboard መተግበሪያ',
'Shp_G_Cred_Legacy' => '{app} (ከ 2026 በፊት በአስተዳዳሪው ውስጥ የተፈጠረ) — በ {token} ({prefix}) እና {secret}ን እንደ የዌብሁክ ፊርማ ሚስጥር በመጠቀም ያለ ለውጥ መስራቱን ይቀጥላል። ከቶከኑ ጋር አንድ አይነት እሴት አይደለም፣ እነሱን ማቀያየር ደግሞ ዌብሁኮች ውድቅ የሚደረጉበት የተለመደ ምክንያት ነው።',
'Shp_G_Legacy_App' => 'የቆየ ብጁ መተግበሪያ',
'Shp_G_Api_Secret_Key' => 'የ API ሚስጥር ቁልፍ (API secret key)',
'Shp_G_Stored' => 'ተቀምጧል',
'Shp_G_Missing_Refused' => 'የለም — መላኪያዎች ውድቅ ይደረጋሉ',
'Shp_G_Targets' => '{path} ይህ ሱቅ ክምችቱን የሚሸጥበት የ ERP መጋዘን፣ እና ያ ክምችት የሚጻፍበት የ Shopify ቦታ። የክምችት ማመሳሰልም የትዕዛዝ ማስመጣትም ያለ እነሱ አይካሄዱም።',
'Shp_G_Currently' => 'አሁን፦ መጋዘን {warehouse}፣ ቦታ {location}',
'Shp_G_Not_Set_Lc' => 'አልተዘጋጀም',
'Shp_G_Ready' => 'ዝግጁ',
'Shp_G_Incomplete' => 'ያልተሟላ',
'Shp_G_Manual_Syncs' => 'በእጅ የሚጀምሯቸው ማመሳሰሎች',
'Shp_G_Manual_Body' => 'ከ {centre} የተጀመረ ማመሳሰል ወዲያውኑ ምላሽ ይሰጣል እና በጀርባ ይካሄዳል፣ እያንዳንዱ ካለፈው ካቆመበት በሚቀጥል አጫጭር ክፍሎች። ትልቅ ካታሎግ ጊዜው ባለፈ የድር ጥያቄ ምክንያት በግማሽ መንገድ በፍጹም አይቋረጥም፣ ገጹን መዝጋትም አያቆመውም።',
'Shp_G_Worker_Managed' => 'መድረክዎ ለዚህ የሚያስፈልገውን ወርከር ያሄዳል፣ ስለዚህ የሚጫን ነገር የለም።',
'Shp_G_Worker_Cron' => 'ለዚህ የሚያስፈልገው ወርከር አንድ ተጨማሪ የክሮን መስመር ነው፦',
'Shp_G_Cron_Copied' => 'የክሮን መስመሩ ተቀድቷል',
'Shp_G_Worker_Busy' => 'ወርከሩ ሥራ ላይ ከሆነ፣ የተከፈተው የማመሳሰል ማዕከል ገጽ ከጥቂት ሰከንዶች በኋላ ዙሩን በራሱ፣ አንድ አጭር ጥያቄ በአንድ ጊዜ እያስኬደ ይቀጥላል — ስለዚህ ማመሳሰል እየተመለከቱት ሁልጊዜ ይጠናቀቃል።',
'Shp_G_Pick_How' => 'ከዚያም እንዴት ወቅታዊ እንደሚሆን ይምረጡ',
'Shp_G_Right_Away' => 'ወዲያውኑ',
'Shp_G_Stock_Live' => 'ክምችት ቀጥታ',
'Shp_G_Stock_Not_Live' => 'ክምችት ቀጥታ አይደለም',
'Shp_G_Realtime_Lead' => 'እያንዳንዱ ለውጥ እንደተከሰተ በሰከንዶች ውስጥ ይላካል። ሁለት ግማሾች ናቸው፣ የተለያዩ ማብሪያዎችም አሏቸው፦ {webhooks} የሱቁን ክስተቶች ያስገባሉ፣ {push} ደግሞ ክምችትን ይልካል።',
'Shp_G_Webhooks_Lc' => 'ዌብሁኮች',
'Shp_G_Instant_Push_Lc' => 'ፈጣን የክምችት መላኪያ',
'Shp_G_Webhooks_Heading' => 'ዌብሁኮች — ሱቁ → ERP',
'Shp_G_Webhooks_Body' => 'በ Shopify ውስጥ የሚደረጉ ትዕዛዞች፣ የትዕዛዝ ሁኔታ ለውጦች እና የምርት፣ የደንበኛ እና የክምችት ማስተካከያዎች። ሱቁን ይክፈቱ እና በ {tab} ላይ {button}ን ይጫኑ — ሁለት ጊዜ መጫን ችግር የለውም። Shopify የሚልከው ወደዚህ ነው፦',
'Shp_G_Webhooks_Tab' => 'የዌብሁኮች ትር',
'Shp_G_Webhooks_Note' => 'አድራሻው ከኢንተርኔት በ HTTPS ሊደረስበት የሚችል መሆን አለበት — Shopify ወደ {localhost} ወይም ወደ {test} ዶሜይን አይልክም። እያንዳንዱ መላኪያ አንድ ጊዜ ብቻ ስለሚመዘገብ የ Shopify ድጋሚ ሙከራዎች የተባዛ ትዕዛዝ ሊፈጥሩ አይችሉም፣ ያልተሳካውም እንደገና ሊካሄድ ይችላል። ከደረጃ 1 ያለው የፊርማ ሚስጥር እስኪቀመጥ ድረስ መላኪያዎች ውድቅ ይደረጋሉ።',
'Shp_G_Push_Heading' => 'ፈጣን የክምችት መላኪያ — ERP → ሱቁ',
'Shp_G_People_Miss' => 'ሰዎች የሚዘነጉት ቅንብር ይህ ነው',
'Shp_G_Push_P1' => 'የ POS ሽያጭ በራሱ ወደ Shopify {not} አይደርስም። ጠፍቶ ከተተወ ሱቁ የሚያውቀው በሚቀጥለው የክምችት መላኪያ እርምጃ ብቻ ነው — በዚያ ክፍተት ውስጥ በመሸጫ መሳቢያው አስቀድመው የሸጡትን እቃ ሊሸጥ ይችላል።',
'Shp_G_Not' => 'በፍጹም',
'Shp_G_Push_P2' => 'በ {path} ላይ {setting}ን ምልክት ያድርጉ። ሙሉ ዝግጅቱ ይህ ብቻ ነው — ወርከርም ክሮንም አያስፈልግም። ከዚያ እያንዳንዱ ሽያጭ፣ መመለሻ እና ማስተካከያ ሽያጩ እንደተቀመጠ ወዲያውኑ ለእነዚያ ምርቶች ብቻ መላኪያ ይልካል፣ ሃያ መስመር ያለው ሽያጭም ሃያ ሳይሆን አንድ መላኪያ ብቻ ይጠይቃል። የሽያጭ መሳቢያው በፍጹም አይጠብቀውም።',
'Shp_G_This_Store' => 'ይህ ሱቅ፦',
'Shp_G_Push_On' => 'በርቷል — ሲቀየር ክምችት ይላካል',
'Shp_G_Push_Off' => 'ጠፍቷል — ክምችት በመርሐግብር ብቻ',
'Shp_G_Push_Note' => 'የሚላኩት አስቀድሞ የ Shopify ትስስር ያላቸው ምርቶች ብቻ፣ እና በዚህ ሱቅ መጋዘን ውስጥ ያሉ እንቅስቃሴዎች ብቻ ናቸው። የጅምላ ስራዎች — ምርትን መሰረዝ፣ መጋዘንን ዳግም ማስጀመር — ክስተት ሳያስነሱ ክምችትን ይጽፋሉ፣ ይህም በመርሐግብር የተያዘውን የክምችት እርምጃ ጭምር ማቆየት የሚገባበት አንዱ ምክንያት ነው።',
'Shp_G_Nothing_Else' => 'ሌላ የሚጫን ነገር የለም',
'Shp_G_Nothing_Else_Body' => 'ሁለቱም ግማሾች የወረፋ ወርከር ወይም የክሮን ግቤት አያስፈልጋቸውም። የሚገባ ዌብሁክ Shopify በሚያደርገው ጥያቄ ውስጥ ይስተናገዳል፤ የሚወጣ የክምችት መላኪያ ደግሞ ሽያጩን ባገለገለው ተመሳሳይ ሂደት ውስጥ፣ ምላሹ ከተመለሰ {after} ይካሄዳል — ስለዚህ የሽያጭ መሳቢያው Shopifyን በፍጹም አይጠብቅም፣ ምላሽ መስጠት ያቆመ ሱቅም ከአስር ሰከንድ በኋላ ይተዋል እና ለሚቀጥለው በመርሐግብር የተያዘ የክምችት መላኪያ ይቀራል።',
'Shp_G_After' => 'በኋላ',
'Shp_G_Exception' => 'አንድ ልዩ ሁኔታ፦ በጀርባ ሥራ የተደረገ የክምችት ለውጥ ተከትሎ የሚመጣ ምላሽ ስለሌለው በምትኩ በ {queue} ወረፋ ውስጥ ይገባል።',
'Shp_G_Queue_Managed' => 'መድረክዎ በዚያ ወረፋ ላይ ወርከርን አስቀድሞ ያሄዳል፣ ስለዚህ እነዚያም በራሳቸው ይላካሉ።',
'Shp_G_Queue_Cron' => 'እነዚያም በፍጥነት እንዲላኩ ከፈለጉ ያንን ወረፋ ያስኪዱ፦',
'Shp_G_On_Schedule' => 'በመርሐግብር',
'Shp_G_On_Lc' => 'በርቷል',
'Shp_G_Off_Lc' => 'ጠፍቷል',
'Shp_G_Scheduled_Lead' => 'ሁሉም ነገር በየተወሰነ ጊዜ በሁለቱም አቅጣጫዎች እንደገና ይፈተሻል። ከቀጥታ ጊዜ የዘገየ ነው፣ ነገር ግን ፈጣን መላኪያን በማይጠቀሙ ሱቆች ክምችትን የሚልከው፣ ያመለጠ ዌብሁክን የሚይዘው እና ሙሉ ካታሎግን ለማንቀሳቀስ ብቸኛው መንገድ እሱ ነው።',
'Shp_G_Nothing_To_Install' => 'የሚጫን ነገር የለም',
'Shp_G_Managed_Body' => 'መርሐግብር አስኪያጁ ይካሄድልዎታል፦ በየአምስት ደቂቃው መድረክዎ እያንዳንዱን ሱቅ የእቅዱ ማንኛውም እርምጃ ጊዜው እንደደረሰ ይጠይቃል፣ የደረሱትንም ያካሂዳል። የሚጨመር የክሮን ግቤት የለም፣ የሚጠበቅ አገልጋይም የለም።',
'Shp_G_Managed_Note' => 'አምስት ደቂቃ አጭሩ የእርምጃ የጊዜ ክፍተት ስለሆነ እቅድ ሊጠቀምበት የሚችለው ዝቅተኛው ትክክለኛነትም ነው። ረዘም ያሉ የጊዜ ክፍተቶች በትክክል ይከበራሉ — ለ 30 ደቂቃ የተዘጋጀ እርምጃ ስድስት ጊዜ ተፈትሾ አንድ ጊዜ ይካሄዳል።',
'Shp_G_Cron_Entry' => 'የክሮን ግቤቱ',
'Shp_G_Cron_Body' => 'ያለሱ ምንም በመርሐግብር የተያዘ ነገር አይካሄድም። አንድ መስመር፣ ለዚህ ሞጁል ብቻ — ለመርሐግብር ከመረጧቸው ሌሎች ነገሮች አጠገብ ያክሉት፦',
'Shp_G_Cron_Note' => 'አምስት ደቂቃ አጭሩ የእርምጃ የጊዜ ክፍተት ስለሆነ በየአምስት ደቂቃው እቅድ ሊጠቀምበት የሚችለው ዝቅተኛው ትክክለኛነት ነው። ረዘም ያለ ግቤት በቀላሉ ዝቅተኛው ገደብ ይሆናል — በ {every15}፣ ለ 5 ደቂቃ የተዘጋጀ እርምጃ በየ 15 ደቂቃው ይካሄዳል። በ Windows ላይ Task Schedulerን ይጠቀሙ፦ ፕሮግራም {php}፣ ነጋሪ እሴቶች (arguments) {args}፣ የሚጀምርበት ቦታ {path}።',
'Shp_G_Switch_On' => 'ያብሩት፣ እቅዱንም ይምረጡ',
'Shp_G_Plan_Body' => '{path} ማብሪያው መርሐግብር አስኪያጁ ጨርሶ እርምጃ መውሰድ ይችል እንደሆነ ይወስናል፤ እቅዱ ደግሞ ምን እንደሚያደርግ ይወስናል። አንድ {step} በአንድ አቅጣጫ ያለ፣ የራሱ የጊዜ ክፍተት ያለው አንድ የውሂብ ዓይነት ነው — {ex1}፣ {ex2}። ነባሪው የጊዜ ክፍተት የራሱን ሳጥን ባዶ በሚተው ማንኛውም እርምጃ ጥቅም ላይ ይውላል።',
'Shp_G_Step_Lc' => 'እርምጃ',
'Shp_G_Ex1' => 'ትዕዛዞች · Shopify → ERP በየ 15 ደቂቃ',
'Shp_G_Ex2' => 'ክምችት · ERP → Shopify በየ 30 ደቂቃ',
'Shp_G_Plan_Note' => 'እቅዱን ባዶ ከተዉት ሱቁ በነባሪው የጊዜ ክፍተት ትዕዛዞችን ያመጣል እና ክምችትን ይልካል፤ አብዛኞቹ ሱቆች የሚፈልጉት ይህንኑ ነው። ትዕዛዞች የሚመጡት ብቻ ናቸው፦ ደንበኛ ትዕዛዝ የሚያስገባው በ Shopify ላይ ነው።',
'Shp_G_Schedule_On' => 'መርሐግብር በርቷል',
