'Shp_G_When_Body' => 'እርምጃ ጊዜው የሚደርሰው ያው እርምጃ ለመጨረሻ ጊዜ {started} ከጊዜ ክፍተቱ በላይ ሲያልፍ ነው፤ ይህም ከዙሮች ታሪክ ይነበባል። ስለዚህ በእጅ የሚጀምሩት ማመሳሰል ቀጣዩን ራስ-ሰር ዙር ያዘገየዋል፣ በተደጋጋሚ የሚወድቅ እርምጃም በየቅጽበቱ ሳይሆን በጊዜ ክፍተቱ እንደገና ይሞከራል። የሱቁ አጠቃላይ እይታ የእያንዳንዱን እርምጃ የመጨረሻ ዙር፣ ቀጣይ ጊዜ እና ሲታገድም ምክንያቱን ያሳያል። የመጀመሪያውን የካታሎግ መላኪያ በመርሐግብር ከማስያዝዎ በፊት ከማመሳሰል ማዕከሉ በእጅ ያካሂዱት — መጀመሪያ እንደ የሙከራ ዙር።',
'Shp_G_Started_Lc' => 'ከተጀመረ',
'Shp_G_Where_Setting' => 'እያንዳንዱ ቅንብር የሚገኝበት',
'Shp_G_Where_Note' => 'እነዚህ ሁሉ ባለ ሱቅ ላይ ይገኛሉ፦ {path}፣ ከዚያም እርሳሱ (ወይም በሱቁ ገጽ ላይ {edit})።',
'Shp_G_Product_Images' => 'የምርት ምስሎች',
'Shp_G_Img1' => 'ምስሎች በ {push} ላይ ከምርቱ ጋር ይላካሉ — መጀመሪያ ዋናው ምስል፣ ከዚያ ጋለሪው፣ ከዚያም የራሱ ምስል ላለው ለእያንዳንዱ ዓይነት አንድ፣ እስከ ሃምሳ ድረስ።',
'Shp_G_Products_Push' => 'የምርቶች መላኪያ',
