'Shp_G_What8' => 'በራሱ የሚካሄደው፣ በየትኛው አቅጣጫ እና በምን ያህል ጊዜ።',
'Shp_G_Cmd1' => 'ሁሉም ሱቆች፦ ምን እንደሚካሄድ እና መቼ። ምንም አይቀይርም።',
'Shp_G_Cmd2' => 'የአንድ ሱቅ ሙሉ እቅድ አሁን፣ ሰዓቱን ችላ በማለት።',
'Shp_G_Cmd3' => 'የመጀመሪያ የካታሎግ መላኪያ፦ እስካሁን ያልተያያዙ ምርቶች ብቻ።',
'Shp_G_Cmd4' => 'ከአንድ ቀን ጀምሮ ያሉ ትዕዛዞችን ወደኋላ ሞልቶ ማምጣት።',
