'Agt_Tax_Map' => 'የIVA መጠን → የAGT ግብር ኮድ',
'Agt_Tax_Map_Hint' => 'ያልተዘረዘሩ መጠኖች እንደ OUT (Outra) ይላካሉ፤ 0% ሁልጊዜ ISE (Isento) ነው።',
'Agt_Series' => 'ተከታታይ ቁጥሮች',
'Agt_Series_Hint' => 'AGT ለእያንዳንዱ የሰነድ አይነት፣ ዓመት እና ተቋም አንድ የቁጥር ተከታታይ ይፈቅዳል። ለአይነታቸው እና ለዓመታቸው ንቁ ተከታታይ ከሌለ ደረሰኞች ሊሰጡ አይችሉም።',
'Agt_Request_Series' => 'ከAGT ተከታታይ ጠይቅ',
'Agt_Add_Series' => 'ያለ ተከታታይ አክል',
'Agt_Contingency' => 'የአደጋ ጊዜ',
'Normal' => 'መደበኛ',
'Agt_Corrects' => 'የሚያርመው',
'Agt_Late' => '> 24 ሰዓት',
'Agt_Check' => 'አረጋግጥ',
'Agt_Correct_Confirm' => 'ለዚህ ውድቅ ለተደረገ ሰነድ በአዲስ ቁጥር እርማት ይሰጥ?',
'Agt_Correct' => 'አርም',
'Agt_Guide_What_Title' => 'ይህ ምን ያደርጋል',
'Agt_Guide_What_Body' => 'እያንዳንዱ የተጠናቀቀ ሽያጭ እንደ AGT ኤሌክትሮኒክ ደረሰኝ ይሰጣል (ሲፈጠር ከተከፈለ FR፣ ካልሆነ FT)፣ እያንዳንዱ የተቀበለ መመለሻ ደግሞ እንደ የክሬዲት ማስታወሻ (NC)። እያንዳንዱ ሰነድ የAGT ተከታታዩን ቀጣይ ቁጥር ያገኛል፣ በAGT ቁልፍዎ ይፈረማል እና ለAGT ይላካል፤ AGT ከጥቂት ደቂቃዎች በኋላ ያረጋግጠዋል። ደረሰኙ እና የPDF ደረሰኙ የAGT ቁጥሩን፣ የደህንነት ቅንጭቡን እና QR ኮድ ያትማሉ።',
'Agt_Guide_Steps_Title' => 'ማዋቀር',
'Agt_Guide_Step_1' => 'በPortal do Contribuinte ላይ ኤሌክትሮኒክ ደረሰኝን ይቀላቀሉ (adesão) እና የAGT የግል ቁልፍዎን ያውርዱ።',
'Agt_Guide_Step_2' => 'በቅንብሮች ትር ላይ NIFዎን፣ ተቋምዎን እና ቁልፉን ያስገቡ፣ Homologação ን ይምረጡ፣ ያስቀምጡ እና ግንኙነትን ይፈትሹ የሚለውን ይጠቀሙ።',
'Agt_Guide_Step_3' => 'በተከታታይ ቁጥሮች ትር ላይ ለሚጠቀሙበት ለእያንዳንዱ የሰነድ አይነት (FR, FT, NC) ለአሁኑ ዓመት አንድ ተከታታይ ይጠይቁ።',
'Agt_Guide_Step_4' => 'የIVA መጠኖችዎን ከAGT ኮዶች ጋር ያዛምዱ እና ለ0% መስመሮች የነፃነት ኮዱን ያዘጋጁ።',
'Agt_Guide_Step_5' => 'ሞጁሉን በሲስተም ቅንብሮች > ባህሪያት ውስጥ ያብሩ፣ የሙከራ ሽያጭ ያድርጉ እና በሰነዶች ትር ላይ ትክክለኛ መሆኑን ያረጋግጡ።',
'Agt_Guide_Step_6' => 'AGT ለምርት አካባቢ ሲያጸድቅዎ ወደ Produção ይቀይሩ እና የምርት አካባቢ ተከታታዮችን ይጠይቁ።',
'Agt_Guide_Note_1' => 'የተሳወቀ ሽያጭ ወይም መመለሻ ከዚያ በኋላ ሊስተካከል ወይም ሊሰረዝ አይችልም። በሽያጭ መመለሻ (የክሬዲት ማስታወሻ) ያርሙት።',
'Agt_Guide_Note_2' => 'በAGT ውድቅ የተደረጉ ሰነዶች ውድቅ የተደረገውን በሚያመለክት አዲስ ቁጥር ይታረማሉ፤ የቀድሞው ቁጥር ዳግም ጥቅም ላይ አይውልም።',
'Agt_Guide_Note_3' => 'ከመስመር ውጭ የተደረጉ የPOS ሽያጮች ሲመሳሰሉ ይሳወቃሉ። AGT ከ24 ሰዓት በላይ ዘግይተው የተላኩ ሰነዶችን ይቀጣል።',
'Agt_Guide_Note_4' => 'አንድ መስመር የምርት ግብር እና የትዕዛዝ ግብርን በአንድ ላይ መያዝ አይችልም፤ AGT በእያንዳንዱ መስመር አንድ የIVA መጠን ይፈልጋል። መላኪያ እንደ ነፃ መስመር ይላካል።',
'Agt_Guide_Note_5' => 'የAGT ድምሮች በእያንዳንዱ መስመር ይሰላሉ እና በማጠጋጋት ምክንያት ከStocky ድምር በጥቂት ሳንቲሞች ሊለዩ ይችላሉ።',
