'Dgi_Api_Pending_Body' => 'DGI የe-MCF ገንቢ APIን የሚያወጣው ለተመዘገቡ ገንቢዎች ብቻ ነው (developper.dgirdc.cd)። እስኪገናኝ ድረስ ደረሰኞች የእርስዎን NIF / RCCM / Id. Nat. መግለጫዎች ይይዛሉ፣ ነገር ግን DEF ቁጥር፣ የማረጋገጫ ኮድ ወይም QR አይኖራቸውም።',
