'Dgi_Api_Url' => 'የAPI URL',
'Dgi_Api_Token' => 'የAPI ቶክን / ቁልፍ',
'Dgi_Token_Saved' => 'ቶክን ተቀምጧል (…{last4})። አዲስ የሚያስገቡት ለመተካት ብቻ ነው።',
'Dgi_Tax_Groups' => 'የግብር መጠን → የDGI ግብር ቡድን',
'Dgi_Tax_Groups_Hint' => 'በDGI የተገለጹ የግብር ቡድኖች (የካቲት 2026 የተዘመኑ)። የe-MCF ግንኙነቱ ቀጥታ ከሆነ በኋላ ጥቅም ላይ ይውላሉ።',
'Dgi_Group' => 'ቡድን',
'Dgi_No_Documents' => 'እስካሁን የተረጋገጡ ደረሰኞች የሉም — ማረጋገጫው የሚጀምረው የe-MCF ግንኙነቱ ቀጥታ ከሆነ በኋላ ነው።',
'Dgi_Guide_What_Title' => 'ዛሬ ይህ ምን ያደርጋል',
'Dgi_Guide_What_Body' => 'ሞጁሉ ሲበራ ደረሰኞች እና የPDF ደረሰኞች በfacture normalisée ላይ የሚያስፈልጉትን የሻጩን NIF፣ RCCM እና Id. Nat. ያትማሉ። ሙሉ ማረጋገጫ (በDGI የሚመለሱ DEF ቁጥር፣ ቆጣሪዎች፣ የማረጋገጫ ኮድ እና QR) የሚታከለው የe-MCF ገንቢ API ከተገናኘ በኋላ ነው።',
'Dgi_Guide_Steps_Title' => 'የe-MCF መዳረሻ ማግኘት',
'Dgi_Guide_Step_1' => 'በdevelopper.dgirdc.cd ላይ በNIFዎ መለያ ይፍጠሩ እና የe-MCF የሙከራ አካባቢ መዳረሻ ይጠይቁ።',
'Dgi_Guide_Step_2' => 'የAPI ሰነዱን (routes, DTOs, የግብር ቡድኖች) እና የሙከራ ምስክርነቶችን ያውርዱ።',
