'Inventory_Out_Of_Sync' => 'የእቃ ክምችት መለያው በእጅ ካለው ክምችት ጋር አይዛመድም',
'Inventory_Out_Of_Sync_Hint' => 'ያለ ሂሳብ መዝገብ የገባ ወይም የወጣ ክምችት (የመነሻ ብዛቶች፣ ከውጭ የገቡ፣ የቆዩ ማስተካከያዎች) በእቃ ክምችት መለያው ውስጥ የለም። ወደ ክምችቱ ዋጋ ለማድረስ የማመጣጠኛ መዝገብ ያስገቡ።',
