'Inventory_True_Up_Confirm' => 'ለልዩነቱ አንድ የጆርናል መዝገብ ይግባ? የመጀመሪያው ማመጣጠኛ ከመነሻ ቀሪ ካፒታል (Opening Balance Equity) አንጻር ይመዘገባል፣ የኋለኞቹ ደግሞ ከእቃ ማስተካከያዎች (Inventory Adjustments) አንጻር።',
