'Simple_List' => 'ቀላል ዝርዝር',
'Variants_Options_Hint' => 'እንደ ቀለም እና መጠን ያሉ አማራጮችን ይግለጹ፣ ከዚያም እያንዳንዱን ጥምረት ያመንጩ። እያንዳንዱ ጥምረት የራሱ ኮድ፣ ዋጋዎች እና ክምችት ያለው ተለዋዋጭ ይሆናል።',
