'Option_Values_Placeholder' => 'ዋጋ ይጻፉ እና Enter ይጫኑ (ለምሳሌ ቀይ፣ ሰማያዊ)',
'Swatches' => 'የቀለም ናሙናዎች',
'Add_Option' => 'አማራጭ አክል',
'Generate_Variants' => 'ተለዋዋጮችን አመንጭ',
'Apply_To_All' => 'ለሁሉም ተግብር',
'Variants_Guide' => 'የተለዋዋጮች መመሪያ',
'VG_Intro' => 'ተለዋዋጭ ምርት እንደ ብዙ ተለዋዋጮች ይሸጣል። ከአማራጮች (የሚመከር) ወይም እንደ ቀላል የስሞች ዝርዝር ይገንቧቸው። እያንዳንዱ ተለዋዋጭ የራሱ ኮድ፣ ዋጋዎች፣ ምስል እና ክምችት አለው።',
'VG_Options_Title' => 'የአማራጮች ሁነታ (ቀለም፣ መጠን...)',
'VG_Opt_Step1' => 'በካርዱ ራስጌ ላይ ያለውን መቀያየሪያ በ"አማራጮች" ላይ ያቆዩ።',
'VG_Opt_Step2' => 'እንደ ቀለም ወይም መጠን ያለ የአማራጭ ስም ይጻፉ፣ ወይም ከጥቆማዎቹ አንዱን ይምረጡ።',
'VG_Opt_Step3' => 'ዋጋ ይጻፉ (ለምሳሌ ቀይ) እና Enter ይጫኑ። ለእያንዳንዱ ዋጋ ይድገሙ፤ ኮማም ዋጋዎችን ይለያል። ዋጋን ለማስወገድ በላዩ ላይ ያለውን x ይጫኑ።',
'VG_Opt_Step4' => 'ለሁለተኛ ወይም ለሦስተኛ አማራጭ "አማራጭ አክል" የሚለውን ይጫኑ (ቢበዛ 3 አማራጮች)።',
'VG_Opt_Step5' => '"ተለዋዋጮችን አመንጭ" የሚለውን ይጫኑ። ለእያንዳንዱ ጥምረት አንድ ረድፍ ይፈጠራል እና ስሙ በራስ-ሰር ይገነባል፣ ለምሳሌ "ቀይ / S"።',
'VG_Opt_Step6' => 'በእያንዳንዱ ረድፍ ላይ ወጪ እና ዋጋ ያስገቡ፣ ወይም በ"ለሁሉም ተግብር" ውስጥ ዋጋ ጽፈው ወደ እያንዳንዱ ረድፍ ለመቅዳት ወጪ ወይም ዋጋ የሚለውን ይጫኑ።',
'VG_Opt_Step7' => 'ኮዶች ለእርስዎ ይመነጫሉ። የራስዎን ይጻፉ ወይም ሌላ ለማመንጨት የማደሻ አዶውን ይጫኑ።',
'VG_Opt_Step8' => 'አማራጭ፦ በአንድ አማራጭ ላይ "የቀለም ናሙናዎች" ላይ ምልክት ያድርጉ እና ለእያንዳንዱ ዋጋ ቀለም ይምረጡ፤ ሱቁ እንደ ባለቀለም ነጥብ ያሳየዋል።',
'VG_Rows_Title' => 'የተለዋዋጭ ረድፎች',
'VG_Rows_Text' => 'እያንዳንዱ ረድፍ ምስል፣ ኮድ፣ ባርኮድ፣ ወጪ፣ ዋጋ፣ የጅምላ ዋጋ እና አነስተኛ የሽያጭ ዋጋ አለው። ምርት ሲፈጥሩ ለእያንዳንዱ ተለዋዋጭ በየመጋዘኑ የመነሻ ክምችት ማስገባትም ይችላሉ። "ያልተሟላ" የሚል መለያ ረድፉ ለአንድ አማራጭ ዋጋ እንደጎደለው ያሳያል።',
'VG_List_Title' => 'የቀላል ዝርዝር ሁነታ',
'VG_List_Text' => 'የተለዋዋጭ ስም ይጻፉ እና ረድፍ ለመጨመር Enter ይጫኑ (ወይም አክል የሚለውን ይጫኑ)፣ ከዚያም ኮዱን እና ዋጋዎቹን ይሙሉ። ይህ የተለመደው አሰራር ሲሆን ለነባር ምርቶች ይገኛል።',
'VG_Edit_Title' => 'በኋላ ማስተካከል',
'VG_Edit_1' => 'ዋጋ ያክሉ እና "ተለዋዋጮችን አመንጭ" የሚለውን ይጫኑ፦ የጎደሉት ጥምረቶች ብቻ ይታከላሉ። ነባር ረድፎች ኮዶቻቸውን፣ ዋጋዎቻቸውን እና ታሪካቸውን ይይዛሉ።',
'VG_Edit_2' => 'ዋጋን ወይም አማራጭን ማስወገድ የሚጠቀሙበትን ረድፎች ያስወግዳል። ቀደም ብለው የተቀመጡ ረድፎች ምርቱን ሲያስቀምጡ ከማረጋገጫ በኋላ ይሰረዛሉ።',
'VG_Edit_3' => 'አሁንም ክምችት ያለው ተለዋዋጭ ሊወገድ አይችልም። መጀመሪያ ክምችቱን ያስተካክሉ ወይም ያስተላልፉ።',
'VG_Edit_4' => 'ወደ "ቀላል ዝርዝር" መቀየር ረድፎቹን እና ስሞቻቸውን ያቆያል፣ ነገር ግን የአማራጮቹን ፍቺዎች ያስወግዳል።',
'VG_Store_Title' => 'በመስመር ላይ ሱቁ ላይ',
'VG_Store_Text' => 'ደንበኞች ለእያንዳንዱ አማራጭ አንድ ዋጋ ይመርጣሉ፣ ለምሳሌ መጀመሪያ ቀለም ከዚያም መጠን። የሌሉ ጥምረቶች ይሰናከላሉ፣ ክምችት ያለቀባቸው ደግሞ በመስመር ተሰርዘው ይታያሉ። ወደ ጋሪው የሚገባው የተመረጠው ተለዋዋጭ ነው።',
