'Comm_G_Optional' => 'የሚመከር',
'Comm_G_Step_Program' => 'የኮሚሽን ፕሮግራም ይፍጠሩ',
'Comm_G_Step_Program_Help' => 'ፕሮግራም ደንቦችዎን ያቧድናል፣ ለምሳሌ "2026 Sales Team" ወይም "Summer Campaign"። ንቁ መሆን አለበት፣ እና ዛሬ በ«ከ ጀምሮ የሚሰራ» እና «እስከ የሚሰራ» ቀኖቹ መካከል መሆን አለበት።',
'Comm_G_Step_Program_Warn' => 'ፕሮግራሞች አሉዎት፣ ነገር ግን ዛሬ አንዳቸውም ንቁ አይደሉም። የንቁ ሳጥኑን እና የ«ከ ጀምሮ የሚሰራ» / «እስከ የሚሰራ» ቀኖቹን ያረጋግጡ።',
'Comm_G_Step_Agent' => 'የሽያጭ ወኪሎችዎን ያክሉ',
'Comm_G_Step_Agent_Help' => 'የሽያጭ ወኪል ኮሚሽን የሚያገኘው ሰው ነው። ወኪሎች ሰራተኞች ወይም እንደ አጣቃሾች ወይም ዳግም ሻጮች ያሉ የውጭ ሰዎች ሊሆኑ ይችላሉ።',
'Comm_G_Step_Link' => 'ወኪሎችን ከተጠቃሚ መለያዎች ጋር ያገናኙ',
'Comm_G_Step_Link_Help' => 'ወኪልን ከተጠቃሚ ጋር ማገናኘት ያ ተጠቃሚ የሚያደርጋቸው ሽያጮች በራስ-ሰር ለወኪሉ እንዲቆጠሩ ያደርጋል፣ በእያንዳንዱ ሽያጭ ላይ ወኪሉን መምረጥ ሳያስፈልግ።',
'Comm_G_Step_Link_Warn' => '{n} ንቁ ወኪል(ሎች) ከተጠቃሚ ጋር አልተገናኙም። የሚያገኙት አንድ ሰው በሽያጩ ላይ ሲመርጣቸው ብቻ ነው።',
'Comm_G_Step_Rule' => 'ቢያንስ አንድ ደንብ ያክሉ',
'Comm_G_Step_Rule_Help' => 'ደንብ ምን ያህል እንደሚከፈል ይወስናል፣ ለምሳሌ ከሽያጩ ድምር 5%። ንቁ መሆን እና ዛሬ ንቁ በሆነ ፕሮግራም ውስጥ መሆን አለበት።',
'Comm_G_Step_Rule_Warn' => 'ደንቦች አሉዎት፣ ነገር ግን ዛሬ ንቁ በሆነ ፕሮግራም ውስጥ ንቁ የሆነ አንድም የለም።',
'Comm_G_Step_Sale' => 'የተጠናቀቀ ሽያጭ ያድርጉ',
'Comm_G_Step_Sale_Help' => 'ኮሚሽኖች የሚፈጠሩት የተጠናቀቀ ሽያጭ ሲቀመጥ ነው (ሽያጭ ፍጠር፣ ሽያጭ አርትዕ ወይም POS)። ደንቦችዎ ከመኖራቸው በፊት የተደረጉ ሽያጮች አይሰሉም።',
'Comm_G_Step_Sale_Done' => 'እስካሁን {n} ኮሚሽን(ኖች) ተሰልተዋል።',
'Comm_G_Step_Approve' => 'ኮሚሽኖችን ያጽድቁ',
'Comm_G_Step_Approve_Help' => 'በኮሚሽን ሪፖርት ውስጥ የሚስማሙባቸውን በመጠባበቅ ላይ ያሉ ረድፎች ምልክት ያድርጉ እና የጸደቀ የሚለውን ይጫኑ። አሁን የሚጠብቅ ምንም የለም።',
'Comm_G_Step_Approve_Warn' => '{n} ኮሚሽን(ኖች) ማጽደቅን በመጠባበቅ ላይ ናቸው።',
'Comm_G_Step_Pay' => 'ለወኪሎችዎ ይክፈሉ',
'Comm_G_Step_Pay_Help' => 'በኮሚሽን ደረሰኞች ውስጥ ወኪል ይምረጡ፣ የጸደቁ ኮሚሽኖቻቸውን ምልክት ያድርጉ እና ደረሰኙን ያስቀምጡ። የተከፈሉ ይሆናሉ። አሁን ክፍያ የሚጠብቅ ምንም የለም።',
'Comm_G_Step_Pay_Warn' => '{n} የጸደቁ ኮሚሽን(ኖች) ክፍያን በመጠባበቅ ላይ ናቸው።',
'Comm_G_Try_Rule' => 'ደንብ ይሞክሩ',
'Comm_G_Try_Rule_Help' => 'ደንቡ በትክክል ምን እንደሚከፍል ለማየት ሽያጭ እና ደንብ ያስገቡ። ስሌቱ ሲስተሙ የሚጠቀምበት ተመሳሳይ ነው።',
'Comm_G_Sale_Total' => 'የሽያጭ ድምር',
'Comm_G_None' => 'ምንም',
'Comm_G_Commission' => 'ለዚህ ደንብ የሚሆን ኮሚሽን',
'Comm_G_No_Commission' => 'ኮሚሽን የለም',
'Comm_G_Calc_Base' => 'መነሻ መጠን ({source})፦ {base}',
'Comm_G_Calc_Zero_Base' => 'መነሻ መጠኑ 0 ስለሆነ ይህ ደንብ ምንም አይፈጥርም። የተከፈለ መጠን ምንጭ ሲሆን፣ ያልተከፈለ ሽያጭ ክፍያ እስኪመዘገብ ድረስ ምንም አያስገኝም።',
'Comm_G_Calc_Below_Min' => 'መነሻው ከዝቅተኛው ደረጃ {min} በታች ስለሆነ ይህ ደንብ ለዚህ ሽያጭ ምንም አይፈጥርም።',
'Comm_G_Calc_Pct' => '{value}% ከ{base} = {amount}',
'Comm_G_Calc_Fixed' => 'ቋሚ መጠን፦ በእያንዳንዱ ሽያጭ {amount}፣ የሽያጩ መጠን ምንም ይሁን',
'Comm_G_Calc_Capped' => 'ከከፍተኛው ጣራ ስለሚበልጥ ወደ {cap} ዝቅ ይላል',
'Comm_G_Calc_Zero' => 'ውጤቱ 0 ስለሆነ ምንም ኮሚሽን አይፈጠርም።',
'Comm_G_The_Flow' => 'ሂደቱ፣ ደረጃ በደረጃ',
'Comm_G_Flow_Program' => 'ፕሮግራም',
'Comm_G_Flow_Program_Help' => 'ፕሮግራም ይፍጠሩ እና የሚሰራባቸውን ቀኖች ያዘጋጁ።',
'Comm_G_Flow_Agent' => 'የሽያጭ ወኪሎች',
'Comm_G_Flow_Agent_Help' => 'ኮሚሽን የሚያገኙ ሰዎችን ያክሉ እና ሰራተኞችን ከተጠቃሚ መለያዎቻቸው ጋር ያገናኙ።',
'Comm_G_Flow_Rule' => 'ደንቦች',
'Comm_G_Flow_Rule_Help' => 'በፕሮግራሙ ውስጥ ደንቦችን ያክሉ፦ መቶኛ ወይም ቋሚ፣ ለሁሉም ወኪሎች ወይም ለአንድ ወኪል።',
'Comm_G_Flow_Sale' => 'ሽያጭ',
'Comm_G_Flow_Sale_Help' => 'የተጠናቀቀ ሽያጭ ይቀመጣል። እያንዳንዱ የሚዛመድ ደንብ አንድ በመጠባበቅ ላይ ያለ ኮሚሽን ይፈጥራል።',
'Comm_G_Flow_Approve' => 'ማጽደቅ',
'Comm_G_Flow_Approve_Help' => 'በኮሚሽን ሪፖርት ውስጥ በመጠባበቅ ላይ ያሉትን ኮሚሽኖች ይገምግሙ እና ያጽድቁ ወይም ይሰርዙ።',
'Comm_G_Flow_Pay' => 'ክፍያ',
'Comm_G_Flow_Pay_Help' => 'ለወኪሉ የኮሚሽን ደረሰኝ ይመዝግቡ። የሚሸፍናቸው ኮሚሽኖች የተከፈሉ ይሆናሉ።',
'Comm_G_How_It_Works' => 'እንዴት እንደሚሰራ',
'Comm_G_T_Credit' => 'ኮሚሽኑን የሚያገኘው የትኛው ወኪል ነው?',
'Comm_G_Credit_Intro' => 'እያንዳንዱ ሽያጭ የሚቆጠረው ቢበዛ ለአንድ ወኪል ነው። ሲስተሙ በዚህ ቅደም ተከተል ያረጋግጣል፦',
'Comm_G_Credit_Picked' => 'በሽያጩ ላይ የተመረጠው የሽያጭ ወኪል፦ በሽያጭ ፍጠር እና ሽያጭ አርትዕ ላይ ያለው የሽያጭ ወኪል መስክ፣ ወይም በPOS ላይ ያለው "የሸጠው" አዝራር። ያ ወኪል ከዚያ በኋላ ከተሰናከለ ሽያጩ ምንም አያስገኝም፤ ወደ ቀጣዮቹ አማራጮች አይሸጋገርም።',
'Comm_G_Credit_Seller' => 'ያለበለዚያ፣ በPOS ላይ ከተመረጠው ሻጭ ጋር የተገናኘው ወኪል (የPOS የሻጭ መቀያየሪያ ሲበራ)።',
'Comm_G_Credit_Cashier' => 'ያለበለዚያ፣ ሽያጩን ካስቀመጠው ተጠቃሚ ጋር የተገናኘው ወኪል።',
'Comm_G_Credit_Nobody' => 'ከእነዚህ አንዳቸውም ንቁ ወኪል ካላገኙ ሽያጩ ምንም ኮሚሽን አያስገኝም።',
'Comm_G_Credit_Note' => 'በPOS ላይ ወኪሉን በ"ራስ-ሰር" ላይ መተው አማራጮች 2 እና 3ን ይጠቀማል። ከ"ራስ-ሰር" አጠገብ የሚታየው ስም የሚቆጠርለት ወኪል ነው።',
'Comm_G_T_When' => 'ኮሚሽኖች መቼ ይሰላሉ እና ይዘመናሉ?',
'Comm_G_When_Intro' => 'ኮሚሽኖች መጀመሪያ የሚፈጠሩት የተጠናቀቀ ሁኔታ ያለው ሽያጭ ከእነዚህ ቦታዎች በአንዱ ሲቀመጥ ነው፦',
'Comm_G_When_Create' => 'ሽያጭ ፍጠር፦ ሽያጩ እንደ የተጠናቀቀ ሲቀመጥ።',
'Comm_G_When_Edit' => 'ሽያጭ አርትዕ፦ የተጠናቀቀ ሽያጭን ማስቀመጥ አሁን ባለው ድምሩ፣ ክፍያዎቹ እና ወኪሉ ከመጀመሪያው እንደገና ያሰላዋል፤ የተሰረዙ ኮሚሽኖችንም ጨምሮ።',
'Comm_G_When_Pos' => 'POS፦ ሽያጭ ሲጠናቀቅ፣ በኋላ የሚጠናቀቅ ረቂቅን ጨምሮ።',
'Comm_G_When_Payment' => 'ለተጠናቀቀ ሽያጭ ክፍያ ማከል፤ ይህም የተከፈለ መጠን ደንቦች ከሽያጩ በኋላ የተወሰዱ ክፍያዎችን እንዲይዙ የሚያስችለው ነው።',
'Comm_G_When_Cod' => 'የተላላኪ ሲደርስ ክፍያ፦ ተላላኪው የሰበሰበው ገንዘብ በሽያጩ ላይ እንደ ክፍያ ሲመዘገብ።',
'Comm_G_When_Not_Intro' => 'እነዚህ ኮሚሽኖችን አይፈጥሩም፦',
'Comm_G_When_Not_Status' => 'በመጠባበቅ ላይ ወይም የታዘዘ ተብለው የተቀመጡ ሽያጮች። ተስተካክለው እንደ የተጠናቀቀ ሲቀመጡ ማስገኘት ይጀምራሉ።',
'Comm_G_When_Not_Before' => 'ፕሮግራሙ ወይም ደንቡ ከመኖሩ በፊት የተቀመጡ ሽያጮች። በጀርባ አይሰሉም። እንዲህ ያለውን ሽያጭ በሽያጭ አርትዕ ውስጥ ከፍቶ ማስቀመጥ በሽያጩ ቀን ንቁ በነበሩት ደንቦች ያሰላዋል።',
'Comm_G_When_Not_Import' => 'ከፋይል የገቡ ሽያጮች።',
'Comm_G_When_Not_Online' => 'በመስመር ላይ ሱቁ ላይ የተሰጡ ትዕዛዞች።',
'Comm_G_T_Statuses' => 'የኮሚሽን ሁኔታዎች',
'Comm_G_Meaning' => 'ትርጉሙ',
'Comm_G_S_Pending' => 'ከሽያጭ አሁን የተሰላ። እስካሁን ማንም አላረጋገጠውም። በኮሚሽን ሪፖርት ውስጥ ያጽድቁት ወይም ይሰርዙት።',
'Comm_G_S_Approved' => 'ተረጋግጦ ስምምነት የተደረገበት። ለወኪሉ የሚከፈል ሲሆን በኮሚሽን ደረሰኝ ውስጥ ሊካተት ይችላል። ሽያጩ ተቀይሮ መጠኑ ከተቀየረ ለሌላ ግምገማ ወደ በመጠባበቅ ላይ ይመለሳል።',
'Comm_G_S_Paid' => 'በኮሚሽን ደረሰኝ ውስጥ የተካተተ። የመጨረሻ ነው፦ የተከፈሉ ኮሚሽኖች ፈጽሞ አይቀየሩም። ሽያጩ ከዚያ በኋላ ከተቀየረ ልዩነቱ እንደ የተለየ ማስተካከያ ይታከላል።',
'Comm_G_S_Cancelled' => 'አይከፈልም። በኋላ ክፍያዎች ወይም መመለሻዎች ሲመጡም ተሰርዞ ይቆያል። ሽያጩን በሽያጭ አርትዕ ውስጥ ማስቀመጥ፣ ወይም በሪፖርቱ ውስጥ ምልክት አድርጎ እንደገና አስላ የሚለውን መጫን እንደገና ያሰላዋል።',
'Comm_G_Field' => 'መስክ',
'Comm_G_T_Programs' => 'የኮሚሽን ፕሮግራሞች',
'Comm_G_Programs_Body' => 'ፕሮግራም የደንቦች መያዣ ነው፣ ብዙውን ጊዜ ለእያንዳንዱ ጊዜ ወይም ዘመቻ አንድ። ደንብ የሚሰራው ፕሮግራሙ ንቁ ሲሆን እና የሽያጩ ቀን በፕሮግራሙ ቀኖች ውስጥ ሲሆን ብቻ ነው። በአንድ ጊዜ በርካታ ፕሮግራሞች ንቁ ሊሆኑ ይችላሉ፣ ሁሉም ተፈጻሚ ይሆናሉ።',
'Comm_G_F_Program_Name' => 'ፕሮግራሙን ለመለየት የሚረዳዎ ማንኛውም ስም፣ ለምሳሌ "Q4 2026" ወይም "Black Friday"።',
'Comm_G_F_Program_Active' => 'በፕሮግራሙ ውስጥ ያሉትን ሁሉንም ደንቦች በአንድ ጊዜ ለማቆም ምልክቱን ያንሱ። ቀድሞ የተፈጠሩ ኮሚሽኖች አይነኩም።',
'Comm_G_F_Program_From' => 'ከዚህ ቀን በፊት የተደረጉ ሽያጮች በፕሮግራሙ ችላ ይባላሉ። የመጀመሪያ ቀን እንዳይኖረው ባዶ ይተዉት።',
'Comm_G_F_Program_To' => 'ከዚህ ቀን በኋላ የተደረጉ ሽያጮች በፕሮግራሙ ችላ ይባላሉ። ማብቂያ የሌለው ፕሮግራም ለማድረግ ባዶ ይተዉት።',
'Comm_G_T_Agents' => 'የሽያጭ ወኪሎች',
'Comm_G_Agents_Body' => 'የሽያጭ ወኪል ኮሚሽን የሚያገኘው ሰው ነው። ወኪል የሲስተሙ ተጠቃሚ መሆን አያስፈልገውም፦ የውጭ አጣቃሾች ወይም ዳግም ሻጮችም ወኪሎች ሊሆኑ ይችላሉ፣ እና በሽያጭ ላይ በተመረጡ ቁጥር ያገኛሉ።',
'Comm_G_F_Agent_Name' => 'በሽያጮች፣ በሪፖርቱ እና በደረሰኞች ላይ የሚታየው ስም።',
'Comm_G_F_Agent_Code' => 'እንደ የሰራተኛ ቁጥር ያለ አማራጭ ማጣቀሻ። በወኪሎች ዝርዝር ውስጥ ሊፈለግ ይችላል።',
'Comm_G_F_Agent_User' => 'ወኪሉን ከሰራተኛ ተጠቃሚ ጋር ያገናኛል። ያ ተጠቃሚ የሚያደርጋቸው ሽያጮች (ወይም በPOS ላይ እንደ ሻጭ የተመረጠባቸው) በራስ-ሰር ለዚህ ወኪል ይቆጠራሉ።',
'Comm_G_F_Agent_Active' => 'ንቁ ያልሆኑ ወኪሎች በአዲስ ሽያጮች ላይ ምንም አያገኙም እና ከወኪል መምረጫዎች ይጠፋሉ። ያለፉ ኮሚሽኖቻቸው ይቆያሉ።',
'Comm_G_T_Rules' => 'የኮሚሽን ደንቦች፦ እያንዳንዱ መስክ ሲብራራ',
'Comm_G_Rules_Body' => 'ደንብ በሽያጭ ላይ ምን ያህል እንደሚከፈል ይወስናል። ደንብን ከማስቀመጥዎ በፊት ለማረጋገጥ ከላይ ያለውን "ደንብ ይሞክሩ" ሳጥን ይጠቀሙ።',
'Comm_G_F_Rule_Program' => 'ደንቡ የሚገኝበት ፕሮግራም። ደንቡ የሚሰራው ያ ፕሮግራም ንቁ ሆኖ በቀኑ ውስጥ እስካለ ድረስ ብቻ ነው።',
'Comm_G_F_Rule_Type' => 'መቶኛ ከመነሻ መጠኑ ድርሻ ይከፍላል። ቋሚ በእያንዳንዱ ብቁ ሽያጭ ላይ መጠኑ ምንም ይሁን ተመሳሳይ መጠን ይከፍላል።',
'Comm_G_F_Rule_Source' => 'መቶኛው የሚወሰድበት። የሽያጭ ድምር የሽያጩ ጠቅላላ ድምር ነው። የተከፈለ መጠን ኮሚሽኑ በተሰላበት ጊዜ ደንበኛው የከፈለው ነው።',
'Comm_G_F_Rule_Value' => 'መቶኛው (5 ማለት 5%) ወይም ቋሚ መጠኑ፣ እንደ አይነቱ።',
'Comm_G_F_Rule_Min' => 'አማራጭ። መነሻ መጠናቸው ከዚህ በታች የሆኑ ሽያጮች ከዚህ ደንብ ምንም አያገኙም። ከደረጃው ጋር በትክክል እኩል የሆነ ሽያጭ ያገኛል።',
'Comm_G_F_Rule_Cap' => 'አማራጭ። ይህ ደንብ በአንድ ሽያጭ ላይ ሊከፍል የሚችለው ከፍተኛ መጠን። ለመቶኛም ሆነ ለቋሚ ደንቦች ይሰራል።',
'Comm_G_F_Rule_Applies' => 'ሁሉም ወኪሎች፦ እያንዳንዱ ወኪል ከዚህ ደንብ ያገኛል። የተወሰነ ወኪል፦ እርስዎ የመረጡት ወኪል ብቻ። ወኪል ያልተመረጠለት የተወሰነ ወኪል ደንብ ለማንም ፈጽሞ አይከፍልም።',
'Comm_G_F_Rule_Priority' => '"ከፍተኛ ቅድሚያ ያለው ደንብ ብቻ ይከፍላል" በተባለ ፕሮግራም ውስጥ ከፍተኛ ቁጥር ያለው ብቁ ደንብ ያሸንፋል፣ ሌሎቹም ይታለፋሉ። እኩል ሲሆኑ የተወሰነ ወኪል ደንብ የሁሉም ወኪሎች ደንብን ያሸንፋል። "እያንዳንዱ የሚዛመድ ደንብ ይከፍላል" በተባለ ፕሮግራም ውስጥ ቅድሚያ ቅደም ተከተሉን ብቻ ይወስናል።',
'Comm_G_F_Rule_Active' => 'ይህን አንድ ደንብ ለማቆም ምልክቱን ያንሱ። ቀድሞ የፈጠራቸው ኮሚሽኖች አይነኩም።',
'Comm_G_T_Stacking' => 'በአንድ ሽያጭ ላይ በርካታ ደንቦች',
'Comm_G_Stacking_Body' => 'እያንዳንዱ ፕሮግራም ደንቦቹ እንዴት እንደሚጣመሩ ይወስናል (በፕሮግራሙ ላይ ያለው "በርካታ ደንቦች ሲዛመዱ" ቅንብር)።

ከፍተኛ ቅድሚያ ያለው ደንብ ብቻ ይከፍላል (ለአዲስ ፕሮግራሞች ነባሪ)፦ ደንቦች ከከፍተኛው ቅድሚያ ጀምሮ ወደ ታች ይሞከራሉ፣ ለሽያጩ ብቁ የሆነው የመጀመሪያው ይከፍላል። ደንብ ብቁ የሚሆነው ሽያጩ ዝቅተኛ ደረጃውን ሲደርስ እና ውጤቱ ከ0 በላይ ሲሆን ነው። ይህ ደረጃዎችን ቀላል ያደርጋል፦ "10,000 እና ከዚያ በላይ በሆኑ ሽያጮች ላይ 7%" በቅድሚያ 10 እና "5%" በቅድሚያ 0። ለሳራ ልዩ መጠን ለመስጠት ከሁሉም ወኪሎች ደንብ ከፍ ያለ ቅድሚያ ያለው የተወሰነ ወኪል ደንብ ለእሷ ያክሉ።

እያንዳንዱ የሚዛመድ ደንብ ይከፍላል፦ ሁሉም የሚዛመዱ ደንቦች ይከፍላሉ እና መጠኖቹ ይደመራሉ። የ3% የሁሉም ወኪሎች ደንብ እና ለሳራ የ2% የተወሰነ ወኪል ደንብ ለሳራ 5% ይሰጣሉ።

ፕሮግራሞች አንዳቸው ከሌላው የተለዩ ናቸው፦ እያንዳንዱ ንቁ ፕሮግራም በራሱ ይከፍላል፣ ስለዚህ አንድ ሽያጭ ከመሠረታዊ ፕሮግራም እና ከዘመቻ ፕሮግራም በአንድ ጊዜ ሊያገኝ ይችላል።',
'Comm_G_T_Paying' => 'ለወኪሎች በኮሚሽን ደረሰኞች መክፈል',
'Comm_G_Paying_Body' => 'የኮሚሽን ደረሰኞችን ይክፈቱ እና አክል የሚለውን ይጫኑ። ወኪሉን ይምረጡ፦ የጸደቁ ኮሚሽኖቻቸው ይዘረዘራሉ። የሚከፍሏቸውን ምልክት ያድርጉ፤ መጠኑ በድምራቸው ይሞላል፣ እና ማስተካከል ይችላሉ። ማጣቀሻው በራስ-ሰር ይሞላል (CR-000001, CR-000002...)፣ እና የክፍያ ዘዴውን፣ ቀኑን እና ማስታወሻ ማከል ይችላሉ።

ደረሰኙን ማስቀመጥ ምልክት የተደረገባቸውን ኮሚሽኖች እንደ የተከፈሉ ምልክት ያደርጋል እና ከደረሰኙ ጋር ያገናኛቸዋል። ሊከፈሉ የሚችሉት የጸደቁ ኮሚሽኖች ብቻ ናቸው፣ ስለዚህ መጀመሪያ በኮሚሽን ሪፖርት ውስጥ ያጽድቋቸው።

አሉታዊ ማስተካከያዎች (ለወኪሉ በብልጫ የተከፈለ ገንዘብ) እንዲሁ ይዘረዘራሉ። ከዚያ ክፍያ እንዲቀነሱ ከወኪሉ ቀጣይ ኮሚሽኖች ጋር አብረው ምልክት ያድርጉባቸው።

ደረሰኝ የክፍያው መዝገብ ብቻ ነው፦ ወጪ አይፈጥርም ወይም በመለያዎችዎ ውስጥ ገንዘብ አያንቀሳቅስም። ክፍያዎችን በወጪዎች ወይም በሒሳብ አስተዳደር ውስጥ የሚከታተሉ ከሆነ እዚያም ይመዝግቧቸው።',
'Comm_G_T_Snapshot' => 'ሽያጭ ሲቀየር',
'Comm_G_Snapshot_Body' => 'ኮሚሽኖች ሽያጩን ይከተላሉ። ኮሚሽኖች ያሉት ሽያጭ በተቀየረ ቁጥር አሁን ካሉት አሃዞቹ እንደገና ይሰላሉ፦ የሽያጩ ድምር የተቀበሉ መመለሻዎች ተቀንሰው፣ እና የተከፈለው መጠን ተመላሽ ገንዘቦች ተቀንሰው።

ያልተከፈሉ ኮሚሽኖች (በመጠባበቅ ላይ ወይም የጸደቁ) በቀላሉ ይዘምናሉ። መጠኑ የተቀየረ የጸደቀ ኮሚሽን አንድ ሰው እንደገና እንዲያረጋግጠው ወደ በመጠባበቅ ላይ ይመለሳል። ከዚያ በኋላ የማይከፈል (ሽያጩ ተሰርዟል፣ ሙሉ በሙሉ ተመልሷል፣ ወኪሉ ተቀይሯል) ይወገዳል።

የተከፈሉ ኮሚሽኖች ፈጽሞ አይቀየሩም። ልዩነቱ ማስተካከያ የሚል ምልክት ያለው አዲስ በመጠባበቅ ላይ ያለ ረድፍ ይሆናል፦ ተጨማሪ ሲከፈል አዎንታዊ (ለምሳሌ የተከፈለ መጠን ሽያጭ ቀሪው ሲከፈል)፣ ለወኪሉ በብልጫ ሲከፈል አሉታዊ (ለምሳሌ ከመመለሻ በኋላ)። ያጽድቁት እና በወኪሉ ቀጣይ ደረሰኝ ውስጥ ያካትቱት።

እያንዳንዱ ኮሚሽን መጀመሪያ በተገኘበት ጊዜ የነበሩትን የደንቡን ውሎች (አይነት፣ መጠን፣ ደረጃ፣ ጣራ) ይይዛል። በኋላ ደንብን መቀየር ወይም ማጥፋት የቆዩ ሽያጮች እንደገና ሲሰሉ ዋጋቸውን አይቀይርም።',
'Comm_G_T_Permissions' => 'ማን ምን ማድረግ ይችላል',
'Comm_G_Permission' => 'ፈቃድ',
'Comm_G_Lets_You' => 'የሚፈቅደው',
'Comm_G_P_View' => 'ሁሉንም የኮሚሽን ገጾች ማየት፦ ፕሮግራሞች፣ ወኪሎች፣ ደንቦች፣ ደረሰኞች፣ ሪፖርቱ እና ይህ መመሪያ።',
'Comm_G_P_Add' => 'ፕሮግራሞችን፣ ወኪሎችን እና ደንቦችን መፍጠር፣ እና የኮሚሽን ደረሰኞችን መመዝገብ (ለወኪሎች መክፈል)።',
'Comm_G_P_Edit' => 'ፕሮግራሞችን፣ ወኪሎችን እና ደንቦችን ማስተካከል፣ እና በኮሚሽን ሪፖርት ውስጥ ኮሚሽኖችን ማጽደቅ ወይም መሰረዝ።',
'Comm_G_P_Delete' => 'ፕሮግራሞችን፣ ወኪሎችን እና ደንቦችን መሰረዝ።',
'Comm_G_T_Faq' => 'ጥያቄዎች እና መልሶች',
'Comm_G_Q_Empty' => 'ሁሉንም አዘጋጅቻለሁ ግን የኮሚሽን ሪፖርቱ ባዶ ነው።',
'Comm_G_A_Empty' => 'የሚከተሉትን ያረጋግጡ፦ ሽያጩ ደንቡ ከተፈጠረ በኋላ ተቀምጧል፤ ሽያጩ የተጠናቀቀ ነው፤ ሽያጩ ወኪል አለው (በሽያጩ ላይ የተመረጠ፣ ወይም ያደረገው ተጠቃሚ ከወኪል ጋር የተገናኘ ነው)፤ ፕሮግራሙ ንቁ ሲሆን የሽያጩ ቀን በቀኖቹ ውስጥ ነው፤ ደንቡ ንቁ ሲሆን ለዚያ ወኪል ይተገበራል፤ እና ሽያጩ በደንቡ ዝቅተኛ ደረጃ ላይ ወይም ከዚያ በላይ ነው። እንዲሁም የሪፖርቱን የቀን ማጣሪያ ያረጋግጡ፦ ኮሚሽኑ በተሰላበት ቀን ያጣራል።',
'Comm_G_Q_Twice' => 'አንድ ወኪል በአንድ ሽያጭ ላይ ሁለት ኮሚሽኖችን አገኘ።',
'Comm_G_A_Twice' => 'ሁለት ደንቦች ከፍለዋል፦ ወይ ፕሮግራሙ "እያንዳንዱ የሚዛመድ ደንብ ይከፍላል" ተብሎ ተቀናብሯል፣ ወይም ደንቦቹ በሁለት የተለያዩ ንቁ ፕሮግራሞች ውስጥ ናቸው (እያንዳንዱ ፕሮግራም በራሱ ይከፍላል)። አንድ ብቻ መክፈል ካለበት ፕሮግራሙን ወደ "ከፍተኛ ቅድሚያ ያለው ደንብ ብቻ ይከፍላል" ያዘጋጁ። ሽያጭን እንደገና ማስቀመጥ ኮሚሽንን ፈጽሞ አይደግምም።',
'Comm_G_Q_Rate' => 'የደንብን መጠን ከቀየርኩ የቆዩ ኮሚሽኖች ይቀየራሉ?',
'Comm_G_A_Rate' => 'አይቀየሩም። እያንዳንዱ ኮሚሽን ሽያጩ በኋላ እንደገና ቢሰላም የተገኘበትን ደንብ ውሎች ይይዛል። አዲሱ መጠን ከአሁን ጀምሮ ለሚገኙ ኮሚሽኖች ጥቅም ላይ ይውላል።',
'Comm_G_Q_Return' => 'ደንበኛው እቃዎቹን መለሰ። ኮሚሽኑ ምን ይሆናል?',
'Comm_G_A_Return' => 'በራስ-ሰር ይቀንሳል። የተቀበለ መመለሻ የሽያጩን ድምር ይቀንሳል፣ ተመላሽ ገንዘብ ደግሞ የተከፈለውን መጠን ይቀንሳል። ኮሚሽኑ ገና ካልተከፈለ ይዘምናል (ለሙሉ መመለሻ ይወገዳል)። ቀድሞ ተከፍሎ ከነበረ አሉታዊ ማስተካከያ ይታከልና ከወኪሉ ቀጣይ ደረሰኝ ይቀነሳል።',
'Comm_G_Q_Wrong_Agent' => 'የተሳሳተ ወኪል ቆጥሬያለሁ። እንዴት ላስተካክለው?',
'Comm_G_A_Wrong_Agent' => 'ሽያጩን ያስተካክሉ፣ ትክክለኛውን የሽያጭ ወኪል ይምረጡ እና ያስቀምጡ። ኮሚሽኖቹ ወደ ትክክለኛው ወኪል ይዛወራሉ። የመጀመሪያው ወኪል ቀድሞ ተከፍሎት ከነበረ ለእሱ አሉታዊ ማስተካከያ ይታከላል።',
'Comm_G_Q_Inactive' => 'ወኪልን ሳሰናክል ምን ይሆናል?',
'Comm_G_A_Inactive' => 'በአዲስ ሽያጮች ላይ ማግኘት ያቆማሉ እና ከወኪል መምረጫዎች ይደበቃሉ። ያሉ ኮሚሽኖቻቸው ይቆያሉ፣ አሁንም ሊጸድቁ እና ሊከፈሉ ይችላሉ፣ እና የሽያጮቻቸውን ለውጦች ይከተላሉ። ያ ወኪል ተመርጦ የተቀመጠ ሽያጭ ወደ ሌላ ወኪል አይሸጋገርም።',
'Comm_G_Q_Partial' => 'የተከፈለ መጠን ደንቦች ከፊል ክፍያዎችን እንዴት ያስተናግዳሉ?',
'Comm_G_A_Partial' => 'ያልተከፈለ ሽያጭ ምንም አያስገኝም። ኮሚሽኑ የሚፈጠረው ገንዘብ መጀመሪያ ሲቀበል ነው (በክፍያ ጊዜ ወይም ክፍያ ሲታከል) እና ተጨማሪ ክፍያዎች ሲመጡ ያድጋል። ከፊሉ ቀድሞ ተከፍሎ ከነበረ ቀሪው እንደ አዎንታዊ ማስተካከያ ይመጣል።',
'Comm_G_Q_Undo' => 'ክፍያን ወይም ስረዛን መቀልበስ እችላለሁ?',
'Comm_G_A_Undo' => 'ክፍያን፣ አይቻልም፦ የተከፈለ የመጨረሻ ነው እና ደረሰኞች ሊስተካከሉ ወይም ሊሰረዙ አይችሉም፣ ስለዚህ ከማስቀመጥዎ በፊት ምልክት የተደረገባቸውን ኮሚሽኖች እና መጠኑን ያረጋግጡ። ስረዛን፣ ይቻላል፦ በኮሚሽን ሪፖርት ውስጥ ረድፉን ምልክት አድርገው እንደገና አስላ የሚለውን ይጫኑ፣ ወይም ሽያጩን በሽያጭ አርትዕ ውስጥ እንደገና ያስቀምጡ።',
'Comm_G_Q_Dates' => 'የፕሮግራሙ ቀኖች የትኛውን ቀን ይጠቀማሉ?',
'Comm_G_A_Dates' => 'የሽያጩን የራሱን ቀን እንጂ የተቀመጠበትን ቀን አይደለም። ባለፈው ወር ቀን ያለው ሽያጭ የሚጠቀመው ባለፈው ወር የሚሰሩ የነበሩ ፕሮግራሞችን ብቻ ነው።',
'Comm_G_When_Changes' => 'ከዚያ በኋላ ኮሚሽኖች ባሉት ሽያጭ ላይ የሚደረግ ማንኛውም ለውጥ በራሱ ያዘምናቸዋል፦ የተስተካከሉ ወይም የተሰረዙ ክፍያዎች፣ መመለሻዎች እና ተመላሽ ገንዘቦች፣ ሁኔታው ከተጠናቀቀ መውጣቱ፣ ወይም ሽያጩ መሰረዙ።',
'Comm_G_F_Program_Mode' => 'በዚህ ፕሮግራም ውስጥ በርካታ ደንቦች ከአንድ ሽያጭ ጋር ሲዛመዱ የሚሆነው። "ከፍተኛ ቅድሚያ ያለው ደንብ ብቻ ይከፍላል"፦ ደንቦች ከከፍተኛው ቅድሚያ ጀምሮ ወደ ታች ይሞከራሉ እና ብቁ የሆነው የመጀመሪያው ይከፍላል። "እያንዳንዱ የሚዛመድ ደንብ ይከፍላል"፦ ሁሉም ይከፍላሉ እና መጠኖቹ ይደመራሉ።',
'Comm_G_Q_Mode_Old' => 'ቅድሚያዎችን አዘጋጅቻለሁ፣ ግን ደንቦቹ አሁንም ይደመራሉ።',
'Comm_G_A_Mode_Old' => 'ያ ፕሮግራም "እያንዳንዱ የሚዛመድ ደንብ ይከፍላል" ተብሎ ተቀናብሯል። ይህ ቅንብር ከመኖሩ በፊት የተፈጠሩ ፕሮግራሞች ክፍያዎቻቸው እንዳይቀየሩ ያንን አሰራር ይይዛሉ። ፕሮግራሙን ያስተካክሉ እና "ከፍተኛ ቅድሚያ ያለው ደንብ ብቻ ይከፍላል" የሚለውን ይምረጡ።',
'Comm_G_Q_Negative' => 'አሉታዊ ኮሚሽን ለምን አለ?',
'Comm_G_A_Negative' => 'ማስተካከያ ነው፦ በመመለሻ፣ በተመላሽ ገንዘብ፣ በዝቅተኛ ድምር፣ በተቀየረ ወኪል ወይም በተሰረዘ ሽያጭ ምክንያት ለወኪሉ ሽያጩ አሁን ከሚያስገኘው በላይ ተከፍሏል። ያጽድቁት እና እንዲቀነስ በወኪሉ ቀጣይ ደረሰኝ ውስጥ ምልክት ያድርጉበት።',
'Comm_Rule_Mode' => 'በርካታ ደንቦች ሲዛመዱ',
'Comm_Mode_Highest' => 'ከፍተኛ ቅድሚያ ያለው ደንብ ብቻ ይከፍላል',
'Comm_Mode_All' => 'እያንዳንዱ የሚዛመድ ደንብ ይከፍላል (ይደመራሉ)',
'Comm_Mode_Highest_Short' => 'ከፍተኛ ቅድሚያ ያሸንፋል',
'Comm_Mode_All_Short' => 'ደንቦች ይደመራሉ',
'Comm_Mode_Highest_Help' => 'ደንቦች ከከፍተኛው ቅድሚያ ጀምሮ ወደ ታች ይሞከራሉ፤ ለሽያጩ ብቁ የሆነው የመጀመሪያው ይከፍላል እና ሌሎቹ ይታለፋሉ። ለደረጃዎች ጥሩ ነው፣ ለምሳሌ ከ10,000 በላይ 7% በቅድሚያ 10 እና ለሌሎቹ ሁሉ 5% በቅድሚያ 0።',
'Comm_Mode_All_Help' => 'ከወኪሉ ጋር የሚዛመድ እያንዳንዱ ደንብ በሽያጩ ላይ ይከፍላል፣ ስለዚህ መጠኖቹ ይደመራሉ። ቅድሚያ ቅደም ተከተሉን ብቻ ይወስናል።',
'Comm_Priority_Help_Highest' => 'ይህ ፕሮግራም የሚከፍለው ብቁ የሆነውን ከፍተኛ ቅድሚያ ያለው ደንብ ብቻ ነው። ይህ ደንብ ሊያሸንፋቸው ከሚገባው ደንቦች የበለጠ ከፍተኛ ቅድሚያ ይስጡት። እኩል ሲሆኑ የተወሰነ ወኪል ደንብ የሁሉም ወኪሎች ደንብን ያሸንፋል።',
'Comm_Priority_Help_All' => 'ይህ ፕሮግራም እያንዳንዱን የሚዛመድ ደንብ ይከፍላል፣ ስለዚህ ይህ ደንብ በሌሎቹ ላይ ይደመራል። ቅድሚያ ቅደም ተከተሉን ብቻ ይወስናል።',
'Comm_Recalculate' => 'እንደገና አስላ',
'Comm_Recalculate_Help' => 'ምልክት የተደረገባቸውን ረድፎች ሽያጮች አሁን ካሉት አሃዞቻቸው እንደገና ያሰላል፣ የተሰረዙ ኮሚሽኖችንም ጨምሮ።',
'Comm_Adjustment' => 'ማስተካከያ',
'Comm_Adjustment_Help' => 'ሽያጩ ከዚያ በኋላ ስለተቀየረ ቀድሞ ለተከፈለ ኮሚሽን የሚደረግ እርማት። አሉታዊ መጠን ከወኪሉ ቀጣይ ደረሰኝ ይቀነሳል።',
'Comm_Cancel_Confirm' => 'የተመረጡት ኮሚሽኖች ይሰረዙ?',
'Comm_Cancel_Confirm_Help' => 'አይከፈሉም፣ እና በኋላ ክፍያዎች ወይም መመለሻዎች ሲመጡም ተሰርዘው ይቆያሉ። ሽያጩን በሽያጭ አርትዕ ውስጥ ማስቀመጥ ወይም እንደገና አስላ የሚለውን መጫን እንደገና ያሰላቸዋል።',
'Fashion_Tiles_Hint' => 'ራስ-ሰር የምድብ ሰሌዳዎችን ለመተካት የራስዎን ሰሌዳዎች (ምስል፣ ርዕስ እና ሊንክ) ያክሉ።',

// Online Store: Car Dealership theme
'Car_Dealership_Theme' => 'የመኪና አከፋፋይ ገጽታ',
'Cars_Theme_Hint' => 'መኪናዎች መደበኛ ምርቶች ናቸው፦ እንደተለመደው ዋጋውን፣ ፎቶዎቹን እና መግለጫውን ያክሉ፣ ከዚያም በምርት ቅጹ ላይ ያለውን የተሽከርካሪ ዝርዝሮች ካርድ ይሙሉ (አምራች፣ ሞዴል፣ ዓመት፣ የተጓዘ ርቀት …)። ገዢዎች ጥያቄዎችን፣ የሙከራ ማሽከርከር ጥያቄዎችን እና የልውውጥ ግምቶችን ይልካሉ፤ እነዚህም በሱቅ › የተሽከርካሪ ተስፋ ደንበኞች ውስጥ ይደርሳሉ።',
