'Rst_Guide_Step_Floor_Help' => 'ክፍሎችዎን (የውስጥ አዳራሽ፣ በረንዳ…) እና ጠረጴዛዎቻቸውን ከመቀመጫ ብዛታቸው ጋር ያክሉ። "ብዙ አክል" T1–T20ን በአንድ ጊዜ ይፈጥራል።',
'Rst_Guide_Step_Stations' => 'የወጥ ቤት ጣቢያዎች',
'Rst_Guide_Step_Stations_Ok' => '{n} ጣቢያዎች።',
'Rst_Guide_Step_Stations_Help' => 'ጣቢያዎች (ጥብስ፣ መጥበሻ፣ ቀዝቃዛ፣ ጣፋጭ ምግቦች፣ መጠጦች…) እያንዳንዱ አብሳይ የራሱን ምግቦች ብቻ እንዲያይ የወጥ ቤት ማሳያውን ይከፋፍላሉ።',
'Rst_Guide_Step_Dishes' => 'ምግቦች እና ተጨማሪዎች',
'Rst_Guide_Step_Dishes_Ok' => '{n} ምግቦች ተዘጋጅተዋል፣ {groups} የተጨማሪ ቡድኖች።',
'Rst_Guide_Step_Dishes_Help' => 'ምግቦች የተለመዱ ምርቶችዎ ናቸው። በሬስቶራንት › ሜኑ ውስጥ ጣቢያ፣ የዝግጅት ጊዜ፣ የአመጋገብ መለያዎች እና የተጨማሪ ቡድኖች (መጠኖች፣ ተጨማሪዎች) ይስጧቸው።',
'Rst_Guide_Step_Payments' => 'ክፍያዎች',
'Rst_Guide_Step_Payments_Ok' => 'ጥሬ ገንዘብን ጨምሮ {n} የክፍያ ዘዴዎች ዝግጁ ናቸው፣ ለቀጥታ ደንበኛ ሂሳቦችም ነባሪ ደንበኛ ተወስኗል።',
'Rst_Guide_Step_Payments_Help' => 'ሂሳቦች ቢያንስ አንድ ንቁ የክፍያ ዘዴ፣ የጥሬ ገንዘብ ዘዴ (መልስ የሚሰጠው ከጥሬ ገንዘብ ነው) እና በስርዓት ቅንብሮች ውስጥ ነባሪ ደንበኛ ያስፈልጋቸዋል።',
'Rst_Guide_Step_Staff' => 'የሰራተኞች ፍቃዶች',
'Rst_Guide_Step_Staff_Help' => 'ትዕዛዝ መቀበል የሚችሉ ሚናዎች: {waiters}፣ የወጥ ቤት ማሳያን መጠቀም የሚችሉ: {kitchen}፣ ክፍያ መቀበል የሚችሉ: {cashiers}። ለእያንዳንዱ ሚና ሥራው የሚፈልገውን ብቻ ይስጡ ("ማን ምን ይሰራል" የሚለውን ይመልከቱ)።',
'Rst_Guide_Step_First' => 'የመጀመሪያ ሂሳብዎ',
'Rst_Guide_Step_First_Ok' => 'እስካሁን {n} ሂሳቦች ተከፍለዋል።',
'Rst_Guide_Step_First_Help' => 'በአዳራሽ ካርታው ላይ የሙከራ ጠረጴዛ ያስቀምጡ፣ ምግብ ያክሉ፣ ይላኩት፣ በወጥ ቤት ማሳያው ላይ ዝግጁ ብለው ምልክት ያድርጉ እና ክፍያውን ይቀበሉ።',
'Rst_Guide_Step_Qr' => 'የQR የጠረጴዛ ማዘዣ',
'Rst_Guide_Step_Qr_On' => 'በርቷል። {n} ጠረጴዛዎች QR ኮድ አላቸው።',
'Rst_Guide_Step_Qr_Help' => 'እንግዶች በጠረጴዛው ላይ ያለውን ኮድ ይቃኛሉ፣ በስልካቸው ምግቦችን ይመርጣሉ እና ወደ ጠረጴዛው ትዕዛዝ ይልካሉ። በሬስቶራንት ቅንብሮች ውስጥ ያብሩት፣ ከዚያ ኮዶቹን ያትሙ።',
'Rst_Guide_Step_Booking' => 'የመስመር ላይ የጠረጴዛ ቦታ ማስያዣ',
'Rst_Guide_Step_Booking_On' => 'በርቷል። ከመስመር ላይ ሱቁ የሚመጡ ቦታ ማስያዣዎች እንዲረጋገጡ በቦታ ማስያዣዎች ስር ይደርሳሉ።',
'Rst_Guide_Step_Booking_Help' => 'እንግዶች ከመስመር ላይ ሱቁ ጠረጴዛ እንዲያስይዙ ይፍቀዱ። የማስያዣ ሰዓቶችን፣ የጊዜ ክፍተቱን እና ከፍተኛ የእንግዶች ብዛትን በሬስቶራንት ቅንብሮች ውስጥ ያዘጋጁ።',
'Rst_Guide_Step_Store' => 'የመስመር ላይ ሱቅ እና የሬስቶራንት ገጽታ',
'Rst_Guide_Step_Store_On' => 'የሬስቶራንት ገጽታ ንቁ ነው። የመስመር ላይ ትዕዛዞች ወደ ወጥ ቤት የሚደርሱት: {mode}።',
'Rst_Guide_Step_Store_Help' => 'በመስመር ላይ ሱቅ › ቅንብሮች ውስጥ "ሬስቶራንት" ገጽታን ይምረጡ: መነሻ ገጹ ሜኑዎ ይሆናል፣ ከተጨማሪዎች፣ ከመውሰድ / ከማድረስ እና ከጠረጴዛ ቦታ ማስያዣ ጋር።',
'Rst_Guide_How' => 'እንዴት እንደሚሰራ',
'Rst_Guide_Service' => 'አንድ አገልግሎት፣ ደረጃ በደረጃ',
'Rst_Guide_Service_1_T' => 'ማስቀመጥ',
'Rst_Guide_Service_1' => 'በአዳራሽ ካርታው ላይ ነፃ ጠረጴዛ ይምረጡ፣ የእንግዶችን ቁጥር እና አስተናጋጁን ያስገቡ፣ ከዚያ "እንግዶችን አስቀምጥ እና ትዕዛዝ ተቀበል" የሚለውን ይጫኑ። ቦታ ያስያዙ እንግዶች ከቦታ ማስያዣቸው ይቀመጣሉ።',
'Rst_Guide_Service_2_T' => 'ማዘዝ',
'Rst_Guide_Service_2' => 'በትዕዛዝ ማያው ላይ ምግቦችን ይንኩ። ተጨማሪዎችን፣ መቀመጫን እና ዙርን ይምረጡ፤ ለወጥ ቤት ማስታወሻ ያክሉ። አንድን ዙር በኋላ ለማስጀመር ያቆዩት።',
'Rst_Guide_Service_3_T' => 'መላክ',
'Rst_Guide_Service_3' => '"ላክ" አዲሶቹን ምግቦች በአንድ የወጥ ቤት ቲኬት ላይ ያደርጋል። ገና ያልተላኩ ምግቦች አሁንም ሊቀየሩ ወይም ሊወገዱ ይችላሉ፤ ከዚያ በኋላ ውድቅ ሊደረጉ የሚችሉት በምክንያት ብቻ ነው።',
'Rst_Guide_Service_4_T' => 'ማብሰል',
'Rst_Guide_Service_4' => 'የወጥ ቤት ማሳያው ቲኬቱን በእያንዳንዱ ጣቢያ ያሳያል። አብሳዮች ይጀምሩታል፣ ምግቦችን ሲጨርሱ ምልክት ያደርጋሉ እና ሁሉም ዝግጁ ሲሆን ይጨርሱታል።',
'Rst_Guide_Service_5_T' => 'ማቅረብ',
'Rst_Guide_Service_5' => 'ዝግጁ ምግቦች በአዳራሽ ካርታው እና በትዕዛዝ ማያው ላይ ይታያሉ። አስተናጋጁ ያቀርባቸዋል እና "እንደቀረበ ምልክት አድርግ" የሚለውን ይንካል።',
'Rst_Guide_Service_6_T' => 'ሂሳብ',
'Rst_Guide_Service_6' => '"ሂሳብ እና ክፍያ" ሂሳቡን ያትማል እና ክፍያውን ይቀበላል: ሙሉ ሂሳብ፣ በእኩል የተከፋፈለ ወይም በምግብ። እያንዳንዱ ክፍያ መደበኛ የPOS ሽያጭ ነው።',
'Rst_Guide_Service_7_T' => 'ማጽዳት',
'Rst_Guide_Service_7' => 'ሁሉም ሲከፈል ትዕዛዙ ይዘጋል እና ጠረጴዛው "ማጽዳት ያስፈልገዋል" ይሆናል (ወይም በሬስቶራንት ቅንብሮች መሰረት በቀጥታ ነፃ ይሆናል)።',
'Rst_Guide_Roles' => 'ማን ምን ይሰራል',
'Rst_Guide_Roles_Help' => 'የሬስቶራንት ፍቃዶች በየሚናው በቡድን ፍቃዶች ውስጥ ይሰጣሉ። አንድ ተጠቃሚ የብዙ ሚናዎችን ፍቃዶች ሊይዝ ይችላል።',
'Rst_Guide_Job' => 'ሥራ',
'Rst_Guide_Give' => 'እነዚህን ፍቃዶች ይስጡ',
'Rst_Guide_Job_Waiter' => 'አስተናጋጅ',
'Rst_Guide_Job_Cook' => 'አብሳይ',
'Rst_Guide_Job_Cashier' => 'ካሽየር',
'Rst_Guide_Job_Host' => 'እንግዳ ተቀባይ / መቀበያ',
'Rst_Guide_Job_Supervisor' => 'ተቆጣጣሪ',
'Rst_Guide_Job_Manager' => 'ሥራ አስኪያጅ',
'Rst_Guide_Menu' => 'ሜኑ፣ ጣቢያዎች እና ተጨማሪዎች',
'Rst_Guide_Menu_1' => 'የሚሸጡት እያንዳንዱ ምርት ምግብ ሊሆን ይችላል። ሬስቶራንት › ሜኑ (ወይም በምርት ቅጹ ላይ ያለው "የምግብ ዝርዝሮች" ካርድ) የሬስቶራንት መረጃውን ያክላል።',
'Rst_Guide_Menu_2' => 'የተጨማሪ ቡድኖች ዋጋ ያላቸውን ምርጫዎች ይይዛሉ: "መጠን" (1 ይምረጡ) ወይም "ተጨማሪዎች" (እስከ 3)። ደንቦቹ በእያንዳንዱ ትዕዛዝ ላይ ይረጋገጣሉ፣ በመስመር ላይም ጭምር።',
'Rst_Guide_Menu_3' => 'አንድ ተጨማሪ ግብዓትን ሊጠቀም ይችላል: "ተጨማሪ አይብ"ን ከአይብ ምርትዎ ጋር ያገናኙ እና እያንዳንዱ ከዚያ ክምችት ይቀንሳል።',
'Rst_Guide_Menu_4' => 'አንድን ምግብ በአንድ ማብሪያ/ማጥፊያ ለዛሬ እንዳለቀ ምልክት ያድርጉ፤ ነገ በራሱ ይመለሳል። የምግብ ሰዓቶች (ቁርስ፣ ምሳ፣ እራት) አንድ ምግብ የሚቀርብበትን ጊዜ ይገድባሉ።',
'Rst_Guide_Menu_5' => 'የምግብ አሰራር የኮምቦ ምርት ነው: ምናባዊ የኮምቦ ክምችት ሲበራ፣ ምግቡን መሸጥ ክፍሎቹን ከክምችት ይቀንሳል።',
'Rst_Guide_Kitchen' => 'የወጥ ቤት ማሳያ',
'Rst_Guide_Kitchen_1' => 'ሬስቶራንት › ወጥ ቤትን በወጥ ቤቱ ውስጥ ባለ ማያ ላይ ይክፈቱ። ጣቢያውን ይምረጡ፤ ጣቢያ የሌላቸው ምግቦች በሁሉም ጣቢያዎች ላይ ይታያሉ።',
'Rst_Guide_Kitchen_2' => 'ቲኬቶች ሲጠብቁ መጀመሪያ ብርቱካናማ ከዚያም ቀይ ይሆናሉ (ሬስቶራንት ቅንብሮች › ከN ደቂቃ በኋላ ዘግይቷል)። አዲስ ቲኬቶችን የድምፅ ምልክት ያሳውቃል።',
'Rst_Guide_Kitchen_3' => 'ጀምር → ምግቦችን ምልክት አድርግ → ጨርስ። "በዚህ ጣቢያ ተጠናቋል" በጋራ ቲኬት ላይ የዚህን ጣቢያ ምግቦች ብቻ ያጠናቅቃል።',
'Rst_Guide_Kitchen_4' => 'የቀረቡ ቲኬቶች ስህተት ቢኖር መልሶ ለማምጣት እንዲቻል ለ15 ደቂቃ ይቆያሉ። ቲኬቶች በ80 mm አታሚ ላይ ሊታተሙ ይችላሉ።',
'Rst_Guide_Kitchen_5' => 'ከመስመር ላይ ሱቁ እና ከጠረጴዛ QR ኮዶች የሚመጡ ትዕዛዞች በቲኬታቸው ላይ "በመስመር ላይ" ወይም "QR" ተብለው ምልክት ይደረግባቸዋል።',
'Rst_Guide_Bills' => 'ሂሳቦች እና ክፍያዎች',
'Rst_Guide_Bills_1' => 'እያንዳንዱ ክፍያ መደበኛ የPOS ሽያጭ ነው: ክምችት፣ የገንዘብ መመዝገቢያ፣ የሒሳብ አያያዝ፣ የታማኝነት ነጥቦች እና የኤሌክትሮኒክ ደረሰኝ ልክ በPOS እንደሚሰሩት ይሰራሉ።',
'Rst_Guide_Bills_2' => 'የአገልግሎት ክፍያ ከታክስ በፊት የምግቦቹ መቶኛ ነው፣ እዚሁ ለሚመገቡ (ወይም እንደ ቅንብርዎ ለሁሉም ትዕዛዞች)። ቲፕ የተወሰነ መቶኛ ወይም መጠን ነው።',
'Rst_Guide_Bills_3' => 'ቅናሽ "የሬስቶራንት ቅናሾች" ፍቃድ ያስፈልገዋል እና በሬስቶራንት ቅንብሮች ውስጥ ባለው ከፍተኛ ቅናሽ የተገደበ ነው።',
'Rst_Guide_Bills_4' => 'ማጠጋጋቱ ሂሳቡን በሚያጠናቅቀው ክፍያ ላይ፣ ለእንግዳው በሚጠቅም መልኩ ወደ ደረጃዎ ወደ ታች ይሄዳል።',
'Rst_Guide_Bills_5' => 'በእኩል መክፈል: አንድ ሽያጭ፣ ለእያንዳንዱ ሰው አንድ የክፍያ መስመር (ድርሻዎች እስከ ሳንቲም)። በምግብ መክፈል: የእያንዳንዱ እንግዳ ምግቦች የራሳቸው ሽያጭ ይሆናሉ፤ ምግቦቹን ለመምረጥ መቀመጫ ይምረጡ።',
'Rst_Guide_Bills_6' => 'ሂሳቡ ከታየ በኋላ ከተቀየረ (ከQR ኮድ ምግብ ከታከለ፣ ቲፕ ከተቀየረ)፣ እንግዳው ያላየውን ነገር እንዳይከፍል ክፍያው ተቀባይነት አያገኝም።',
'Rst_Guide_Bills_7' => 'የተከፈሉ ምግቦች ውድቅ ሊደረጉ አይችሉም። ያልተከፈለው የትዕዛዙ ቀሪ ክፍል ውድቅ ከተደረገ፣ ትዕዛዙ እንደተከፈለ ይዘጋል እና ጠረጴዛው ነፃ ሊደረግ ይችላል።',
'Rst_Guide_Bookings' => 'ቦታ ማስያዣዎች እና የተጠባባቂ ዝርዝር',
'Rst_Guide_Bookings_1' => 'ቦታ ማስያዣዎች ጠረጴዛን ለቆይታቸው ይይዛሉ (ነባሪው በሬስቶራንት ቅንብሮች ውስጥ ነው)። ሁለት ቦታ ማስያዣዎች በአንድ ጠረጴዛ ላይ በፍጹም ሊደራረቡ አይችሉም።',
'Rst_Guide_Bookings_2' => 'የአዳራሽ ካርታው የእያንዳንዱን ጠረጴዛ ቀጣይ ቦታ ማስያዣ ያሳያል እና ጊዜው ሲቃረብ ያስጠነቅቃል፤ "ደርሰዋል — አስቀምጥ" እንግዶቹን ያስቀምጣል።',
'Rst_Guide_Bookings_3' => 'የያለመምጣት ጊዜው ካለፈ በኋላ የዘገዩ እንግዶች እንዳልመጡ ምልክት ሊደረግባቸው ይችላል፤ ስህተት ከሆነ መመለስ ይቻላል።',
'Rst_Guide_Bookings_4' => 'የተጠባባቂ ዝርዝሩ ሳያስይዙ የመጡ እንግዶችን ከተነገራቸው የመጠበቂያ ጊዜ ጋር በቅደም ተከተል ይይዛል። ጠረጴዛ ዝግጁ ሲሆን ይደውሉላቸው ወይም በWhatsApp ያሳውቋቸው፣ ከዚያ ያስቀምጧቸው።',
'Rst_Guide_Bookings_5' => 'የመስመር ላይ ቦታ ማስያዣዎች እንዲያረጋግጧቸው "ተይዟል" ሆነው ይደርሳሉ (በጎን አሞሌው ላይ ያለ ምልክት ይቆጥራቸዋል)።',
'Rst_Guide_Online' => 'የመስመር ላይ ትዕዛዞች፣ የQR ሜኑዎች እና የመስመር ላይ ቦታ ማስያዣ',
'Rst_Guide_Online_1' => 'በሬስቶራንት የሱቅ ገጽታ የመስመር ላይ ሱቁ መነሻ ገጽ ሜኑዎ ነው፣ ከተጨማሪዎች እና ከአመጋገብ ማጣሪያዎች ጋር፤ ገዢዎች እንደተለመደው በክፍያ ሂደቱ ይከፍላሉ።',
'Rst_Guide_Online_2' => '"የመስመር ላይ ትዕዛዞች ወደ ወጥ ቤት" ወደ ወጥ ቤት ማሳያው መቼ እንደሚደርሱ ይወስናል: ሲታዘዙ (ሲከፈሉ፣ ወይም በመለያ የገባ ደንበኛ ሲያደርስ / ሲረከብ የሚከፍል ከሆነ)፣ ሲቀበሉ ወይም በፍጹም።',
'Rst_Guide_Online_3' => 'የጠረጴዛ QR ኮዶች (የአዳራሽ ዝግጅት › የጠረጴዛ QR ኮዶች) የዚያን ጠረጴዛ ሜኑ ይከፍታሉ። "አዲስ ሊንክ" የታተመን ኮድ ከአገልግሎት ያስወጣል።',
'Rst_Guide_Online_4' => '"የQR ትዕዛዞችን በቀጥታ ወደ ወጥ ቤት ላክ" ካልበራ በስተቀር፣ የQR ትዕዛዞች አስተናጋጅ እስኪልካቸው ድረስ በጠረጴዛው ትዕዛዝ ላይ ይጠብቃሉ። እንግዶች ለሰራተኞች ይከፍላሉ።',
'Rst_Guide_Online_5' => 'የመስመር ላይ ቦታ ማስያዣ የሚያቀርበው ለእንግዶቹ የሚመጥን ጠረጴዛ ለሙሉ የማስያዣ ጊዜው ነፃ የሆነባቸውን ሰዓቶች ብቻ ነው፣ እና እያንዳንዱን ስልክ ቁጥር በ3 መጪ ቦታ ማስያዣዎች ይገድባል።',
'Rst_Guide_Online_6' => 'ይህ ሁሉ የመስመር ላይ ሱቁ አካል ነው: መብራት እና በእቅድዎ ውስጥ መካተት አለበት።',
'Rst_Guide_Reports' => 'ዳሽቦርድ እና ሪፖርቶች',
'Rst_Guide_Reports_1' => 'ዳሽቦርዱ ዛሬን ካለፈው ሳምንት ተመሳሳይ ቀን ጋር ያነጻጽራል: ሽያጮች፣ ሂሳቦች፣ እንግዶች፣ አማካይ ሂሳብ፣ ውድቅ የተደረጉ እና ቅናሾች፣ እንዲሁም አሁን እየሆነ ያለውን ያሳያል።',
'Rst_Guide_Reports_2' => 'ሽያጮች የሬስቶራንት ሂሳቦች እና ወደ ወጥ ቤት የደረሱ የመስመር ላይ ትዕዛዞች ናቸው። የምግብ ሽያጮች እና የትርፍ ህዳጎች የእያንዳንዱን ምርት ወጪ በመጠቀም ከታክስ በፊት ይሰላሉ።',
'Rst_Guide_Reports_3' => 'ሪፖርቶች: ሽያጭ በቀን እና በክፍያ ዘዴ፣ ምግቦች፣ ውድቅ የተደረጉ እና ስረዛዎች (ከምክንያቶች ጋር)፣ ሰራተኞች፣ የወጥ ቤት ጊዜዎች እና ቦታ ማስያዣዎች — እያንዳንዱ ወደ Excel ይላካል።',
'Rst_Guide_Reports_4' => 'ለአንዳንድ ቅርንጫፎች ብቻ የተገደቡ ሰራተኞች የራሳቸውን ቅርንጫፎች ብቻ ያያሉ፤ ቅርንጫፍ የሌላቸው ትዕዛዞች ለሁሉም የጋራ ናቸው።',
'Rst_Guide_Faq' => 'ማወቅ ጠቃሚ ነው',
'Rst_Guide_Faq_1_Q' => '"ላክ"ን ከመጫኔ በፊት የሚወሰድ ትዕዛዝ ተከፍሏል። ይበስላል?',
'Rst_Guide_Faq_1_A' => 'አዎ። መክፈል ገና ያልተላኩ ምግቦችን ወደ ወጥ ቤት ይልካል።',
'Rst_Guide_Faq_2_Q' => 'ጠረጴዛን ነፃ ማድረግ ለምን አልችልም?',
'Rst_Guide_Faq_2_A' => 'ትዕዛዙ አሁንም ያልተከፈሉ ምግቦች አሉት። ክፍያውን ይቀበሉ፣ ያልተበላውን ውድቅ ያድርጉ፣ ወይም ትዕዛዙን ይሰርዙ (ምንም ገና ካልተከፈለ ብቻ)።',
'Rst_Guide_Faq_3_Q' => 'ሁለት ጠረጴዛዎች አንድ ላይ ተገጥመዋል። ትዕዛዞቻቸው ምን ይሆናሉ?',
'Rst_Guide_Faq_3_A' => '"ጠረጴዛዎችን አጣምር" የሁለተኛውን ጠረጴዛ ምግቦች (እና ማንኛውንም ክፍያ) ወደ ዋናው ጠረጴዛ ትዕዛዝ ያዛውራል፤ "ለይ" ጠረጴዛዎቹን እንደገና ይለያል።',
'Rst_Guide_Faq_4_Q' => 'የካርድ ክፍያዎች እዚህ Stripe መጠቀም ይችላሉ?',
'Rst_Guide_Faq_4_A' => 'አይ። የStripe ካርድ ክፍያዎች የPOS የካርድ ቅጽ ያስፈልጋቸዋል፤ ለካርድ ተርሚናል እንደ "ካርድ" ያለ የክፍያ ዘዴ ያክሉ እና በሂሳቡ ላይ ያንን ይጠቀሙ።',
'Rst_Guide_Faq_5_Q' => 'አንድ ምግብ በአንድ ቅርንጫፍ ብቻ ክምችቱ አልቋል።',
'Rst_Guide_Faq_5_A' => 'ክምችቱ የሚወሰደው ከትዕዛዙ ቅርንጫፍ ነው (የጠረጴዛው ክፍል፣ አለበለዚያ በሬስቶራንት ቅንብሮች ውስጥ ያለው ነባሪ ቅርንጫፍ)። ትዕዛዞችን በፍጥነት ለማቆም "ዛሬ አልቋል" ይጠቀሙ።',
'Rst_Guide_Faq_6_Q' => 'አታሚ ያስፈልገኛል?',
'Rst_Guide_Faq_6_A' => 'አይ። ሂሳቦች፣ ደረሰኞች እና የወጥ ቤት ቲኬቶች ከአሳሹ በማንኛውም አታሚ ይታተማሉ፤ 80 mm የደረሰኝ አታሚዎች በተሻለ ይስማማሉ።',
'Rst_Guide_Faq_7_Q' => 'በመስመር ላይ ሱቁ ውስጥ የሬስቶራንት ሜኑዎች ከየት ይመጣሉ?',
'Rst_Guide_Faq_7_A' => 'ከተመሳሳይ ምርቶች፣ ምድቦች እና ተጨማሪዎች። ከመስመር ላይ ሱቁ የተደበቁ ምርቶች እና በሱቁ ውስጥ የማይታዩ ምድቦች ከመስመር ላይ ሜኑው እና ከQR ሜኑው ውጭ ይቆያሉ።',

