'Bkm_Guide_Website_1' => 'ደንበኛው በመነሻ ገጽዎ ወይም በማስያዣ ገጹ ላይ ካለው ቅጽ ይጀምራል።',
'Bkm_Guide_Website_2_T' => 'ሰዓት መምረጥ ወይም ጥያቄ መላክ',
'Bkm_Guide_Website_2' => 'ነፃ ሰዓቶች ከሰራተኞችዎ የሥራ ሰዓቶች፣ የዕረፍት ቀናት እና ከሌሎች ማስያዣዎች ይሰላሉ፤ ጥያቄ ደግሞ የሚመረጥ ቀን እና የቀኑን ክፍል ብቻ ይሰጣል።',
'Bkm_Guide_Website_3_T' => 'የደንበኛው ዝርዝሮች',
'Bkm_Guide_Website_3' => 'ስም፣ ስልክ፣ ኢሜይል እና የንግድ አይነትዎ የሚጠይቃቸው ጥያቄዎች።',
'Bkm_Guide_Website_4_T' => 'ቀብድ',
'Bkm_Guide_Website_4' => 'ቀብድ ሲጠይቁ ሰዓቱን ለማቆየት ወዲያውኑ ይከፍላሉ።',
'Bkm_Guide_Website_5_T' => 'እርስዎን በመጠበቅ ላይ',
'Bkm_Guide_Website_5' => 'በጥያቄዎች ውስጥ በመጠባበቅ ላይ ሆኖ ይገባል፣ ሰዓቱም ለእነሱ ተይዞ ይቆያል (በራስ-ሰር ማረጋገጥ ካልበራ በስተቀር)።',
'Bkm_Guide_Website_6_T' => 'የደንበኛው የማስያዣ ገጽ',
'Bkm_Guide_Website_6' => 'በኢሜይላቸው ካለው ሊንክ ይከታተሉታል፦ ሁኔታ፣ ወደ ቀን መቁጠሪያ ማከል፣ መሰረዝ፣ ለተጠቆመ ሰዓት ምላሽ መስጠት።',
'Bkm_Guide_Requests' => 'ለጥያቄዎች ምላሽ መስጠት',
'Bkm_Guide_Requests_1' => '"ጥያቄዎች" ገጹ እርስዎን የሚጠብቁትን ማስያዣዎች ሁሉ፣ የቆየው ማቆያ መጀመሪያ፣ በምናሌው ውስጥ ካለ ምልክት ጋር ያሳያል።',
'Bkm_Guide_Requests_2' => '"አረጋግጥ" ሰራተኛውን ባዶ ከተዉት ሰራተኛ ይመርጥልዎታል፣ ሰዓቱ አሁንም ነፃ መሆኑንም ያረጋግጣል።',
'Bkm_Guide_Requests_3' => 'የእነሱ ሰዓት የማይመች ሲሆን ሌላ ሰዓት ይጠቁሙ — ከማስያዣ ገጻቸው ይቀበሉታል።',
'Bkm_Guide_Requests_4' => 'ከምክንያት ጋር ውድቅ ያድርጉ፤ ደንበኛው ምክንያቱን ያያል።',
'Bkm_Guide_Requests_5' => 'ጊዜው ያለፈበት ማቆያ ሰዓቱን ነፃ ያደርጋል፤ ማስያዣው ግን ምላሽ እስኪሰጡት ድረስ ይቆያል።',
'Bkm_Guide_Day' => 'በዕለቱ',
'Bkm_Guide_Day_1' => '"የቀን እይታ" የእያንዳንዱን ሰራተኛ ማስያዣዎች ጎን ለጎን ያሳያል።',
'Bkm_Guide_Day_2' => 'ደንበኛው ሲገባ እንደደረሰ ምልክት ያድርጉ።',
'Bkm_Guide_Day_3' => '"አጠናቅቅ እና አስከፍል" ሽያጩን በPOS በኩል ይፈጥራል፤ ቀብዱም አስቀድሞ ተቆጥሯል።',
'Bkm_Guide_Day_4' => 'ክፍያው በሌላ መንገድ ከተፈጸመ "ክፍያ ሳይጠየቅ አጠናቅቅ" የሚለውን ይጠቀሙ።',
'Bkm_Guide_Day_5' => 'የመጀመሪያ ሰዓቱ ካለፈ በኋላ እንዳልመጣ ምልክት ያድርጉ።',
'Bkm_Guide_Day_6' => 'ዳሽቦርዱ የዛሬውን መርሐ ግብር፣ ገና የሚመጣውን እና ገና ያልተከፈለውን ያሳያል።',
'Bkm_Guide_Deposits' => 'ቀብዶች',
'Bkm_Guide_Deposits_1' => 'መጠኑን በ"የቦታ ማስያዣ ቅንብሮች › ቀብድ" ውስጥ ያዘጋጁ፤ አንድ አገልግሎት የራሱ ሊኖረው ይችላል።',
'Bkm_Guide_Deposits_2' => 'ደንበኞች በ"የመስመር ላይ ሱቅ › የክፍያ መንገድ" ስር በተዘጋጁ የክፍያ አቅራቢዎች፣ በመሠረታዊ ምንዛሪዎ ይከፍላሉ።',
'Bkm_Guide_Deposits_3' => 'ሰዓቱ ለክፍያው ተይዞ ይቆያል፤ ያልተከፈሉ ማስያዣዎች በራስ-ሰር ሊሰረዙ ይችላሉ።',
'Bkm_Guide_Deposits_4' => 'ደንበኛው ሳይመለስ የተፈጸመ ክፍያ በራስ-ሰር ይመዘገባል።',
'Bkm_Guide_Deposits_5' => 'ማስያዣውን ሲያስከፍሉ ቀብዱ በሽያጩ ላይ የመጀመሪያው ክፍያ ይሆናል።',
'Bkm_Guide_Deposits_6' => 'ተመላሽ ገንዘብ በክፍያ አቅራቢዎ ይፈጸማል፤ ከዚያም በማስያዣው ላይ ቀብዱ ተመላሽ እንደተደረገ ምልክት ያድርጉ።',
'Bkm_Guide_Messages' => 'ኢሜይሎች፣ WhatsApp እና ማስታወሻዎች',
'Bkm_Guide_Messages_1' => 'ደንበኞች ማስያዣቸው ሲደርስ፣ ሲረጋገጥ፣ ውድቅ ሲደረግ፣ ሲቀየር ወይም ሲሰረዝ ኢሜይል ይደርሳቸዋል።',
'Bkm_Guide_Messages_2' => 'ለእያንዳንዱ አዲስ የድረ-ገጽ ማስያዣ፣ የደንበኛ ስረዛ እና የተከፈለ ቀብድ ለእርስዎም ኢሜይል ይደርስዎታል።',
'Bkm_Guide_Messages_3' => 'ከእያንዳንዱ የተረጋገጠ ጉብኝት በፊት ማስታወሻ ይላካል (የቦታ ማስያዣ ቅንብሮች › ማሳወቂያዎች)።',
'Bkm_Guide_Messages_4' => 'ተመሳሳይ መልዕክቶችን እዚያ ለመላክ "በWhatsApp ጭምር ላክ" የሚለውን ያብሩ።',
'Bkm_Guide_Messages_5' => 'እያንዳንዱ መልዕክት በማስያዣው ላይ ይዘረዘራል፤ ካልተላከም ለምን እንዳልተላከ ይገለጻል።',
'Bkm_Guide_Customers' => 'ደንበኞች፣ CRM እና ፖርታል',
'Bkm_Guide_Customers_1' => 'የድረ-ገጽ ማስያዣ ወደ ደንበኞችዎ ይታከላል፤ በተመሳሳይ ኢሜይል እና ስልክ እንደገና የሚያስይዝ ሰው ከነባሩ ጋር ይዛመዳል።',
'Bkm_Guide_Customers_2' => 'CRM በእቅድዎ ውስጥ ካለ ማስያዣዎች በደንበኛው ወይም በእምቅ ደንበኛ መዝገቡ ላይ ሊመዘገቡ ይችላሉ፤ ጥያቄዎችም ስምምነት ሊከፍቱ ይችላሉ።',
'Bkm_Guide_Customers_3' => 'የደንበኛ ፖርታል መለያ ያላቸው ደንበኞች ማስያዣዎቻቸውን እዚያ ያያሉ፤ መሰረዝ ወይም ለተጠቆመ ሰዓት ምላሽ መስጠትም ይችላሉ።',
'Bkm_Guide_Customers_4' => 'የገቡ የሱቅ ደንበኞች ማስያዣዎቻቸውን በ"የእኔ መለያ" ስር ያገኛሉ።',
'Bkm_Guide_Roles' => 'ማን ምን ማድረግ ይችላል',
'Bkm_Guide_Roles_Help' => 'ለእያንዳንዱ ሚና የሚያስፈልገውን ፍቃድ ብቻ ይስጡ (ቅንብሮች › የቡድን ፍቃዶች)።',
'Bkm_Guide_Job' => 'ሥራ',
'Bkm_Guide_Give' => 'የሚሰጣቸው',
'Bkm_Guide_Job_Front_Desk' => 'የእንግዳ መቀበያ',
'Bkm_Guide_Job_Staff_Member' => 'ሰራተኛ',
'Bkm_Guide_Job_Manager' => 'ሥራ አስኪያጅ',
'Bkm_Guide_Job_Owner' => 'ባለቤት ወይም የሂሳብ ባለሙያ',
'Bkm_Guide_Faq' => 'ጥያቄዎች',
'Bkm_Guide_Faq_1_Q' => 'አንድ አገልግሎት ለምን በድረ-ገጹ ላይ አይታይም?',
'Bkm_Guide_Faq_1_A' => 'የማስያዣ ዝርዝሮች (አገልግሎቶች)፣ የበራ "በድረ-ገጽ ላይ አሳይ"፣ ንቁ ምርት እና — ሰዓት ለመምረጥ — አገልግሎቱን የሚሰጥ በመስመር ላይ ሊያዝ የሚችል ሰው ያስፈልገዋል።',
'Bkm_Guide_Faq_2_Q' => 'ለምን ነፃ ሰዓቶች የሉም?',
'Bkm_Guide_Faq_2_A' => 'የሰራተኞቹን የሥራ ሰዓቶች፣ የዕረፍት ቀናት፣ በዓላት እና የጸደቀ እረፍት፣ ቅርብ የማስያዣ ጊዜውን እና ደንበኞች ምን ያህል ቀናት አስቀድመው ማስያዝ እንደሚችሉ ያረጋግጡ።',
'Bkm_Guide_Faq_3_Q' => 'ሁለት ደንበኞች አንድ ሰዓት ሊይዙ ይችላሉ?',
'Bkm_Guide_Faq_3_A' => 'አይ። ሲያስይዙ ሰዓቱ እንደገና ይረጋገጣል፤ የተያዘ ወይም የተረጋገጠ ማስያዣም ያግደዋል። ክፍለ ትምህርቶች እስከ ገደባቸው ድረስ መቀመጫዎችን ይጋራሉ።',
'Bkm_Guide_Faq_4_Q' => 'የማቆያ ጊዜ ሲያልፍ ምን ይሆናል?',
'Bkm_Guide_Faq_4_A' => 'ሰዓቱ ለሌሎች እንደገና ነፃ ይሆናል። ማስያዣው ምላሽ እስኪሰጡት ድረስ በጥያቄዎች ውስጥ ይቆያል (ወይም ቀብዱ ካልተከፈለ ይሰረዛል)።',
'Bkm_Guide_Faq_5_Q' => 'ደንበኞች መለያ ያስፈልጋቸዋል?',
'Bkm_Guide_Faq_5_A' => 'አይ። ወደ ማስያዣ ገጻቸው የሚወስድ የግል ሊንክ ይደርሳቸዋል። የሱቅ እና የፖርታል መለያዎችም ማስያዣዎቻቸውን ይዘረዝራሉ።',
'Bkm_Guide_Faq_6_Q' => 'ገንዘቡ ወዴት ይሄዳል?',
'Bkm_Guide_Faq_6_A' => 'ቀብዶች ወደ ክፍያ አቅራቢዎ ይሄዳሉ፤ ቀሪው ማስያዣውን ሲያስከፍሉ በPOS ይቀበላል። ሪፖርቶች ገቢን ከእነዚያ ሽያጮች ይቆጥራሉ።',
