'Pf_Guide_1' => 'በPrintful ውስጥ የ{store} ዓይነት ሱቅ ያክሉ እና ምርቶችዎን በውስጡ ይንደፉ።',
'Pf_Guide_2' => 'ለዚያ ሱቅ በ{portal} ላይ {scopes} ወሰኖች ያሉት የግል ቶክን ይፍጠሩ። በግንኙነት ትር ላይ ለጥፈው ያስቀምጡ፤ ቶክኑ ብዙ ሱቆችን የሚደርስ ከሆነ አንዱን ይምረጡ።',
'Pf_Guide_3' => 'የመጀመሪያው የተሳካ የግንኙነት ሙከራ ዌብሁኮቹን ይመዘግባል፣ በዚህም Printful የትዕዛዝ ለውጦችንና መላኪያዎችን ለStocky ማሳወቅ ይችላል።',
'Pf_Guide_4' => 'የምርቶች ትር፦ ምርቶችን አስመጣ። ከእርስዎ ውጭ በሌላ ምንዛሪ ዋጋ የተሰጣቸው ምርቶች በቅንብሮች ትር ላይ የምንዛሪ ተመን እስኪያዘጋጁ ወይም በእጅ ዋጋ እስኪሰጧቸው ድረስ ንቁ ያልሆኑ ሆነው ይመጣሉ።',
'Pf_Guide_5' => 'የቅንብሮች ትር፦ የድረ-ገጽ ትዕዛዞች መቼ ወደ Printful እንደሚሄዱ ይምረጡ። የሚላኩት የትዕዛዙ የPrintful እቃዎች ብቻ ናቸው፤ ሌላውን ሁሉ እርስዎ ይልካሉ።',
'Pf_Guide_6' => 'ራስ-ሰር ማረጋገጫ ካልበራ በስተቀር ትዕዛዞች Printful ላይ እንደ ረቂቅ ይደርሳሉ። እንዲታተሙ ረቂቆቹን በትዕዛዞች ትር (ወይም በPrintful ውስጥ) ያረጋግጡ።',
'Pf_Guide_7' => 'በክፍያ ጊዜ የPrintfulን የራሱን የመላኪያ ዋጋዎች ለመጠቀም፣ በሱቅ > የመላኪያ ዘዴዎች ስር ዋጋ አወሳሰኑ የPrintful ተመኖች የሆነ የመላኪያ ዘዴ ያክሉ።',
'Pf_Guide_Duplicate' => 'ይህን የPrintful ሱቅ ተመሳሳይ ምርቶችን ከሚሸጥ የShopify ወይም WooCommerce ሱቅ ጋርም አያገናኙ፤ ካልሆነ Printful እነዚያን ትዕዛዞች ሁለት ጊዜ ይቀበላል።',
