'Mkg_Guide_Stuck_Alert_Help' => 'ከ30 ደቂቃ በላይ ምንም አልተላከም። ዘመቻውን ከፍተው ለመቀጠል አሁን ላክ የሚለውን ይጫኑ፤ አስቀድሞ የደረሳቸው ደንበኞች እንደገና መልእክት አይላክላቸውም። ይህ መደጋገሙን ከቀጠለ የጀርባ ስራዎች እየሰሩ መሆናቸውን እንዲያረጋግጥ የፕላትፎርም አስተዳዳሪዎን ይጠይቁ።',
'Mkg_Guide_Your_Setup' => 'የእርስዎ ዝግጅት',
'Mkg_Guide_Your_Setup_Help' => 'ይህ የስራ ቦታ ያለበት ሁኔታ። እያንዳንዱ ደረጃ ወደሚሰራው ገጽ ይወስዳል።',
'Mkg_Guide_Done_N' => 'ከ{total} {done} ተጠናቀዋል',
'Mkg_Guide_Optional' => 'አማራጭ',
'Mkg_Guide_State_Done' => 'ተጠናቋል',
'Mkg_Guide_State_Warn' => 'ትኩረት ያስፈልገዋል',
'Mkg_Guide_State_Todo' => 'ገና አልተሰራም',
'Mkg_Guide_How' => 'እንዴት እንደሚሰራ',
'Mkg_Guide_Step_Customers' => 'የሚደረሱ ደንበኞች',
'Mkg_Guide_Step_Customers_Ok' => '{n} ደንበኞች፦ {email} የኢሜይል አድራሻ ያላቸው፣ {phone} የስልክ ቁጥር ያላቸው።',
'Mkg_Guide_Step_Customers_Help' => 'የኢሜይል አድራሻ ወይም የስልክ ቁጥር ያላቸውን ደንበኞች ያክሉ ወይም ያስመጡ።',
'Mkg_Guide_Step_Channel' => 'ቻናል ያብሩ',
'Mkg_Guide_Step_Channel_Ok' => 'የበሩ፦ {list}።',
'Mkg_Guide_Step_Channel_Help' => 'በግብይት ቅንብሮች ውስጥ ኢሜይል፣ SMS ወይም WhatsApp ያብሩ።',
'Mkg_Guide_Step_Mail' => 'ኢሜይል፦ የሜይል አገልጋይ',
'Mkg_Guide_Step_Mail_Ok' => 'የሜይል አገልጋይዎ ተዘጋጅቷል። የኢሜይል ዘመቻዎች በእሱ በኩል ይላካሉ።',
'Mkg_Guide_Step_Mail_Help' => 'ኢሜይል በርቷል ነገር ግን ምንም የሜይል አገልጋይ አልተዘጋጀም፣ ስለዚህ እያንዳንዱ ኢሜይል ይዘለላል። በኢሜይል ቅንብሮች ውስጥ አንዱን ያክሉ።',
'Mkg_Guide_Step_Sms' => 'SMS፦ ጌትዌይ',
'Mkg_Guide_Step_Sms_Ok' => 'የSMS ጌትዌዩ ተዘጋጅቷል።',
'Mkg_Guide_Step_Sms_Help' => 'SMS በርቷል ነገር ግን የAPI URL የለውም፣ ስለዚህ እያንዳንዱ SMS ይዘለላል። በግብይት ቅንብሮች ውስጥ ጌትዌዩን ይሙሉ።',
'Mkg_Guide_Step_Whatsapp' => 'WhatsApp፦ API',
'Mkg_Guide_Step_Whatsapp_Ok' => 'የWhatsApp API ተዘጋጅቷል።',
'Mkg_Guide_Step_Whatsapp_Help' => 'WhatsApp በርቷል ነገር ግን የAPI URL የለውም፣ ስለዚህ እያንዳንዱ መልእክት ይዘለላል። በግብይት ቅንብሮች ውስጥ APIውን ይሙሉ።',
'Mkg_Guide_Step_Segments' => 'የደንበኛ ክፍሎች',
'Mkg_Guide_Step_Segments_Ok' => '{n} ክፍል(ዎች) ተቀምጠዋል።',
'Mkg_Guide_Step_Segments_Help' => 'ከሁሉም ይልቅ ደንበኞችን በከተማ፣ በመጨረሻ ግዢ፣ በግዢዎች ብዛት ወይም በጠቅላላ ወጪ ያነጣጥሩ።',
'Mkg_Guide_Step_Templates' => 'የመልእክት አብነቶች',
'Mkg_Guide_Step_Templates_Ok' => '{n} አብነት(ዎች) እንደገና ለመጠቀም ዝግጁ።',
'Mkg_Guide_Step_Templates_Help' => 'ብዙ ጊዜ የሚልኳቸውን መልእክቶች ያስቀምጡ እና ዘመቻዎችን ከእነሱ ይጀምሩ።',
'Mkg_Guide_Step_Schedule' => 'መርሐግብር',
'Mkg_Guide_Step_Schedule_Ok' => 'በርቷል። ዘመቻዎች በኋላ እንዲላኩ ሊዘጋጁ ይችላሉ።',
'Mkg_Guide_Step_Schedule_Help' => 'በሚመርጡት ቀንና ሰዓት ዘመቻዎችን ለመላክ ያብሩ።',
'Mkg_Guide_Step_First' => 'የመጀመሪያ ዘመቻዎን ይላኩ',
'Mkg_Guide_Step_First_Ok' => '{n} ዘመቻ(ዎች) ተልከዋል።',
'Mkg_Guide_Step_First_Help' => 'ዘመቻ ይፍጠሩ እና መጀመሪያ በትንሽ ክፍል ላይ ይሞክሩት።',
'Mkg_Guide_Step_Health' => 'የመላኪያ ጤንነት',
'Mkg_Guide_Step_Health_Stuck' => '{n} ዘመቻ(ዎች) በመላክ ላይ እንደተጣበቁ ናቸው። ከፍተው ለመቀጠል አሁን ላክ የሚለውን ይጫኑ።',
'Mkg_Guide_Step_Health_Failed' => 'ባለፉት 30 ቀናት ውስጥ {n} መልእክት(ዎች) አልተሳኩም እና {skipped} ተዘልለዋል። እያንዳንዱን ስህተት ለማየት ዘመቻ ይክፈቱ።',
'Mkg_Guide_Step_Health_Skipped' => 'ባለፉት 30 ቀናት ውስጥ {n} መልእክት(ዎች) ተዘልለዋል (ኢሜይል ወይም ስልክ የለም፣ ቻናሉ ጠፍቷል፣ ወይም አገልጋይ የለም)። ምክንያቱን ለማየት ዘመቻ ይክፈቱ።',
'Mkg_Guide_Step_Health_Ok' => 'ባለፉት 30 ቀናት ውስጥ ምንም ያልተሳካ ወይም የተጣበቀ መልእክት የለም።',
'Mkg_Guide_Flow' => 'ዘመቻ መላክ',
'Mkg_Guide_Flow_1_T' => 'ቻናል ያዋቅሩ',
'Mkg_Guide_Flow_1' => 'በግብይት ቅንብሮች ውስጥ ኢሜይል፣ SMS ወይም WhatsApp ያብሩ እና አገልጋዩን ወይም ጌትዌዩን ያገናኙ።',
'Mkg_Guide_Flow_2_T' => 'ተቀባዮችን ይምረጡ',
'Mkg_Guide_Flow_2' => 'ሁሉም ደንበኞች፣ ወይም የተቀመጠ ክፍል።',
'Mkg_Guide_Flow_3_T' => 'መልእክቱን ይጻፉ',
'Mkg_Guide_Flow_3' => 'ይተይቡት ወይም ከአብነት ይጀምሩ፣ እና የግል ማድረጊያ ተለዋዋጮችን ያክሉ (ከታች ይመልከቱ)።',
'Mkg_Guide_Flow_4_T' => 'አሁን ይላኩ ወይም መርሐግብር ያስይዙ',
'Mkg_Guide_Flow_4' => 'አሁን ላክ ወዲያውኑ ይጀምራል፤ መርሐግብር በሚመርጡት ቀንና ሰዓት ይልካል።',
'Mkg_Guide_Flow_5_T' => 'የተቀባዮች ዝርዝር ይዘጋጃል',
'Mkg_Guide_Flow_5' => 'በላኩበት ቅጽበት እያንዳንዱ ተዛማጅ ደንበኛ በመጠባበቅ ላይ ሆኖ ይጨመራል፣ ስለዚህ ማን እንደሚደርሰው ወዲያውኑ ማየት ይችላሉ።',
'Mkg_Guide_Flow_6_T' => 'መላኩ በጀርባ ይካሄዳል',
'Mkg_Guide_Flow_6' => 'መልእክቶች በቡድን ይላካሉ (በግብይት ቅንብሮች ውስጥ ያለው የቡድን መጠን) እና ቁጥሮቹ ከእያንዳንዱ ቡድን በኋላ ይዘምናሉ።',
'Mkg_Guide_Flow_7_T' => 'ውጤቶቹን ያረጋግጡ',
'Mkg_Guide_Flow_7' => 'እያንዳንዱን ተቀባይ ከሁኔታውና ከማንኛውም ስህተት ጋር ለማየት ዘመቻውን ይክፈቱ፤ ሪፖርቶች ሁሉንም ቻናሎች ያጠቃልላል።',
'Mkg_Guide_Audience' => 'ማን ይቀበለዋል',
'Mkg_Guide_Audience_1' => 'ሁሉም ደንበኞች ላልተሰረዘ እያንዳንዱ ደንበኛ ይልካል።',
'Mkg_Guide_Audience_2' => 'ክፍል ደንበኞችን በከተማ፣ በመጨረሻ ግዢ ቀን፣ በግዢዎች ብዛት እና በጠቅላላ ወጪ ያጣራል። ቅድመ እይታ ከማስቀመጥዎ በፊት ምን ያህል እንደሚዛመዱ ያሳያል።',
'Mkg_Guide_Audience_3' => 'ዝርዝሩ ላክ ሲጫኑ ይወሰናል። በኋላ የተጨመሩ ደንበኞች አይካተቱም።',
'Mkg_Guide_Audience_4' => 'የኢሜይል አድራሻ (ኢሜይል) ወይም የስልክ ቁጥር (SMS፣ WhatsApp) የሌላቸው ደንበኞች በዝርዝሩ ላይ እንደ ተዘሏል ይቆያሉ።',
'Mkg_Guide_Audience_5' => 'ያልተሳካ ዘመቻን እንደገና መላክ ዝርዝሩን ከክፍሉ እንደገና ይገነባል እና ሁሉንም እንደገና ይሞክራል።',
'Mkg_Guide_Audience_Leads' => 'CRM በርቶ ሲሆን፣ ክፍል ከደንበኞች ይልቅ የCRM ተስፋ ደንበኞችን (መለያዎች፣ ምንጭ፣ ሁኔታ፣ ነጥብ እና ሌሎችም) ማነጣጠር ይችላል። ደንበኝነታቸውን የሰረዙ ተስፋ ደንበኞች ይዘለላሉ፣ እና ለተስፋ ደንበኞች የሚላኩ ኢሜይሎች ሁልጊዜ የደንበኝነት መሰረዣ ሊንክ ይይዛሉ።',
'Mkg_Guide_Channels' => 'ቻናሎች',
'Mkg_Guide_Ch_email_1' => 'በራስዎ የሜይል አገልጋይ በኩል ይላካል (ቅንብሮች > የኢሜይል ቅንብሮች)። የፕላትፎርሙ ሜይለር በፍጹም ጥቅም ላይ አይውልም።',
'Mkg_Guide_Ch_email_2' => 'የላኪው ስምና አድራሻ ከግብይት ቅንብሮች ይመጣሉ፣ ካልሆነ ከሜይል አገልጋዩ።',
'Mkg_Guide_Ch_email_3' => 'ርዕስ እና አማራጭ አባሪ ያክሉ። መልእክቱ HTML ሊይዝ ይችላል።',
'Mkg_Guide_Ch_email_4' => 'የኢሜይል አድራሻ የሌላቸው ደንበኞች ይዘለላሉ።',
