'Mkg_Guide_Perm_marketing_campaigns' => 'ዘመቻዎችን መፍጠር፣ ማርትዕ፣ መላክና መሰረዝ፣ እንዲሁም ተቀባዮቻቸውን ማየት።',
'Mkg_Guide_Perm_marketing_segments' => 'የደንበኛ ክፍሎችን መፍጠርና ማርትዕ።',
'Mkg_Guide_Perm_marketing_templates' => 'የSMS፣ WhatsApp እና ኢሜይል አብነቶችን ማስተዳደር።',
'Mkg_Guide_Perm_marketing_reports' => 'የግብይት ሪፖርቶችን መክፈት።',
'Mkg_Guide_Perm_marketing_settings' => 'ቻናሎችን (SMS፣ WhatsApp፣ የኢሜይል ላኪ)፣ መርሐግብርን እና የቡድን መጠንን ማዋቀር።',
'Mkg_Guide_Faq' => 'የተለመዱ ጥያቄዎች',
'Mkg_Guide_Faq_1_Q' => 'ዘመቻዬ በመላክ ላይ እንዳለ ይቆያል እና ምንም አይላክም።',
'Mkg_Guide_Faq_1_A' => 'የጀርባው ላኪ ገና አልተረከበውም። ያለ እድገት 30 ደቂቃ ካለፈ በኋላ አሁን ላክ የሚለው ቁልፍ ተመልሶ ይመጣል፦ ለመቀጠል ይጫኑት። ይህ መደጋገሙን ከቀጠለ የጀርባ ስራዎች (የወረፋ ሰራተኛው) እየሰሩ መሆናቸውን እንዲያረጋግጥ የፕላትፎርም አስተዳዳሪዎን ይጠይቁ።',
'Mkg_Guide_Faq_2_Q' => 'ተቀባዮች "Skipped: Email channel disabled" ያሳያሉ።',
'Mkg_Guide_Faq_2_A' => 'በግብይት ቅንብሮች ውስጥ ኢሜይል አንቃን ያብሩ፣ ከዚያ ዘመቻውን እንደገና ይላኩ።',
'Mkg_Guide_Faq_3_Q' => 'ተቀባዮች "No mail server configured" ያሳያሉ።',
'Mkg_Guide_Faq_3_A' => 'የኢሜይል ዘመቻዎች የሚላኩት በራስዎ የሜይል አገልጋይ በኩል ብቻ ነው። በቅንብሮች > የኢሜይል ቅንብሮች ውስጥ ያክሉት።',
'Mkg_Guide_Faq_4_Q' => 'መልእክቱ የደረሳቸው ሰዎች በክፍሌ ውስጥ ካሉት ያነሱ ናቸው።',
'Mkg_Guide_Faq_4_A' => 'የኢሜይል አድራሻ (ኢሜይል) ወይም የስልክ ቁጥር (SMS፣ WhatsApp) የሌላቸው ደንበኞች ይዘለላሉ። ማን እና ለምን እንደተዘለለ ለማየት ዘመቻውን ይክፈቱ።',
'Mkg_Guide_Faq_5_Q' => 'ተልኳል ማለት ደንበኛው ተቀብሎታል ማለት ነው?',
'Mkg_Guide_Faq_5_A' => 'ተልኳል ማለት የሜይል አገልጋይዎ ወይም ጌትዌይዎ መልእክቱን ተቀብሏል ማለት ነው። ወደ ገቢ ሳጥን መድረሱ፣ መከፈቱ እና የአይፈለጌ መልእክት ማጣሪያ አይከታተሉም።',
'Mkg_Guide_Faq_6_Q' => 'ዘመቻን ከላክሁ በኋላ ማርትዕ እችላለሁ?',
'Mkg_Guide_Faq_6_A' => 'አይችሉም። በመላክ ላይ ያሉና የተላኩ ዘመቻዎች ተቆልፈዋል፤ በምትኩ አዲስ ዘመቻ ይፍጠሩ።',
'Mkg_Guide_Faq_7_Q' => 'የWhatsApp መልእክቶቼ እየደረሱ አይደሉም።',
'Mkg_Guide_Faq_7_A' => 'ደንበኛ ለመጨረሻ ጊዜ ከጻፈልዎ 24 ሰዓት በላይ ካለፈ፣ WhatsApp በMeta የጸደቁ አብነቶችን ብቻ ያደርሳል። WhatsApp Cloud API ይጠቀሙ እና በዘመቻው ውስጥ የጸደቀ አብነት ይምረጡ።',
'Mkg_Guide_Faq_8_Q' => 'ዘመቻን እንደገና ብልክ ደንበኞች ሁለት ጊዜ ይደርሳቸዋል?',
'Mkg_Guide_Faq_8_A' => 'የተጣበቀን ዘመቻ መቀጠል የሚልከው አሁንም በመጠባበቅ ላይ ላሉ ተቀባዮች ብቻ ነው፣ ስለዚህ አስቀድሞ የደረሰው ማንም እንደገና መልእክት አይላክለትም። ያልተሳካ ዘመቻን እንደገና መላክ በአዲስ ዝርዝር ከመጀመሪያው ይጀምራል።',

// POS Devices (card terminals / fiscal registers — Ingenico IDE280)
'Pd_Pos_Devices' => 'የPOS መሳሪያዎች',
