'Pd_Line_Locked' => 'ይህ መስመር በመሳሪያው ላይ ተከፍሏል። ለመቀየር መጀመሪያ ክፍያውን ይሰርዙ።',
'Pd_Needs_Online' => 'የካርድ ተርሚናል ክፍያዎች የኢንተርኔት ግንኙነት ይፈልጋሉ።',
'Pd_Device_Error' => 'መሳሪያውን መድረስ አልተቻለም።',
'Pd_Void_Charge' => 'ክፍያውን ሰርዝ',
'Pd_Void_Charge_Confirm' => 'በመሳሪያው ላይ የ{amount} የካርድ ክፍያውን ይሰርዙ?',
'Pd_Void_Before_Close' => 'በመሳሪያው ላይ የካርድ ክፍያ አስቀድሞ ተወስዷል። ሰርዘው ይዝጉ?',
'Pd_Installments' => 'የክፍፍል ክፍያዎች',
'Pd_Single_Payment' => 'የአንድ ጊዜ ክፍያ',
'Pd_Guide_How_Title' => 'እንዴት እንደሚሰራ',
'Pd_Guide_How_Intro' => 'የPOS መሳሪያ ከመሸጫው አጠገብ ያለ የካርድ ተርሚናል ወይም የፊስካል ካሽ ሬጂስተር ነው። Stocky መጠኑን ይልክለታል፣ ደንበኛው እስኪከፍል ይጠብቃል፣ እና ክፍያውን የሚመዘግበው መሳሪያው ካጸደቀው በኋላ ብቻ ነው።',
'Pd_Guide_Step_1' => 'መሳሪያውን እዚህ ያክሉ፦ ሞዴል፣ መጋዘን፣ እና የካርድ ክፍያዎቹ የሚመዘገቡበት የክፍያ ዘዴ (ለምሳሌ "ክሬዲት ካርድ")።',
'Pd_Guide_Step_2' => 'Stocky እንዴት እንደሚደርሰው ይምረጡ፦ በካሽየሩ ኮምፒውተር ላይ ያለ የአካባቢ ብሪጅ፣ ወይም የአቅራቢዎ ክላውድ API። ከባንክዎ ወይም ከአቅራቢዎ የተገኙትን መታወቂያዎችና ቁልፎች ያስገቡ።',
'Pd_Guide_Step_3' => 'ግንኙነት ሞክርን ይጫኑ። የብሪጅ መሳሪያዎች መሞከር ያለባቸው ብሪጁ ከሚሰራበት የካሽየር ኮምፒውተር ነው።',
'Pd_Guide_Step_4' => 'በPOS ላይ ያንን የክፍያ ዘዴ ይምረጡ፣ "በመሳሪያው ላይ አስከፍል" ይጫኑ እና ደንበኛው እንዲከፍል ያድርጉ። መሳሪያው ካጸደቀ በኋላ ሽያጩ ሊጠናቀቅ ይችላል።',
'Pd_Guide_Step_5' => 'ያለ ሽያጭ የተወሰዱ የካርድ ክፍያዎችን (ለምሳሌ የተተወ ክፍያ) በልውውጦች ውስጥ ይፈትሹ እና ይሰርዟቸው ወይም ገንዘቡን ይመልሱ።',
'Pd_Guide_Bridge_Text' => 'በካሽየሩ ኮምፒውተር ላይ በአቅራቢ SDK ለሚንቀሳቀሱ መሳሪያዎች (USB፣ serial ወይም LAN ማጣመር)። አሳሹ SDKውን በቀጥታ መጠቀም ስለማይችል፣ ትንሽ የብሪጅ ፕሮግራም ይጠቀልለዋል እና በዚህ ኮምፒውተር ላይ ያዳምጣል።',
'Pd_Guide_Bridge_Point_1' => 'POS እያንዳንዱን ጥያቄ ከካሽየሩ አሳሽ ወደ ብሪጅ URL ይልካል፤ የStocky አገልጋይ የሱቅዎን ኔትወርክ መድረስ በፍጹም አያስፈልገውም።',
'Pd_Guide_Bridge_Point_2' => 'ጥያቄዎችና ምላሾች በጋራ ሚስጥሩ ይፈረማሉ፣ ስለዚህ ማጽደቅ ከአሳሹ ሊጭበረበር አይችልም።',
'Pd_Guide_Bridge_Point_3' => 'በዚህ መሳሪያ የካርድ ክፍያ በሚቀበል በእያንዳንዱ ኮምፒውተር ላይ ብሪጁን ይጫኑና ያስጀምሩ።',
'Pd_Guide_Cloud_Text' => 'መሳሪያውን በኢንተርኔት ለሚደርሱ አቅራቢዎች። የStocky አገልጋይ APIውን ይጠራል፣ ስለዚህ በካሽየሩ ኮምፒውተር ላይ ምንም መጫን አያስፈልግም።',
'Pd_Guide_Cloud_Point_1' => 'የAPI URL በይፋዊ አድራሻ ላይ https:// መሆን አለበት።',
'Pd_Guide_Cloud_Point_2' => 'ደንበኛው በሚከፍልበት ጊዜ Stocky በየ2 ሰከንዱ ሁኔታውን ይጠይቃል፣ ስለዚህ የሁኔታ endpointው ክፍያውን በማጣቀሻው ማወቅ አለበት፤ ካርዱ ከመጠናቀቁ በፊት APIው ምላሽ ከሰጠ ("pending")፣ ጥያቄው መደጋገሙ ውጤቱን ይወስናል።',
'Pd_Guide_Ide280_Title' => 'Ingenico IDE280',
'Pd_Guide_Ide280_Text' => 'IDE280 የካርድ አንባቢ ያለው አዲስ ትውልድ የፊስካል ካሽ ሬጂስተር (YN ÖKC) ነው። አብዛኛውን ጊዜ የሚዋሃደው በIngenico ECR / GMP3 SDK፣ ወይም በባንክዎ የውህደት አገልግሎት በኩል ነው።',
'Pd_Guide_Ide280_Point_1' => 'በIngenico / ባንክ ሰነድ እንደተገለጸው መሳሪያውን ከካሽየሩ ኮምፒውተር ጋር ያጣምሩ፣ ከዚያ ብሪጁን (ወይም የAPI ቅንብሮችን) ወደ እሱ ያመልክቱ።',
'Pd_Guide_Ide280_Point_2' => 'መጠኖች በአስርዮሽም በkuruşም (amount_minor) ይላካሉ፣ በምንዛሪ TRY / 949።',
'Pd_Guide_Ide280_Point_3' => 'በ"ሙሉ የፊስካል ደረሰኝ"፣ እያንዳንዱ እቃ የVAT መጠኑን የመሳሪያ ክፍል ይይዛል — የVAT ክፍሎቹን መሳሪያው ከተዋቀረበት ጋር ያዛምዱ።',
'Pd_Guide_Protocol_Title' => 'የብሪጅ / API ስምምነት',
'Pd_Guide_Protocol_Intro' => 'Stocky ከብሪጁ ወይም ከAPIው ጋር በJSON ይነጋገራል። ከታች ያሉት ዱካዎች ነባሪዎቹ ናቸው እና በእያንዳንዱ መሳሪያ የላቀ ክፍል ስር ሊቀየሩ ይችላሉ።',
'Pd_Guide_Operation' => 'ተግባር',
'Pd_Guide_Default_Endpoint' => 'ነባሪ endpoint',
'Pd_Guide_When' => 'መቼ',
'Pd_Guide_When_Ping' => 'የግንኙነት ሞክር ቁልፍ።',
'Pd_Guide_When_Sale' => 'ካሽየሩ "በመሳሪያው ላይ አስከፍል" ሲጫን። ካርዱ ሲጠናቀቅ፣ ወይም ወዲያውኑ በ"pending" ሁኔታ ምላሽ ሊሰጥ ይችላል።',
'Pd_Guide_When_Status' => 'ክፍያው በመጠባበቅ ላይ እያለ በየ2 ሰከንዱ።',
'Pd_Guide_When_Cancel' => 'ካሽየሩ ካርዱን እየጠበቀ ሲያቋርጥ።',
'Pd_Guide_When_Void' => 'ክፍያን መሰረዝ (በዚያው ቀን፣ ሙሉ መጠን)።',
'Pd_Guide_When_Refund' => 'የክፍያውን ከፊል ወይም ሙሉ ገንዘብ መመለስ።',
'Pd_Guide_Request_Title' => 'ጥያቄ',
'Pd_Guide_Request_Text' => 'Stocky ለሽያጭ የሚልከው አካል። ተመላሽ ገንዘብና ስረዛ የመጀመሪያውን ክፍያ እንደ "original" ይይዛሉ።',
'Pd_Guide_Response_Title' => 'ምላሽ',
'Pd_Guide_Response_Text' => 'የመስክ ስሞች በተለዋዋጭ ሁኔታ ይነበባሉ (በ"data" ስርም)፤ "status" ወይም response_code "00" ውጤቱን ይወስናል። የካርድ ቁጥሮች ተሸፍነው ይቀመጣሉ።',
'Pd_Guide_Signing_Title' => 'ፊርማ (ብሪጅ)',
'Pd_Guide_Signing_Text' => 'ብሪጁ የStockyን ፊርማ ማረጋገጥ አለበት፣ እና ትክክለኛውን የምላሽ አካሉን መፈረምና "reference" እና "operation" ሁለቱንም መልሶ ማስተጋባት አለበት — ያልተፈረሙ ምላሾች፣ ወይም ስለ ሌላ ተግባር የሆኑ ምላሾች ውድቅ ይደረጋሉ።',
'Pd_Guide_Browser_Title' => 'የአሳሽ መዳረሻ (ብሪጅ)',
'Pd_Guide_Browser_Text' => 'የPOS ገጹ ብሪጁን ከአሳሹ ይጠራል፣ ስለዚህ ብሪጁ እነዚህን የCORS ራስጌዎች (የOPTIONS preflightን ጨምሮ) መመለስ አለበት።',
'Pd_Guide_Safety_Title' => 'ማወቅ የሚገባዎ',
'Pd_Guide_Safety_1' => 'ሽያጭ የሚቀመጠው ለተመሳሳይ መጠን የጸደቀ የመሳሪያ ክፍያ ሲኖር ብቻ ነው፤ አንድ የመሳሪያ ክፍያ በፍጹም ሁለት ሽያጮችን ሊከፍል አይችልም።',
'Pd_Guide_Safety_2' => 'ካርድ ከተከፈለ በኋላ የክፍያ መስኮቱን መዝጋት መጀመሪያ ያንን ክፍያ ይሰርዛል።',
'Pd_Guide_Safety_3' => 'መሳሪያው በጊዜው ምላሽ ካልሰጠ ክፍያው "ምላሽ የለም" ሆኖ ይታያል፦ መሳሪያውን ይፈትሹ፣ እና ካርዱ ከተከፈለ ክፍያውን ከልውውጦች ይሰርዙ።',
'Pd_Guide_Safety_4' => 'እዚህ ያሉ ተመላሽ ገንዘቦችና ስረዛዎች ገንዘብን በካርዱ ላይ ብቻ ያንቀሳቅሳሉ፤ ሽያጩን አይቀይሩም። የተመለሱ እቃዎችን በሽያጭ መመለሻዎች ውስጥ ይመዝግቡ።',
'Perm_Pos_Terminals_Manage' => 'የPOS መሳሪያዎች፦ ማስተዳደር፣ ገንዘብ መመለስ እና መሰረዝ',
'Perm_Pos_Terminals_Transactions' => 'የPOS መሳሪያዎች፦ ልውውጦችን ማየት',
'Pd_Check_Again' => 'እንደገና አረጋግጥ',
