'Cd_Dns_Txt_Note' => 'የCNAME ወይም የA ሪከርዱ ገና እየተሰራጨ እያለ ባለቤትነትዎን ያረጋግጣል።',
'Cd_Dns_Ip_Unknown' => 'የሰርቨሩን IP አድራሻ የፕላትፎርሙን አስተዳዳሪ ይጠይቁ።',
'Cd_Ssl_Hint' => 'ከማረጋገጫው በኋላ የፕላትፎርሙ ቡድን ለዶሜይንዎ የHTTPS ሰርተፊኬት ይጭናል። የመቆለፊያ ምልክቱ መስራት ሲጀምር የSSL ምልክቱ በራሱ ንቁ ይሆናል (በየሰዓቱ እና አረጋግጥን በተጫኑ ቁጥር ይፈተሻል)። ከአንድ ቀን በኋላም አልተሳካም ካሳየ ድጋፍ ሰጪውን ያግኙ።',
'Cd_Err_invalid' => 'እንደ shop.example.com ያለ ትክክለኛ የዶሜይን ስም ያስገቡ።',
