'Cd_Err_duplicate' => 'ይህ ዶሜይን አስቀድሞ በጥቅም ላይ ነው።',
'Cd_Err_limit_reached' => 'እቅድዎ የሚፈቅደውን የብጁ ዶሜይኖች ብዛት ደርሰዋል።',
