'Cd_Err_lookup_failed' => 'የDNS ፍለጋ አልተሳካም። ትንሽ ቆይተው እንደገና ይሞክሩ።',
'Cd_Err_unknown' => 'ማረጋገጫው አልተሳካም። እባክዎ የDNS ቅንብሮችን ያረጋግጡ።',
