'Cd_Guide_Title' => 'እንዴት እንደሚሰራ',
'Cd_Guide_1' => 'የእርስዎ የሆነውን ዶሜይን ያክሉ፣ ለምሳሌ shop.example.com።',
'Cd_Guide_2' => 'በዶሜይን አቅራቢዎ (GoDaddy፣ Namecheap፣ Cloudflare...) ይግቡ እና የሚታየውን የDNS ሪከርድ ይፍጠሩ።',
'Cd_Guide_3' => 'ተመልሰው DNS አረጋግጥን ይጫኑ። ከተረጋገጠ በኋላ የስራ ቦታዎ፣ የመስመር ላይ ሱቅዎ እና የደንበኛ ፖርታልዎ በዚያ ዶሜይን ላይ ይከፈታሉ።',
'Cd_Guide_4' => 'የፕላትፎርሙ ንዑስ ዶሜይንዎ ከብጁ ዶሜይኑ ጋር አብሮ መስራቱን ይቀጥላል።',
'Cd_Cloudflare_Note' => 'የCloudflare ተጠቃሚዎች: ማረጋገጫው እስኪጠናቀቅ ድረስ ሪከርዱን DNS only (ግራጫ ደመና) ያድርጉት።',
'Perm_custom_domains' => 'ብጁ ዶሜይን (ቅንብሮች > ብጁ ዶሜይን)',
'List_Too_Big_All' => 'ይህ ዝርዝር ከ{count} በላይ ረድፎች ስላሉት የሁሉም አማራጭ ተዘግቷል። በአንድ ገጽ 100 ረድፎች እየታዩ ነው። ለማጥበብ ፍለጋ ወይም ማጣሪያዎችን ይጠቀሙ።',
'List_Too_Big_Export' => 'ይህ ዝርዝር ከ{count} በላይ ረድፎች አሉት፣ ይህም በአንድ ጊዜ ወደ ውጭ ለመላክ በጣም ብዙ ነው። ለማጥበብ ፍለጋ ወይም ማጣሪያዎችን ይጠቀሙ።',
'PartiallyPaid' => 'በከፊል የተከፈለ',
'Ord_Guide_PayAuto_Tip' => 'በሽያጩ ላይ ክፍያዎች ሲመዘገቡ በራሱ ይዘመናል። ክፍያ እንዴት እንደሚመዘገብ ለማየት ይጫኑ።',
'Ord_Guide_PayAuto_Intro' => 'ይህ አምድ ከትዕዛዙ ምን ያህሉ እንደተከፈለ ያሳያል። በደንበኛው የክፍያ ምርጫ ይጀምራል፣ ከዚያም ትዕዛዙን ማረጋገጥ በሚፈጥረው ሽያጭ ላይ ክፍያዎች ሲመዘገቡ በራሱ ይዘመናል። ከዚህ ገጽ ሊስተካከል አይችልም።',
'Ord_Guide_PayAuto_Paid' => 'ሙሉ መጠኑ ተቀብሏል። ደንበኛው በክፍያ መግቢያ (gateway) በመስመር ላይ ከከፈለ፣ ትዕዛዙን ማረጋገጥ ሽያጩን እንደ ተከፍሏል ይፈጥራል እና ክፍያውን ይመዘግብልዎታል። አለበለዚያ በሽያጩ ላይ ያሉት ክፍያዎች ጠቅላላውን ሲሸፍኑ ሁኔታው ወደ ተከፍሏል ይቀየራል።',
'Ord_Guide_PayAuto_Partial' => 'በሽያጩ ላይ ክፍያ ተመዝግቧል፣ ነገር ግን ከጠቅላላው የተወሰነው ገና አልተከፈለም።',
'Ord_Guide_PayAuto_Pending' => 'እስካሁን ምንም ክፍያ አልተቀበለም: በማድረስ ጊዜ ክፍያ፣ የባንክ ዝውውር ወይም ሌላ በኋላ የመክፈያ ዘዴ። ትዕዛዙን ማረጋገጥ ሽያጩን እንደ አልተከፈለም ይፈጥራል፣ ስለዚህ ገንዘቡን ሲሰበስቡ እርስዎ ራስዎ ይመዘግባሉ። ከታች ያሉትን ደረጃዎች ይመልከቱ።',
'Ord_Guide_PayAuto_Note' => 'እዚህ የሚታየው የክፍያ ሁኔታ ሽያጩን ይከተላል: ክፍያ ሲያስቀምጡ በራሱ ወደ በከፊል የተከፈለ ወይም ተከፍሏል ይቀየራል፣ አንዱን ከሰረዙ ደግሞ ወደ ቀድሞው ይመለሳል። ሽያጩ የሂሳብ መዝገቡ ነው፣ የክፍያ እና የትርፍ ሪፖርቶችዎንም የሚመግበው እሱ ነው። ያስገቡትን ለመገምገም ወይም ለማስተካከል በሽያጩ ላይ ክፍያዎችን አሳይን ይጠቀሙ።',
