'Ord_LinkedSale_Missing' => 'ከዚህ ትዕዛዝ ጋር የተያያዘ ሽያጭ የለም። ሽያጩ ተሰርዞ ሊሆን ይችላል፣ ወይም ትዕዛዙ የተረጋገጠው ትዕዛዞች ከሽያጮች ጋር መያያዝ ከመጀመራቸው በፊት ነው።',
