'Oc_Order_Statuses_Help' => 'እያንዳንዱ የOpenCart ሁኔታ እዚህ ምን ማለት እንደሆነ። እነዚህ ከሱቅዎ ተወስደው የተሞሉ ናቸው፣ መቀየር የሚያስፈልጋቸው ብጁ ሁኔታዎችን ከተጠቀሙ ብቻ ነው።',
