'Oc_Variants_Linked' => 'የተያያዙ ተለዋዋጮች',
'Oc_Push_Desc' => 'የጎደሉ ምርቶችን እና ተለዋዋጮችን በOpenCart ውስጥ ይፈጥራል፣ በተያያዙት ላይ ደግሞ ስም፣ ዋጋ፣ ሁኔታ እና ክምችትን ያዘምናል። መግለጫዎች፣ ምስሎች እና ምድቦች የሚሞሉት ምርቱ አዲስ ሲሆን ወይም ምንም ከሌለው ብቻ ነው፣ ስለዚህ በOpenCart የተጻፈ ጽሑፍ እንዳለ ይቆያል።',
'Oc_Pull_Desc' => 'የOpenCart ምርቶችን ያስመጣል፣ ያሉትን በሞዴል ወይም በSKU ያዛምዳል፣ የቀሩትንም ይፈጥራል። የተያያዙ ምርቶች ስማቸውን እና ዋጋቸውን ከOpenCart ይወስዳሉ።',
'Oc_Pull_Stock' => 'ለአዳዲስ ምርቶች የOpenCart ብዛቶችን እንደ መነሻ ክምችት ተጠቀም',
'Oc_Reset_Confirm' => 'የምርት ትስስሮች እንደገና ይጀመሩ? የትዕዛዝ ታሪክ ትስስሮቹን እንደያዘ ይቆያል።',
'Oc_Stock_Desc' => 'የእያንዳንዱን የተያያዘ ምርት እና ተለዋዋጭ የሱቅ ብዛት እዚህ ካለው ክምችት ጋር እኩል ያደርጋል።',
'Oc_Orders_Desc' => 'የሱቅ ትዕዛዞችን እንደ ሽያጮች ያስመጣል (እንደ {ref} ያሉ ማጣቀሻዎች)። ቀድሞ የገቡ ትዕዛዞች ሁኔታቸው እና ክፍያቸው ብቻ ይዘመናል፣ ስለዚህ እንደገና መሳብ ችግር የለውም።',
'Oc_Orders_Since' => 'ከዚህ ቀን ጀምሮ ያሉ ትዕዛዞች',
'Oc_Guide_1' => 'በግንኙነት ትር ላይ የ{company} Connectorን ያውርዱ።',
'Oc_Guide_2' => 'በOpenCart አስተዳዳሪ ገጽዎ ፋይሉን በ{installer} ስር ይስቀሉ እና Install ን ይጫኑ፣ ከዚያም ሞጁሉን በ{modules} ስር ይጫኑ።',
'Oc_Guide_3' => 'የ{name} ሞጁልን ይክፈቱ፣ ከዚያም የሱቁን URL እና ሚስጥራዊ ቁልፉን ይቅዱ።',
'Oc_Guide_4' => 'በግንኙነት ትር ላይ ይለጥፏቸው፣ ያስቀምጡ እና {test} ን ያስኪዱ። ይህ ሱቁ አዳዲስ ትዕዛዞችን የት እንደሚልክ ጭምር ያሳውቀዋል።',
'Oc_Guide_5' => 'ምርቶችን ያዘጋጁ: ሱቁ አስቀድሞ ካታሎግ ካለው ይሳቡ፣ {company} ካለው ደግሞ ይግፉ። በራስ-ሰር ክምችት ላይ ከመተማመንዎ በፊት ይህንን ያድርጉ፣ ምክንያቱም {company} የክምችት አሃዞች ምንጭ ይሆናል።',
'Oc_Guide_6' => 'ታሪክ ከፈለጉ የቅርብ ጊዜ ትዕዛዞችን አንድ ጊዜ ይሳቡ። ከዚያ በኋላ ትዕዛዞች በራሳቸው ይደርሳሉ።',
'Oc_Identity_Title' => 'ምርቶች በሞዴል እና በSKU ይዛመዳሉ',
'Oc_Identity_Desc' => 'እዚህ ያለው የምርት ኮድ ከOpenCart ሞዴል እና SKU ጋር ይዛመዳል። በሁለቱም በኩል አንድ አድርገው ያቆዩዋቸው። እዚህ ያለው ክምችት ዋናው አሃዝ ነው: ከእያንዳንዱ ትዕዛዝ በኋላ ሱቁ ከዚህ ይዘመናል።',
'Oc_Options_Title' => 'ተለዋዋጭ የሌላቸው አማራጮች',
'Oc_Options_Desc' => 'የOpenCart ተለዋዋጮች የራሳቸው ክምችት አላቸው፣ እዚህም ከተለዋዋጮች ጋር ይዛመዳሉ። ተለዋዋጮች ሳይፈጠሩለት አማራጮች ብቻ ያሉት ምርት እንደ አንድ ምርት ይገባል፣ ክምችቱም በአማራጭ አይከፋፈልም።',
'Oc_Cancel_Title' => 'የተሰረዙ ትዕዛዞች',
'Oc_Cancel_Desc' => 'በOpenCart ውስጥ ትዕዛዝን መሰረዝ እዚህ ያለውን ሽያጩን ይቀለብሳል። ሽያጩ አስቀድሞ ደርሶ ከሆነ ወይም መመለሻ ካለው ምንም አይቀለበስም: እርስዎ እንዲገመግሙት ሽያጩ በማስታወሻዎቹ እና በመዝገቦቹ ውስጥ ምልክት ይደረግበታል።',
'Oc_Download_Connector_3' => 'ለOpenCart 3 አውርድ',
'Oc_Opencart3_Title' => 'OpenCart 3 ሱቆች',
'Oc_Opencart3_Desc' => 'OpenCart 3 የራሱ ተለዋዋጮች የሉትም፣ አማራጮች ብቻ ናቸው። አንድ አማራጭ (ለምሳሌ መጠን) ያለው ምርት በእያንዳንዱ የአማራጭ እሴት ክምችት ይመሳሰላል፣ ይህም እዚህ ካሉት ተለዋዋጮች ጋር ይዛመዳል። በርካታ አማራጮች ያሉት ምርት አማራጮቹ ለእያንዳንዱ ጥምረት ክምችት ሳይኖራቸው ይፈጠራሉ: ክምችቱ በምርቱ ላይ በአጠቃላይ ይያዛል፣ የሽያጭ መስመሮቹም በምርቱ ላይ ይመዘገባሉ።',
