'Oc_G_I_5' => 'እዚህ ተመልሰው በግንኙነት ትር ላይ ይለጥፏቸው፣ ያስቀምጡ እና {test} ን ያስኪዱ። ይህ ሱቁ የትዕዛዝ ማሳወቂያዎችን የት እንደሚልክ ጭምር ያሳውቀዋል።',
'Oc_G_Requirements' => 'ሱቁ የሚያስፈልገው',
'Oc_G_Requirements_Desc' => 'OpenCart 3.0 ወይም 4.0 እና ከዚያ በላይ፣ PHP ከcURL ጋር (በማንኛውም ሆስት ላይ መደበኛ ነው)፣ እና ከኢንተርኔት የሚደረስ የሱቅ አድራሻ። ሱቁ በግል ኔትወርክ ላይ ከሆነ፣ ይህ የስራ ቦታ ሱቁን መድረስ እስከቻለ ድረስ ትዕዛዞች በየጥቂት ደቂቃዎች በሚካሄደው ፍተሻ አማካኝነት ይደርሳሉ።',
'Oc_G_First_Title' => 'የመጀመሪያው ማመሳሰል',
'Oc_G_First_Shop_Has' => 'ሱቁ አስቀድሞ ካታሎጉ አለው',
'Oc_G_First_Shop_Has_Text' => 'በምርቶች ትር ላይ ምርቶችን ይሳቡ። ምርቶች በሞዴል ወይም በSKU ከምርት ኮዶችዎ ጋር ይዛመዳሉ፣ ከጎደሉም ይፈጠራሉ፤ የሱቁን ብዛቶች እንደ መነሻ ክምችት ለመውሰድ የክምችት አማራጩን ምልክት ያድርጉ።',
'Oc_G_First_Company_Has' => 'ካታሎጉ በ{company} ውስጥ አለ',
'Oc_G_First_Company_Has_Text' => 'ምርቶችን ይግፉ። የጎደሉ ምርቶች ከክምችታቸው ጋር በሱቁ ውስጥ ይፈጠራሉ፤ ያሉት ደግሞ በሞዴል ወይም በSKU ተያይዘው ይዘመናሉ።',
'Oc_G_First_Both' => 'በሁለቱም በኩል ምርቶች አሉ',
'Oc_G_First_Both_Text' => 'ያሉት የሱቅ ምርቶች እንዳይባዙ እና እንዲያያዙ መጀመሪያ ይሳቡ፣ ከዚያም ሱቁ የሌለውን ለመፍጠር ይግፉ። የምርት ኮዶችን እና ሞዴሎችን በሁለቱም በኩል አንድ አድርገው ያቆዩ።',
'Oc_G_Stock_Master' => 'የክምችት አሃዙን የሚይዘው {company} ነው',
'Oc_G_Stock_Master_Desc' => 'ከመጀመሪያው ማመሳሰል በኋላ በሱቁ ውስጥ ያለው ብዛት ሁልጊዜ ከ{company} ይጻፋል። በOpenCart ውስጥ ብዛትን ማስተካከል ዘላቂ ውጤት የለውም: ቀጣዩ እንቅስቃሴ ወይም የሰዓቱ ፍተሻ ይተካዋል።',
'Oc_G_How_Title' => 'እንዴት እንደሚሰራ',
'Oc_G_T_Products' => 'ምርቶች',
'Oc_G_Products_1' => 'ምርት እዚህ ባለው ኮዱ በሱቁ ውስጥ ካለው ሞዴል እና SKU ጋር ይዛመዳል። ትስስሩ ይታወሳል፣ ስለዚህ በኋላ የምርቱን ስም መቀየር አያበላሸውም።',
'Oc_G_Products_2' => '{company} ምርትን ሲገፋ ሞዴሉን፣ SKUን፣ ስሙን፣ ዋጋውን፣ ሁኔታውን እና ክምችቱን ያስቀምጣል። መግለጫው፣ ምስሉ እና ምድቡ የሚጻፉት ምርቱ በሱቁ ውስጥ አዲስ ሲሆን ወይም ምንም ከሌለው ብቻ ነው፣ ስለዚህ በOpenCart የተጻፈ ጽሑፍ እንዳለ ይቆያል።',
'Oc_G_Products_3' => 'ከመስመር ላይ ሱቁ የተደበቀ ወይም እዚህ ለሽያጭ ያልቀረበ ምርት በሱቁ ውስጥ አይፈጠርም፤ አስቀድሞ የተያያዘ ከሆነ ይልቁንስ እዚያ እንዲሰናከል ይደረጋል።',
'Oc_G_T_Variants' => 'ተለዋዋጮች እና አማራጮች',
'Oc_G_Variants_4' => 'OpenCart 4 እውነተኛ ተለዋዋጮች አሉት (የቀለም እና የመጠን ምርጫዎች ያሉት ምርት)፣ እያንዳንዱም የራሱ ክምችት አለው። በሁለቱም አቅጣጫ ከተለዋዋጮችዎ ጋር ይዛመዳሉ፣ እያንዳንዱም በራሱ ሞዴል ይዛመዳል።',
'Oc_G_Variants_3' => 'OpenCart 3 ተለዋዋጮች የሉትም፣ አማራጮች እና በእያንዳንዱ የአማራጭ እሴት ክምችት ብቻ ነው ያለው። አንድ አማራጭ (ለምሳሌ መጠን) ያለው ምርት በእያንዳንዱ እሴት ክምችት ይመሳሰላል፣ ይህም ከተለዋዋጮችዎ ጋር ይዛመዳል። በርካታ አማራጮች ያሉት ምርት አማራጮቹ ለእያንዳንዱ ጥምረት ክምችት ሳይኖራቸው ይፈጠራሉ: ክምችቱ በምርቱ ላይ በአጠቃላይ ይቆያል፣ የሽያጭ መስመሮቹም በምርቱ ላይ ይመዘገባሉ።',
'Oc_G_Variants_Multi' => 'ተለዋዋጮች ሳይፈጠሩለት አማራጮች ብቻ ያሉት የሱቅ ምርት እንደ አንድ ምርት ይገባል፤ ይህም በመዝገቦቹ ውስጥ ይጠቀሳል።',
'Oc_G_T_Stock' => 'ክምችት',
'Oc_G_Stock_1' => 'የክምችት ማብሪያው በርቶ እያለ እዚህ ያለ እያንዳንዱ እንቅስቃሴ (ሽያጭ፣ መመለሻ፣ ግዢ፣ ማስተካከያ፣ ዝውውር) ገጹ ምላሽ ከሰጠ በኋላ በሰከንዶች ውስጥ ሱቁን ያዘምናል፣ ስለዚህ ካሽየሩ ሱቁን በጭራሽ አይጠብቅም።',
'Oc_G_Stock_2' => 'በሰዓት አንድ ጊዜ እያንዳንዱ የተያያዘ ምርት ተፈትሾ ይስተካከላል፣ ይህም የቀጥታ ግፊቱ ማየት የማይችላቸውን የጅምላ ለውጦች ይሸፍናል። የክምችት ትሩ ሲጠየቅ ሁሉንም ይገፋል።',
'Oc_G_Stock_3' => 'አገልግሎቶች፣ ሁልጊዜ በክምችት ያሉ ተብለው የተመደቡ ምርቶች እና ክፍሎቻቸው ገደብ የሌላቸው ጥምር ምርቶች በሱቁ ውስጥ ሁልጊዜ እንደሚገኙ ሆነው ይታያሉ። ያንን መጋዘን ብቻ ለመቁጠር በግንኙነት ትር ላይ መጋዘን ይምረጡ፤ አለበለዚያ ሁሉም መጋዘኖች ይደመራሉ።',
'Oc_G_T_Orders' => 'ትዕዛዞች እና ሁኔታዎች',
'Oc_G_Orders_1' => 'አዲስ ወይም የተቀየረ ትዕዛዝ በሱቁ ወዲያውኑ ይታወጃል እና በተፈረመው ግንኙነት በኩል እንደገና ይነበባል፣ ስለዚህ በማሳወቂያው ውስጥ ያለ ምንም ነገር ታማኝ ተደርጎ አይወሰድም። በየጥቂት ደቂቃዎች አንድ ፍተሻ ማሳወቂያ ያመለጠውን ሁሉ ይስባል። እያንዳንዱ ትዕዛዝ OC-<order number> የሚል ማጣቀሻ ያለው አንድ ሽያጭ ይሆናል፤ ደንበኛው በኢሜይል ይዛመዳል ወይም ይፈጠራል።',
'Oc_G_Col_List' => 'የሁኔታ ዝርዝር',
'Oc_G_Col_Meaning' => 'እዚህ የሚያደርገው',
'Oc_G_Col_Default' => 'ከሱቅዎ የተሞላ',
'Oc_G_Default_Commit' => 'በOpenCart ውስጥ ክምችት የሚቀንሱት ሁኔታዎች (በነባሪ Pending፣ Processing፣ Shipped፣ Complete)',
'Oc_G_Default_Paid' => 'Processing, Processed, Shipped, Complete',
'Oc_G_Default_Cancel' => 'Canceled, Denied, Failed, Refunded, Reversed, Chargeback, Expired, Voided',
'Oc_G_Orders_2' => 'ዝርዝሮቹ በመጀመሪያው ግንኙነት ከሱቅዎ ይሞላሉ፣ በግንኙነት ትር ላይም ሊቀየሩ ይችላሉ። ሁለቱም ወገኖች በተመሳሳይ ደረጃ ክምችት እንዲያንቀሳቅሱ የመጀመሪያውን ዝርዝር በOpenCart ውስጥ ክምችት ከሚቀንሱት ሁኔታዎች ጋር አንድ አድርገው ያቆዩ።',
'Oc_G_Orders_3' => 'ከምንም ምርት ጋር የማይዛመድ ዕቃ ያለው ትዕዛዝ በይደር ይያዛል፣ ምርቱም በሱቁ ውስጥ ካለ ከሱቁ ይገባል። በይደር የተያዙ ትዕዛዞች በእያንዳንዱ መርሃ-ግብር ፍተሻ እንደገና ይሞከራሉ፤ ከአስራ ሁለት ሙከራዎች በኋላ ተመዝግበው በእጅ እንዲስቡአቸው ይተዋሉ።',
'Oc_G_T_Cancel' => 'ስረዛዎች እና ተመላሽ ገንዘቦች',
'Oc_G_Cancel_1' => 'ትዕዛዝ በሱቁ ውስጥ የተሰረዘ ሁኔታ ላይ ሲደርስ እዚህ ያለው ሽያጩ ይቀለበሳል: ክምችቱ ይመለሳል፣ ክፍያዎቹ ይወገዳሉ እና ሽያጩ ይሰረዛል፤ ልክ በሽያጮች ገጽ ላይ መሰረዝ እንደሚያደርገው።',
'Oc_G_Cancel_2' => 'አስቀድሞ የደረሰ፣ መመለሻ ያለው ወይም በግብር ባለሥልጣን ተቀባይነት ያገኘ ሽያጭ በሱቁ በጭራሽ አይቀለበስም። እርስዎ እንዲገመግሙት በማስታወሻዎቹ እና በመዝገቦቹ ውስጥ ምልክት ይደረግበታል።',
'Oc_G_Cancel_3' => 'ትዕዛዙ ከዚያ በኋላ በሱቁ ውስጥ ከተመለሰ እንደ አዲስ ሽያጭ እንደገና ይገባል።',
'Oc_G_T_Automation' => 'የአውቶሜሽን ማብሪያዎች',
'Oc_G_Auto_1' => 'ትዕዛዞችን በራስ-ሰር አስመጣ: የትዕዛዝ ማሳወቂያዎች እና መርሃ-ግብር ፍተሻው። ሲጠፋ ትዕዛዞች የሚደርሱት በትዕዛዞች ትር ላይ ሲስቡአቸው ብቻ ነው።',
'Oc_G_Auto_2' => 'ክምችትን በራስ-ሰር ግፋ: የቀጥታ የክምችት ዝመናዎች እና የሰዓቱ ፍተሻ። ሲጠፋ ሱቁ የሚቀየረው ክምችትን በእጅ ሲገፉ ብቻ ነው።',
'Oc_G_Auto_3' => 'የምርት ለውጦችን በራስ-ሰር ግፋ: እዚህ የተፈጠረ ወይም የተስተካከለ ምርት ሱቁን ወዲያውኑ ያዘምናል። ሲጠፋ የምርቶች ትርን ይጠቀሙ።',
'Oc_G_T_Faq' => 'ጥያቄዎች',
'Oc_G_Q_Secret' => 'ግንኙነትን ይፈትሹ ሚስጥራዊ ቁልፉ አይዛመድም ይላል',
'Oc_G_A_Secret' => 'በOpenCart ውስጥ የ{company} Connector ሞጁልን ይክፈቱ እና ሚስጥራዊ ቁልፉን እንደገና ይቅዱ፤ እንደገና የተጫነ ሞጁል አዲስ ቁልፍ ያገኛል። ከመፈተሽዎ በፊት በግንኙነት ትር ላይ ይለጥፉት እና ያስቀምጡ።',
'Oc_G_Q_Clock' => 'ግንኙነትን ይፈትሹ የሱቁ ሰዓት በጣም የተለየ ነው ይላል',
'Oc_G_A_Clock' => 'የተፈረሙ ጥያቄዎች ሰዓቱን ይይዛሉ፣ ሁለቱ ሰዓቶች ከአምስት ደቂቃ በላይ ሲለያዩም ውድቅ ይደረጋሉ። በሱቁ ሰርቨር ላይ ቀኑን እና ሰዓቱን ያስተካክሉ።',
'Oc_G_Q_Redirect' => 'ግንኙነትን ይፈትሹ ሱቁ ወደ ሌላ አድራሻ ያዞራል ይላል',
'Oc_G_A_Redirect' => 'ሱቅዎ በሌላ አድራሻ ምላሽ ይሰጣል፣ ብዙውን ጊዜ ከhttp ይልቅ https ወይም ከwww ጋር። በመልዕክቱ ውስጥ የሚታየውን አድራሻ እንደ ሱቁ URL ይጠቀሙ።',
'Oc_G_Q_Not_Answering' => 'ግንኙነትን ይፈትሹ ኮኔክተሩ ምላሽ አልሰጠም ይላል',
'Oc_G_A_Not_Answering' => 'አድራሻው የOpenCart ሱቅ አይደለም፣ ወይም ሞጁሉ አልተጫነም ወይም ተሰናክሏል። የሱቁን URL ያረጋግጡ፣ ከዚያም የ{company} Connector በExtensions → Modules ስር እንደተጫነ እና እንደነቃ መታየቱን ያረጋግጡ።',
'Oc_G_Q_No_Orders' => 'ትዕዛዞች በሱቁ ውስጥ ይቀርባሉ ነገር ግን ለመታየት ደቂቃዎች ይወስዳሉ',
'Oc_G_A_No_Orders' => 'ሱቁ ይህንን የስራ ቦታ መድረስ አይችልም፣ ስለዚህ ትዕዛዞች የሚደርሱት በመርሃ-ግብር ፍተሻው ብቻ ነው። በሞጁሉ ገጽ ላይ ያለውን የ{company} አድራሻ ይመልከቱ: ከሱቁ ሰርቨር የሚደረስ መሆን አለበት። ግንኙነትን ይፈትሹን ማስኬድ እንደገና ያስመዘግበዋል።',
'Oc_G_Q_Stock_Wrong' => 'በሱቁ ውስጥ ያለ ብዛት የተሳሳተ ነው',
'Oc_G_A_Stock_Wrong' => 'በክምችት ትር ላይ ክምችትን ይግፉ፣ ይህም እያንዳንዱን የተያያዘ ምርት እዚህ ካሉት አሃዞች እንደገና ይጽፋል። መዛባቱ ከቀጠለ የክምችት ማብሪያው መብራቱን እና ማንም በOpenCart ውስጥ ብዛቶችን እያስተካከለ አለመሆኑን ያረጋግጡ።',
'Oc_G_Q_Out_Of_Stock' => 'እዚህ ክምችት ቢኖርም አንድ ምርት በሱቁ ውስጥ ከክምችት ውጭ ሆኖ ይታያል',
'Oc_G_A_Out_Of_Stock' => 'በOpenCart 3 በርካታ አማራጮች ያሉት ምርት ክምችቱን በምርቱ ላይ በአጠቃላይ ይይዛል፤ ከአማራጮቹ ይልቅ በሱቁ ውስጥ ያለውን የምርቱን ብዛት ያረጋግጡ። ለማንኛውም ምርት ክምችትን አንድ ጊዜ ይግፉ እና የዚያን ምርት መዝገቦች ይመልከቱ።',
'Oc_G_Q_Held' => 'መዝገቦቹ አንድ ትዕዛዝ በይደር ተይዟል ይላሉ',
'Oc_G_A_Held' => 'ከዕቃዎቹ አንዱ እዚህ ካለ ምንም ምርት ጋር አይዛመድም እና ከሱቁ ሊገባ አልቻለም፣ ብዙውን ጊዜ ምርቱ እዚያ ስለተሰረዘ። ምርቱን ይፍጠሩ ወይም ያያይዙ፣ ከዚያም በትዕዛዞች ትር ላይ ትዕዛዞችን ይሳቡ።',
'Oc_G_Q_Deleted_Sale' => 'የገባ ሽያጭ ሰረዝኩ እና ተመልሶ መጣ',
'Oc_G_A_Deleted_Sale' => 'ትዕዛዙ በሱቁ ውስጥ ንቁ እስከሆነ ድረስ ቀጣዩ ማሳወቂያ ወይም ፍተሻ እንደገና ያስገባዋል። ይልቁንስ ትዕዛዙን በሱቁ ውስጥ ይሰርዙ፣ ይህም እዚህ ያለውን ሽያጩን ይቀለብሳል።',
'Oc_G_Q_Uninstall' => 'ሱቁን እንዴት አለያየዋለሁ?',
'Oc_G_A_Uninstall' => 'በግንኙነት ትር ላይ ማመሳሰሉን ያጥፉ፤ ጠፍቶ እያለ ምንም ነገር አይንቀሳቀስም። ውህደቱን ከሱቁ ለማስወገድ የ{company} Connectorን በExtensions → Modules ስር ያራግፉ (Uninstall)።',
'Oc_Full_Guide' => 'ሙሉ መመሪያውን ክፈት',
'Comm_Receipt_Account_Hint' => 'ይህ ክፍያ የሚወጣበት የጥሬ ገንዘብ ወይም የባንክ መለያ። ቀሪ ሂሳቡ በመጠኑ ልክ ይቀንሳል፣ የሂሳብ መዝገቡም የሽያጭ ኮሚሽን ወጪን (Sales Commission Expense) በእሱ ላይ ይመዘግባል።',
'Comm_G_Q_Ledger' => 'የኮሚሽን ክፍያ በሂሳቦቹ ላይ ምን ያደርጋል?',
'Comm_G_A_Ledger' => 'ደረሰኝ ሲፈጥሩ እና መለያ ሲመርጡ የዚያ መለያ ቀሪ ሂሳብ በደረሰኙ መጠን ይቀንሳል፣ አውቶማቲክ ጆርናሎች በርተው ከሆነም ጆርናል ይመዘገባል: ዴቢት የሽያጭ ኮሚሽን ወጪ (Sales Commission Expense, 5200-COMM)፣ ክሬዲት የተመረጠው የጥሬ ገንዘብ ወይም የባንክ መለያ። ምንም መለያ ካልተመረጠ ክሬዲቱ ወደ ነባሪው የጥሬ ገንዘብ መለያ (Cash) ይሄዳል፣ ምንም ቀሪ ሂሳብም አይቀየርም።',
'Hide_Zero_Decimals' => 'ዜሮ አስርዮሾችን ደብቅ',
'Sys_Hide_Zero_Decimals_Help' => 'ሙሉ ቁጥር የሆኑ መጠኖችን ያለ አስርዮሽ አሳይ: 100.00 100 ይሆናል፣ 100.50 ግን አስርዮሹን ይይዛል። ለማሳያ ብቻ ነው፤ የተቀመጡ እሴቶች እና ስሌቶች አይቀየሩም።',
