'Oc_Code_Source' => 'የምርት ኮድ ምንጭ',
'Oc_Code_Source_Help' => 'የትኛው የOpenCart መስክ እዚህ የምርት ኮድ እንደሆነ። Model በOpenCart ውስጥ ግዴታ ስለሆነ አንዳንድ ሱቆች ምድብን ወይም የምርት አይነትን ያስገቡበታል፣ እውነተኛውን የዕቃ ኮድ ደግሞ በSKU፣ ISBN፣ UPC፣ EAN፣ JAN ወይም MPN ውስጥ ያስቀምጣሉ፤ ለእንደዚህ አይነት ሱቅ ያንን መስክ ይምረጡ። የተመረጠው መስክ ባዶ ሲሆን መጀመሪያ ሞዴሉ፣ ከዚያም SKU ጥቅም ላይ ይውላሉ። ለሚሳቡ ምርቶች፣ ለማዛመድ እና ለመግፋት ይሠራል።',
