'Oc_Connector_Link_Help' => 'የድረ-ገጽዎ አድራሻ። OpenCart በExtensions > Installer ገጽ ላይ የኮኔክተሩን ስም ከእሱ ጋር ያገናኛል። የዚህን የ{company} የስራ ቦታ አድራሻ ለመጠቀም ባዶ ይተዉት።',
