'Oc_L_D_Options' => 'አማራጮች ያሏቸው ነገር ግን ተለዋዋጭ የሌላቸው ምርቶች (ክምችቱ በምርት ይያዛል)',
'Oc_L_D_Unmatched' => 'እዚህ ካለ ምንም ምርት ጋር የማይዛመዱ የትዕዛዝ ዕቃዎች',
'Oc_L_D_Store_Total' => 'በሱቁ ውስጥ ያሉ ምርቶች',
