'Oc_L_D_Order' => 'የOpenCart ትዕዛዝ',
'Oc_L_D_Sale' => 'ሽያጭ',
'Oc_L_D_Product_Ids' => 'በወረፋ ያሉ ምርቶች',
'Oc_L_D_Stock_Ids' => 'በወረፋ ያሉ የክምችት ለውጦች',
'Oc_L_D_Id' => 'መለያ ቁጥር (ID)',
'Oc_L_D_Error' => 'ስህተት',
'Oc_L_Act_products_pull' => 'የምርቶች መሳብ',
'Oc_L_Act_products_push' => 'የምርቶች መግፋት',
