'Oc_L_Act_orders_reverse' => 'ትዕዛዝ ተሰርዟል',
'Oc_L_Act_orders_review' => 'ትዕዛዝ መገምገም ያስፈልገዋል',
'Oc_L_Act_webhook_order' => 'የትዕዛዝ ማሳወቂያ',
'Oc_L_Act_auto_sync' => 'ራስ-ሰር ማመሳሰል',
'Oc_L_Act_connect_test' => 'የግንኙነት ሙከራ',
'Oc_L_Act_scheduled' => 'መርሃ-ግብር ማመሳሰል',
'Oc_L_Act_sync' => 'ማመሳሰል',
'Oc_L_H_Secret' => 'እዚህ የተቀመጠው ሚስጥራዊ ቁልፍ በOpenCart ውስጥ ካለው የኮኔክተር ሞጁል ቁልፍ ጋር አንድ አይደለም፣ ስለዚህ ሱቁ ሁሉንም ጥሪዎች ውድቅ ያደርጋል።',
'Oc_L_F_Secret' => 'በOpenCart ውስጥ Extensions → Modules → ኮኔክተሩን ይክፈቱ፣ እዚያ የሚታየውን ሚስጥራዊ ቁልፍ ይቅዱ፣ በግንኙነት ትር ላይ ይለጥፉት እና ያስቀምጡ። ሞጁሉን እንደገና መጫን አዲስ ሚስጥራዊ ቁልፍ ይፈጥራል።',
'Oc_L_H_Clock' => 'የOpenCart ሰርቨር ሰዓት ከእኛው በጣም ይለያል፣ ስለዚህ የተፈረሙ ጥያቄዎች ጊዜያቸው ያለፈ ይመስላሉ።',
'Oc_L_F_Clock' => 'የሆስቲንግ አቅራቢውን የሰርቨሩን ሰዓት (NTP) እንዲያስተካክል ይጠይቁ። የጥቂት ደቂቃዎች ልዩነት ግንኙነቱን ለማገድ በቂ ነው።',
'Oc_L_H_Disabled' => 'የኮኔክተር ሞጁሉ በOpenCart ውስጥ ተጭኗል ነገር ግን ጠፍቷል።',
'Oc_L_F_Disabled' => 'በOpenCart ውስጥ Extensions → Modules → ኮኔክተሩን ይክፈቱ እና Status ን ወደ Enabled ያድርጉት።',
'Oc_L_H_Unreachable' => 'ሱቁ በተቀመጠው አድራሻ ምላሽ አልሰጠም፣ ወይም የኮኔክተር ሞጁሉ እዚያ አልተጫነም።',
'Oc_L_F_Unreachable' => 'ሱቁ መስመር ላይ መሆኑን ለማረጋገጥ የሱቁን URL በአሳሽ ይክፈቱ፣ የኮኔክተር ሞጁሉ መጫኑን እና መንቃቱን ያረጋግጡ፣ እና ምንም ፋየርዎል ወይም የጥገና ሁኔታ ሰርቨራችንን እንደማያግድ ያረጋግጡ።',
'Oc_L_H_Redirect' => 'ሱቁ ጎብኚዎችን ወደ ሌላ አድራሻ ይልካል (ለምሳሌ ከhttp ወደ https ወይም ወደ www)።',
'Oc_L_F_Redirect' => 'በመልዕክቱ ውስጥ የተጠቀሰውን አድራሻ በግንኙነት ትር ላይ እንደ ሱቁ URL ያስቀምጡ።',
'Oc_L_H_Not_Configured' => 'የሱቁ URL ወይም ሚስጥራዊ ቁልፉ ይጎድላል፣ ስለዚህ እስካሁን ምንም ሊላክ አይችልም።',
'Oc_L_F_Not_Configured' => 'በግንኙነት ትር ላይ የሱቁን URL እና ሚስጥራዊ ቁልፉን ይሙሉ፣ ያስቀምጡ እና ግንኙነትን ይፈትሹን ያስኪዱ።',
'Oc_L_H_Model_Taken' => 'ወደ ሱቁ የተገፋ ምርት ሌላ የሱቅ ምርት ወይም ከተለዋዋጮቹ አንዱ አስቀድሞ እንደ ሞዴል የሚጠቀምበት ኮድ አለው።',
'Oc_L_F_Model_Taken' => 'ከሁለቱ ምርቶች በአንዱ ላይ ኮዱን ይቀይሩ፣ ወይም ያለው የሱቅ ምርት እንደገና ከመፈጠር ይልቅ እንዲያያዝ መጀመሪያ ምርቶችን ይሳቡ።',
'Oc_L_H_Model_Missing' => 'ወደ ሱቁ የተገፋ ምርት ኮድ ወይም ስም የለውም። OpenCart ሁለቱንም ይፈልጋል።',
'Oc_L_F_Model_Missing' => 'እዚህ ለምርቱ ኮድ እና ስም ይስጡት፣ ከዚያም እንደገና ይግፉ።',
'Oc_L_H_Held' => 'ትዕዛዝ ደርሷል ነገር ግን አንዳንድ ዕቃዎቹ እዚህ ካለ ምንም ምርት ጋር አይዛመዱም፣ ስለዚህ በመጠባበቅ ላይ ነው፤ ምንም ሽያጭም አልተፈጠረም።',
'Oc_L_F_Held' => 'የጎደሉትን ምርቶች ይፍጠሩ ወይም ይሳቡ (ዕቃዎቹ ከታች ተዘርዝረዋል)፣ ከዚያም ትዕዛዞችን እንደገና ይሳቡ። በይደር የተያዙ ትዕዛዞች ጥቂት ጊዜ በራስ-ሰር እንደገና ይሞከራሉ።',
'Oc_L_H_Given_Up' => 'ትዕዛዝ ከበርካታ ሙከራዎች በኋላ ሊገባ አልቻለም፣ ከአሁን በኋላም እንደገና አይሞከርም።',
'Oc_L_F_Given_Up' => 'ምርቶቹ እዚህ መኖራቸውን ያረጋግጡ፣ ከዚያም ከትዕዛዙ በፊት ያለ ቀን በመምረጥ ከትዕዛዞች ትር ትዕዛዞችን በእጅ ይሳቡ።',
'Oc_L_H_Review' => 'እዚህ ያለው ሽያጭ ከደረሰ ወይም ከተመለሰ በኋላ ትዕዛዙ በOpenCart ውስጥ ተሰርዟል፣ ስለዚህ ክምችቱ በራስ-ሰር አልተቀለበሰም።',
'Oc_L_F_Review' => 'ሽያጩን ይክፈቱ እና ዕቃዎቹን መመለስ ወይም እንዳለ መተው ይወስኑ።',
'Oc_L_H_Reversed' => 'ትዕዛዝ በOpenCart ውስጥ ተሰርዟል፣ እዚህ ያለው ተዛማጅ ሽያጭም ተቀልብሶ ክምችቱ ተመልሷል።',
'Oc_L_H_Backlog' => 'መርሃ-ግብር የትዕዛዝ መሳቡ በአንድ ዙር ከሚያስተናግደው በላይ ትዕዛዞችን አግኝቷል፤ በሚቀጥለው ጊዜ እንደገና ይጀምራል።',
'Oc_L_F_Backlog' => 'የተከማቹትን ለማጽዳት ከትዕዛዞች ትር ትዕዛዞችን በእጅ ይሳቡ።',
'Oc_L_H_Paused' => 'ሱቁ ምላሽ መስጠት ስላቆመ አውቶማቲክ ግፊቶች ለተወሰነ ጊዜ ቆመዋል። በመሃል የተደረጉ ለውጦች ሱቁ እንደገና ምላሽ ሲሰጥ ይላካሉ።',
'Oc_L_F_Paused' => 'ሱቁ መስመር ላይ መሆኑን ያረጋግጡ። ሌላ ምንም አያስፈልግም፤ ወረፋው በራሱ ይቀጥላል።',
'Oc_L_H_Busy' => 'ሁለት አውቶማቲክ ግፊቶች ተደራርበው አንዱ ቦታ ለቋል። ምንም የጠፋ ነገር የለም።',
'Oc_L_H_Codes_Suffixed' => 'አንዳንድ የተሳቡ ምርቶች ሌላ የሱቅ ምርት እዚህ አስቀድሞ የያዘውን ኮድ ይዘዋል፣ ብዙውን ጊዜ የተመረጠው የኮድ መስክ ባዶ ስለሆነ ወይም የምድብ ስም ስለያዘ። ሁለት ምርቶች እንዳይዋሃዱ የOpenCart id ተጨምሮላቸው ተፈጥረዋል።',
'Oc_L_F_Codes_Suffixed' => 'ከታች ለተዘረዘሩት ምርቶች በOpenCart ውስጥ የኮድ መስኩን (Model፣ SKU፣ ISBN…) ይሙሉ፣ ወይም በግንኙነት ትር ላይ ሌላ የምርት ኮድ ምንጭ ይምረጡ፣ ከዚያም የምርት ትስስሮችን እንደገና ያስጀምሩ እና እንደገና ይሳቡ።',
'Oc_L_H_Options' => 'አንዳንድ የሱቅ ምርቶች ያለ ተለዋዋጭ ክምችት አማራጮች (መጠን፣ ቀለም…) አሏቸው፣ ስለዚህ ክምችቱ ለምርቱ በአጠቃላይ ይከታተላል።',
'Oc_L_F_Options' => 'ምንም አያስፈልግም። ክምችትን በአማራጭ ለመከታተል በOpenCart 4 ውስጥ እነዚያን አማራጮች ወደ ተለዋዋጮች ይቀይሩ፣ ወይም በOpenCart 3 ውስጥ ለእያንዳንዱ ምርት አንድ አማራጭ ይጠቀሙ።',
'Oc_L_H_Pull_Ok' => 'ይህ የምርቶች ገጽ ከሱቁ ተነቧል። ተፈጥሯል ማለት እዚህ አዲስ ምርት ማለት ነው፤ ተዘምኗል ማለት አስቀድሞ የነበረ እና የተያያዘ ማለት ነው።',
'Oc_L_H_Pull_Failed' => 'በዚህ ገጽ ላይ ያሉ አንዳንድ ምርቶች እዚህ ሊቀመጡ አልቻሉም፤ እያንዳንዱ ከምክንያቱ ጋር ከታች ተዘርዝሯል።',
'Oc_L_F_Pull_Failed' => 'የተዘረዘሩትን ምርቶች በOpenCart ውስጥ ያስተካክሉ (የጎደለ ስም ወይም ኮድ የተለመደው ምክንያት ነው) እና እንደገና ይሳቡ። የሚነኩት ያልተሳኩት ብቻ ናቸው።',
'Oc_L_H_Push_Warnings' => 'ምርቶች ወደ ሱቁ ተልከዋል፣ ነገር ግን ሱቁ በአንዳንዶቹ ላይ ችግሮችን አሳውቋል፣ ለምሳሌ ማውረድ ያልቻለው ምስል።',
'Oc_L_F_Push_Warnings' => 'ከታች ያለውን ዝርዝር ያንብቡ። ምስሎች ከሱቁ ሰርቨር የሚደረሱ መሆን አለባቸው፤ ሌላው ሁሉ እንደተላከ ተቀምጧል።',
'Oc_L_H_Missing_Remote' => 'ክምችት ተገፍቷል፣ ነገር ግን አንዳንድ የተያያዙ ምርቶች ከአሁን በኋላ በሱቁ ውስጥ የሉም።',
'Oc_L_F_Missing_Remote' => 'በሱቁ ውስጥ እንደገና ለመፍጠር ምርቶችን ይግፉ፣ ወይም ሆን ተብለው ከተሰረዙ የምርት ትስስሮችን እንደገና ያስጀምሩ።',
'Oc_L_H_Generic' => 'አንድ የማመሳሰል ደረጃ አልተሳካም። ከላይ ያለው መልዕክት የሱቁ ወይም የሰርቨሩ የራሱ ምክንያት ነው።',
'Oc_L_F_Generic' => 'በግንኙነት ትር ላይ ግንኙነትን ይፈትሹን ያስኪዱ። ካለፈ ደረጃውን እንደገና ይሞክሩ፤ ካልተሳካ የሚሰጠውን ፍንጭ ይከተሉ።',
'Oc_L_H_Code_Fallback' => 'በዚህ ገጽ ላይ ያሉ አንዳንድ ምርቶች እንደ የምርት ኮድ ምንጭ በተመረጠው መስክ ውስጥ እሴት ሳይኖራቸው ደርሰዋል፣ ስለዚህ ሞዴላቸው (ብዙውን ጊዜ የምድብ ስም) እንደ ኮድ ጥቅም ላይ ውሏል።',
'Oc_L_F_Code_Fallback' => 'ከታች "እያንዳንዱን መስክ የያዙ ምርቶች" የሚለውን ይመልከቱ። ሱቁ እነዚያ እሴቶች እያሉት የተመረጠው መስክ 0 ካሳየ፣ ሱቁ በሌላ የመለያ ስም ይይዛቸዋል፤ አንድ የተዘረዘረ ምርትን በOpenCart ውስጥ ይክፈቱ (Data ትር፣ Product Codes) እና የሚያሳየውን ይላኩልን። አለበለዚያ ለተዘረዘሩት ምርቶች በOpenCart ውስጥ መስኩን ይሙሉ እና እንደገና ይሳቡ።',
'Oc_L_H_Old_Connector' => 'ሱቁ አሁንም ከ1.1.0 የቆየ ኮኔክተር እያሄደ ነው፣ ይህም Model እና SKU ብቻ ይልካል፣ ስለዚህ የተመረጠው የኮድ መስክ በጭራሽ አይደርስም፣ ሞዴሉም ጥቅም ላይ ውሏል።',
