'Warehouse_Prices_Enabled_Help' => 'ለአንድ ምርት በእያንዳንዱ መጋዘን (ሱቅ) የራሱን ዋጋ፣ የጅምላ ዋጋ እና ዝቅተኛ ዋጋ ይስጡት። POS፣ ሽያጮች፣ የዋጋ ማቅረቢያዎች እና የባርኮድ መለያዎች የተመረጠውን መጋዘን ዋጋ ይጠቀማሉ። የመስመር ላይ ሱቁ እና የቻናል ማመሳሰሎች መደበኛውን ዋጋ ይይዛሉ፣ አስቀድሞ የተመዘገቡ ሽያጮችም አይቀየሩም።',
