'LicK_Rotate_Confirm' => 'አሁንም አሮጌውን ይፋዊ ቁልፍ የያዘ ሶፍትዌር አዲሱን ይፋዊ ቁልፍ እስኪልኩለት ድረስ በአዲሱ ቁልፍ የተፈረመ እያንዳንዱን ምላሽ ውድቅ ያደርጋል። ይቀጥሉ?',
'LicK_Rotated' => 'አዲስ የመፈረሚያ ቁልፍ ተፈጥሯል።',
'LicK_Api_Guide' => 'የፈቃድ API መመሪያ',
'LicK_G_Endpoints' => 'Endpoints (የመዳረሻ ነጥቦች)',
'LicK_G_Activate' => 'ቁልፉን ከዚህ ዶሜይን ወይም መሳሪያ ጋር ያስራል። አንድ ማግበር ይጠቀማል።',
'LicK_G_Validate' => 'ፈቃዱን በዚህ ዶሜይን ወይም መሳሪያ ላይ ያረጋግጣል፣ አዲስ የተፈረመ ምላሽም ይሰጣል።',
'LicK_G_Deactivate' => 'ማግበሩ ሌላ ቦታ ጥቅም ላይ እንዲውል ይህንን ዶሜይን ወይም መሳሪያ ይለቃል። በጭራሽ የአጠቃቀም ፍቃድ አይሰጥም።',
'LicK_G_Status' => 'ምንም ሳይቀይር ፈቃዱን ያነባል። በጭራሽ የአጠቃቀም ፍቃድ አይሰጥም (valid ሁልጊዜ false ነው)።',
'LicK_G_Request' => 'ጥያቄ',
'LicK_G_Request_Help' => 'license_key ያለበት JSON body ይላኩ። product (የምርት ኮዱ) አማራጭ ሲሆን ቁልፉ የምርትዎ መሆኑን ያረጋግጣል። domain ወይም device_id (+ አማራጭ device_name) ይላኩ — ለተቆለፉ ፈቃዶች እና የማግበር ገደብ ላላቸው ፈቃዶች ግዴታ ነው። በእያንዳንዱ ጥሪ የዘፈቀደ nonce ይላኩ እና በtoken ውስጥ ተመልሶ መምጣቱን ያረጋግጡ።',
'LicK_G_Response' => 'ምላሽ',
'LicK_G_Response_Help' => 'valid true የሚሆነው በዚህ ዶሜይን ወይም መሳሪያ ላይ መጠቀምን በሚፈቅድ የactivate / validate ምላሽ ላይ ብቻ ነው። status የፈቃዱን ሁኔታ ይነግራል። ውድቅ የተደረገ ምላሽ error እና message ጭምር አለው። token action፣ key_fingerprint (የቁልፍዎ SHA-256፣ ወደ ትልቅ ፊደል የተቀየረ እና የተከረከመ)፣ identifier፣ nonce እና host ን ይደግማል — ያረጋግጧቸው።',
